private enum WorkspaceScrollTarget {
    static let monitors = "workspace-monitors"
    static let timeline = "workspace-timeline"
}

private enum LeftWorkbenchMode: String, CaseIterable, Identifiable {
    case inspector
    case shorts
    case transcript

    var id: String { rawValue }

    var title: String {
        switch self {
        case .inspector:
            return "Inspector"
        case .shorts:
            return "Shorts"
        case .transcript:
            return "Transcript"
        }
    }

    var icon: String {
        switch self {
        case .inspector:
            return "slider.horizontal.3"
        case .shorts:
            return "rectangle.portrait.on.rectangle.portrait.angled"
        case .transcript:
            return "text.quote"
        }
    }
}

