        }
        .fileImporter(
            isPresented: $isShowingFileImporter,
            allowedContentTypes: [UTType.movie, UTType.video, UTType.audio],
            allowsMultipleSelection: true
        ) { result in
            switch result {
            case .success(let urls):
                for url in urls {
                    // Start accessing security-scoped resource on macOS/iOS
                    _ = url.startAccessingSecurityScopedResource()
                    loadVideoIntoProject(url: url, allowProtectedOriginalProbe: true)
                    // We technically shouldn't stop accessing immediately for AVPlayer, but this is an MVP
                }
            case .failure(let error):
                errorMessage = error.localizedDescription
                showErrorAlert = true
            }
        }
        .fileImporter(
            isPresented: $isShowingRelinkImporter,
            allowedContentTypes: [UTType.movie, UTType.video, UTType.audio],
            allowsMultipleSelection: false
        ) { result in
            defer { relinkingLaneId = nil }
            switch result {
            case .success(let urls):
                guard let url = urls.first, let laneId = relinkingLaneId else { return }
                _ = url.startAccessingSecurityScopedResource()
                relinkLaneMedia(laneId: laneId.uuidString, sourceURL: url)
            case .failure(let error):
                errorMessage = error.localizedDescription
                showErrorAlert = true
            }
        }
        .fileImporter(
            isPresented: $isShowingAttachProxyImporter,
            allowedContentTypes: [UTType.audio, UTType.movie, UTType.video],
            allowsMultipleSelection: false
        ) { result in
            defer { proxyAttachingLaneId = nil }
            switch result {
            case .success(let urls):
                guard let url = urls.first, let laneId = proxyAttachingLaneId else { return }
                _ = url.startAccessingSecurityScopedResource()
                attachProxyToLane(laneId: laneId.uuidString, proxyURL: url)
            case .failure(let error):
                errorMessage = error.localizedDescription
                showErrorAlert = true
            }
        }
        #if os(macOS)
        .fileImporter(
            isPresented: $isShowingExternalMediaAccessImporter,
            allowedContentTypes: [UTType.folder],
            allowsMultipleSelection: false
        ) { result in
            switch result {
            case .success(let urls):
                guard let url = urls.first else { return }
                externalMediaAccess.grantAccess(to: url)
                lastMediaAction = "External media access granted for \(url.lastPathComponent)"
                updateAgentState()
            case .failure(let error):
                errorMessage = error.localizedDescription
                showErrorAlert = true
            }
        }
        #endif
        .alert(isPresented: $showErrorAlert) {
            Alert(title: Text("Error"), message: Text(errorMessage ?? "Unknown error"), dismissButton: .default(Text("OK")))
        }
    }

