            Spacer()

            VStack(spacing: 8) {
                Button("16:9") {
                    playbackEngine.playbackFormat = .horizontal16x9
                    rebuildPlayer()
                }
                .font(.caption2)
                .buttonStyle(.borderedProminent)
                .controlSize(.mini)

                Button("9:16") {
