            .padding(.bottom, 26)
        }
        .padding(.vertical, 12)
        .frame(width: 54)
        #if os(macOS)
        .background(Color(NSColor.controlBackgroundColor))
        #else
        .background(Color(UIColor.secondarySystemBackground))
        #endif
    }
    private var mainWorkspace: some View {
        ZStack {
            studioBackdrop
                .ignoresSafeArea()

            VStack(spacing: 10) {
                studioMasthead

                monitorWall
                    .id(WorkspaceScrollTarget.monitors)

                ScrollViewReader { scrollProxy in
                    ScrollView(.vertical) {
                        VStack(spacing: 12) {
                            productionActionBar
                                .padding(.horizontal)

                            externalStorageOnboardingBanner
                                .padding(.horizontal)

                            NativeTransportControls(
                                playbackEngine: playbackEngine,
                                onPlaybackModeRequest: handlePlaybackModeRequest
                            )
                            .padding(.horizontal)

                            productionDetailsDrawer
                                .padding(.horizontal)

                            timelineToolbar
                                .padding(.horizontal)
                
                            TimelineEditorView(
                                playbackEngine: playbackEngine,
                                projectStore: projectStore,
                                selectedLaneId: selectedLaneId,
                                selectedTagId: selectedTagId,
                                visualReviewBoundaries: visualDecisionBoundariesForTimeline(),
                                focusedSourceReviewBoundaries: sourceDecisionBoundariesForTimeline(laneId: selectedLaneId),
                                onSelectTag: { laneId, tagId in
                                    selectedLaneId = laneId
                                    selectedTagId = tagId
                                },
                                onAddTag: { laneId, tag in
                                    guard var seq = projectStore.activeSequence,
                                          let laneIndex = seq.lanes.firstIndex(where: { $0.id == laneId }) else { return }
                                    seq.lanes[laneIndex].tags.append(tag)
                                    selectedLaneId = laneId
                                    selectedTagId = tag.id
                                    projectStore.updateSequence(seq, undoManager: nil, actionName: "Add Tag")
                                    rebuildPlayer()
                                    scheduleAutosave(reason: "added decision")
                                },
                                onRemoveTag: { laneId, tagId in
                                    guard var seq = projectStore.activeSequence,
                                          let laneIndex = seq.lanes.firstIndex(where: { $0.id == laneId }) else { return }
                                    seq.lanes[laneIndex].tags.removeAll(where: { $0.id == tagId })
                                    if selectedLaneId == laneId && selectedTagId == tagId {
                                        selectedLaneId = nil
                                        selectedTagId = nil
                                    }
                                    projectStore.updateSequence(seq, undoManager: nil, actionName: "Remove Tag")
                                    rebuildPlayer()
                                    scheduleAutosave(reason: "removed decision")
                                },
                                onUpdateTag: { laneId, updatedTag in
                                    guard var seq = projectStore.activeSequence,
                                          let laneIndex = seq.lanes.firstIndex(where: { $0.id == laneId }),
                                          let tagIndex = seq.lanes[laneIndex].tags.firstIndex(where: { $0.id == updatedTag.id }) else { return }
                                    seq.lanes[laneIndex].tags[tagIndex] = updatedTag
                                    selectedLaneId = laneId
                                    selectedTagId = updatedTag.id
                                    projectStore.updateSequence(seq, undoManager: nil, actionName: "Update Tag")
                                    rebuildPlayer()
                                    scheduleAutosave(reason: "updated decision")
                                },
                                onSelectAdjacentDecision: { direction in
                                    jumpToAdjacentDecision(direction: direction, scope: "video")
                                },
                                onSelectReviewBoundary: { boundary in
                                    selectReviewBoundary(boundary)
                                },
                                onZoomChanged: { scale, fitToWindow, label in
                                    lastMediaAction = fitToWindow
                                        ? label
                                        : String(format: "%@ (%.1f px/sec)", label, scale)
                                    updateAgentState()
                                },
                                allowExternalOriginalMedia: false,
                                pixelsPerSecond: $timelinePixelsPerSecond,
                                fitToWindow: $isTimelineFitToWindow
                            )
                            .frame(maxHeight: .infinity)
                            .padding(.horizontal)
                            .id(WorkspaceScrollTarget.timeline)
                
                            Spacer()
                        }
                        .padding(.bottom, 14)
                    }
                    .onChange(of: timelineFocusRequest) { _ in
                        withAnimation(.easeInOut(duration: 0.22)) {
                            scrollProxy.scrollTo(WorkspaceScrollTarget.timeline, anchor: .top)
                        }
                    }
                }
            }
        }
        .onChange(of: monitorFocusRequest) { _ in
            // Monitor Wall is pinned above the scrolling workbench, so focusing it
            // no longer requires a scroll operation. The state update still gives
            // agents a visible acknowledgement via lastMediaAction.
        }
        .onChange(of: projectStore.project) { _ in
            updateAgentState()
        }
        .onChange(of: projectStore.activeSequenceId) { _ in
            requestMonitorFocus(reason: "Focused monitor wall for loaded sequence")
        }
        .onChange(of: playbackEngine.playhead) { newValue in
            enforceSelectedShortPreviewStop(at: newValue)
            guard abs(newValue - lastAgentPlayheadUpdate) >= 0.25 else { return }
            lastAgentPlayheadUpdate = newValue
            updateAgentState()
        }
        .onChange(of: playbackEngine.isPlaying) { _ in
            updateAgentState()
        }
        .onChange(of: agentServer.trigger) { _ in
            handleAgentCommandDispatch(fallbackToLegacy: true)
        }
        .onChange(of: agentServer.commandSerial) { _ in
            handleAgentCommandDispatch(fallbackToLegacy: false)
        }
        .onReceive(Timer.publish(every: 0.5, on: .main, in: .common).autoconnect()) { _ in
            handleAgentCommandDispatch(fallbackToLegacy: false)
        }
        #if os(macOS)
        .onAppear {
            installKeyboardMonitorIfNeeded()
            installProgramScrollMonitorIfNeeded()
            restoreActiveSessionIfPossible()
            if projectStore.activeSequence != nil {
                requestMonitorFocus(reason: "Focused monitor wall on launch")
            } else {
                updateAgentState()
            }
        }
        .onDisappear {
            removeKeyboardMonitor()
            removeProgramScrollMonitor()
        }
        #endif
    }

