    private var publishLedgerPanel: some View {
        let sequence = projectStore.activeSequence
        let records = sequence?.publishReceipts ?? []
        let readyCount = records.filter { $0.publishStatus == "ready-to-upload" }.count
        let scheduledCount = records.filter { $0.publishStatus == "scheduled" }.count
        let uploadedCount = records.filter { $0.publishStatus == "uploaded" }.count
        let publishedCount = records.filter { $0.publishStatus == "published" }.count
        let integrationNeededCount = records.filter { $0.uploadJobStatus == "integration-needed" }.count

        return VStack(alignment: .leading, spacing: 10) {
            HStack(alignment: .top, spacing: 10) {
                Image(systemName: "checklist.checked")
                    .font(.headline)
                    .foregroundStyle(.mint)
                    .frame(width: 30, height: 30)
                    .background(Color.mint.opacity(0.14))
                    .clipShape(Circle())

                VStack(alignment: .leading, spacing: 2) {
                    Text("Publish ledger")
                        .font(.caption)
                        .fontWeight(.bold)
                    Text(records.isEmpty
                         ? "Generate platform records from exported artifacts before upload, scheduling, and receipt work."
                         : publishLedgerSummaryText(recordCount: records.count, readyCount: readyCount, scheduledCount: scheduledCount, uploadedCount: uploadedCount, publishedCount: publishedCount, integrationNeededCount: integrationNeededCount))
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }

                Spacer(minLength: 8)

                Button {
                    generatePublishLedgerFromCurrentDelivery()
                } label: {
                    Label(records.isEmpty ? "Generate ledger" : "Refresh ledger", systemImage: "wand.and.stars")
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.small)
                .disabled(sequence == nil)
                .help("Create or update platform-specific publish records from exported artifacts and the delivery packet.")

                Button {
                    copyPublishLedgerJSON()
                } label: {
                    Label("Copy JSON", systemImage: "doc.on.doc")
                }
                .controlSize(.small)
                .disabled(records.isEmpty)

                Button {
                    generatePublishPacketForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label("Packet", systemImage: "tray.and.arrow.down")
                }
                .controlSize(.small)
                .disabled(records.isEmpty)
                .help("Write a publish handoff packet with ledger JSON plus per-platform metadata, upload job, and checklist files.")

                Button {
                    generatePublishUploadPacketBundleForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label(publishUploadBundleStatus == "generating" ? "Writing Uploads..." : "Upload Bundle", systemImage: "shippingbox")
                }
                .controlSize(.small)
                .disabled(records.isEmpty || publishUploadBundleStatus == "generating")
                .help("Write one upload packet JSON per platform record plus a manifest and README for manual or Codex publishing.")

                Button {
                    generatePublicationCockpitForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label(publicationCockpitStatus == "generating" ? "Writing Cockpit..." : "Cockpit", systemImage: "rectangle.3.group")
                }
                .controlSize(.small)
                .disabled(records.isEmpty || publicationCockpitStatus == "generating")
                .help("Write the human/Codex publication cockpit: core artifacts, top shorts, upload checklist, and receipt commands in one place.")

                Button {
                    runAllBundledPublishConnectorWorkersDryRunFromAgent(values: [:])
                } label: {
                    Label("Dry-run all", systemImage: "play.rectangle.on.rectangle")
                }
                .controlSize(.small)
                .disabled(records.isEmpty || publishConnectorWorkerStatus == "running" || publishConnectorWorkerStatus == "running-all")
                .help("Run every bundled dry-run worker against the current publish ledger. This proves packet safety; it does not upload or publish.")

                Button {
                    prepareFullReleaseForHuman()
                } label: {
                    Label("Full prep", systemImage: "shippingbox.and.arrow.backward")
                }
                .controlSize(.small)
                .disabled(sequence == nil || exportEngine.isExporting)
                .help("Run release prep, then generate the delivery packet, publish ledger, release checklist, and publish packet in one operator flow.")

                Button {
                    generatePodcastPacketForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label(podcastPacketStatus == "generating" ? "Writing Podcast..." : "Podcast Packet", systemImage: "dot.radiowaves.left.and.right")
                }
                .controlSize(.small)
                .disabled(sequence == nil || podcastPacketStatus == "generating")
                .help("Write a Spotify and Apple Podcasts handoff packet for the exported audio master. This does not upload directly; it prepares the RSS/podcast-host handoff.")

                Button {
                    generatePodcastReadyPacketForCurrentManifest()
                } label: {
                    Label("Podcast Ready", systemImage: "checklist.checked")
                }
                .controlSize(.small)
                .disabled(podcastPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty || podcastPacketStatus == "generating" || podcastReadyPacketStatus == "generating")
                .help("Turn the generated podcast manifest into the operator-ready Spotify/Apple handoff folder with copied audio, probe data, CSV, README, and optional zip.")

                Button {
                    generateSocialPublicationQueueForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label(socialPublicationQueueStatus == "generating" ? "Writing Queue..." : "Social Queue", systemImage: "square.grid.3x3.square")
                }
                .controlSize(.small)
                .disabled(sequence == nil || socialPublicationQueueStatus == "generating")
