            }

            publicationMissionControlPanel(records: records)

            if fullReleaseStatus != "idle" || !fullReleaseOutputPath.isEmpty || !fullReleaseErrorMessage.isEmpty {
                fullReleaseStatusRow
            }

            if records.isEmpty {
                HStack(alignment: .top, spacing: 8) {
                    Image(systemName: "arrow.down.doc")
                        .foregroundStyle(.secondary)
                    Text("After release prep exports the episode master, vertical master, shorts, and podcast audio, this ledger becomes the platform work queue for YouTube, Patreon, social, Spotify, and Apple Podcasts.")
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
                .padding(8)
                .background(Color.white.opacity(0.045))
                .clipShape(RoundedRectangle(cornerRadius: 10))
            } else {
                HStack(spacing: 6) {
                    publishStatPill("records", records.count, .mint)
                    publishStatPill("ready", readyCount, .green)
                    publishStatPill("scheduled", scheduledCount, .blue)
                    publishStatPill("uploaded", uploadedCount, .cyan)
                    publishStatPill("published", publishedCount, .yellow)
                    publishStatPill("needs API", integrationNeededCount, .orange)
                }

                publicationReadyHandoffPanel(records: records)
                publishReleaseChecklistPanel(records: records)
                socialPublicationQueuePanel(records: records)
                publishReceiptCapturePanel(records: records)

                if publishConnectorWorkerStatus != "idle" || !publishConnectorWorkerResultJson.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty || !publishConnectorWorkerErrorMessage.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    publishConnectorWorkerStatusRow
                }

                if let selectedReceipt = selectedPublishReceipt(from: records) {
                    publishReceiptEditorPanel(selectedReceipt)
                }

                LazyVGrid(columns: [GridItem(.adaptive(minimum: 255), spacing: 8)], spacing: 8) {
                    ForEach(records.prefix(8), id: \.id) { record in
                        publishReceiptCard(record)
                    }
                }

                Text(publishLedgerNextActionText(records: records))
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)

                if publishPacketStatus != "idle" || !publishPacketOutputPath.isEmpty || !publishPacketErrorMessage.isEmpty {
                    publishPacketStatusRow
                }

                if publishUploadBundleStatus != "idle" || !publishUploadBundleOutputPath.isEmpty || !publishUploadBundleErrorMessage.isEmpty {
                    publishUploadBundleStatusRow
                }

                if publicationCockpitStatus != "idle" || !publicationCockpitOutputPath.isEmpty || !publicationCockpitErrorMessage.isEmpty {
                    publicationCockpitStatusRow
                }
            }

            if podcastPacketStatus != "idle" || !podcastPacketOutputPath.isEmpty || !podcastPacketErrorMessage.isEmpty {
                podcastPacketStatusRow
            }

            if podcastReadyPacketStatus != "idle" || !podcastReadyPacketOutputPath.isEmpty || !podcastReadyPacketErrorMessage.isEmpty {
                podcastReadyPacketStatusRow
            }

            if socialPublicationQueueStatus != "idle" || !socialPublicationQueueOutputPath.isEmpty || !socialPublicationQueueErrorMessage.isEmpty {
                socialPublicationQueueStatusRow
            }
        }
        .padding(9)
        .background(Color.mint.opacity(0.06))
        .overlay(
            RoundedRectangle(cornerRadius: 12)
                .stroke(Color.mint.opacity(0.18), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 12))
