    private func shortRangeSummary(
        for clip: ShortClipCandidate,
        sequenceRange: (start: Double, end: Double, duration: Double)?
    ) -> String {
        if let sequenceRange {
            return String(
                format: "sequence %.2fs - %.2fs | %.2fs",
                sequenceRange.start,
                sequenceRange.end,
                sequenceRange.duration
            )
        }
        return String(format: "sequence %.2fs - %.2fs", clip.startTime, clip.startTime + clip.duration)
    }

    private func shortPacketOriginSummary(
        for clip: ShortClipCandidate,
        sequenceRange: (start: Double, end: Double, duration: Double)?
    ) -> String {
        let origin = clip.sourceLaneId == nil
            ? "episode-spine range"
            : "selected SHOW decision"
        let review = clip.reviewStatus.isEmpty ? "draft" : clip.reviewStatus
        let export = clip.exportStatus.isEmpty ? "not-exported" : clip.exportStatus
        if let sequenceRange {
            return String(
                format: "%@ | %@ | %@ | %.1fs",
                origin,
                review,
                export,
                sequenceRange.duration
            )
        }
        return "\(origin) | \(review) | \(export)"
    }

