                    .foregroundStyle(shortStatusColor(clip.reviewStatus))
                    .padding(.horizontal, 6)
                    .padding(.vertical, 2)
                    .background(shortStatusColor(clip.reviewStatus).opacity(0.14))
                    .clipShape(Capsule())
            }

            VStack(alignment: .leading, spacing: 4) {
                shortEditorLabel("Title")
                TextField("Short title", text: selectedShortTitleBinding)
                    .textFieldStyle(.roundedBorder)
            }

            VStack(alignment: .leading, spacing: 4) {
                shortEditorLabel("Hook")
                TextField("Opening idea or AI hook prompt", text: selectedShortHookBinding)
                    .textFieldStyle(.roundedBorder)
            }

            VStack(alignment: .leading, spacing: 4) {
                shortEditorLabel("Text overlay")
                TextField("Primary on-screen text", text: selectedShortOverlayBinding)
                    .textFieldStyle(.roundedBorder)
            }

            VStack(alignment: .leading, spacing: 4) {
                shortEditorLabel("Caption draft")
                TextEditor(text: selectedShortCaptionBinding)
                    .font(.caption)
                    .frame(minHeight: 56, maxHeight: 72)
                    .scrollContentBackground(.hidden)
                    .background(Color.black.opacity(0.18))
                    .clipShape(RoundedRectangle(cornerRadius: 8))
            }

            VStack(alignment: .leading, spacing: 4) {
                shortEditorLabel("Notes")
                TextEditor(text: selectedShortNotesBinding)
                    .font(.caption)
                    .frame(minHeight: 42, maxHeight: 62)
                    .scrollContentBackground(.hidden)
                    .background(Color.black.opacity(0.18))
                    .clipShape(RoundedRectangle(cornerRadius: 8))
            }

            Picker("Review", selection: selectedShortReviewStatusBinding) {
                Text("Draft").tag("draft")
                Text("Needs captions").tag("needs-captions")
                Text("Ready").tag("ready")
            }
            .pickerStyle(.segmented)
            .labelsHidden()

            Picker("Export", selection: selectedShortExportStatusBinding) {
                Text("Not exported").tag("not-exported")
                Text("Queued").tag("queued")
                Text("Exporting").tag("exporting")
                Text("Exported").tag("exported")
                Text("Failed").tag("export-failed")
            }
            .pickerStyle(.segmented)
            .labelsHidden()

            if let range = selectedShortSequenceRange(clip) {
                VStack(alignment: .leading, spacing: 7) {
                    shortEditorLabel("Short range")
                    Text(String(format: "In %.2fs -> Out %.2fs  |  %.2fs", range.start, range.end, range.duration))
                        .font(.caption2.monospacedDigit())
                        .foregroundStyle(.secondary)
                    HStack(spacing: 6) {
                        Button {
                            previewSelectedShortClip(play: false)
                        } label: {
                            Label("Cue", systemImage: "scope")
                        }
                        .help("Cue the program monitor to this short packet's in point.")

                        Button {
                            previewSelectedShortClip(play: true)
                        } label: {
                            Label("Preview", systemImage: "play.fill")
                        }
                        .help("Preview this short from its in point in 9:16 Play Edit mode.")
                    }
                    .buttonStyle(.bordered)

                    HStack(spacing: 6) {
                        Button("Set In") {
                            setSelectedShortBoundaryFromPlayhead("start")
                        }
                        .help("Set this short's in point to the current shared playhead.")

                        Button("Set Out") {
                            setSelectedShortBoundaryFromPlayhead("end")
                        }
                        .help("Set this short's out point to the current shared playhead.")
                    }
                    .buttonStyle(.bordered)

                    HStack(spacing: 6) {
                        Button("-0.1 In") { nudgeSelectedShortBoundary("start", by: -0.1) }
                        Button("+0.1 In") { nudgeSelectedShortBoundary("start", by: 0.1) }
                        Button("-0.1 Out") { nudgeSelectedShortBoundary("end", by: -0.1) }
                        Button("+0.1 Out") { nudgeSelectedShortBoundary("end", by: 0.1) }
                    }
                    .buttonStyle(.bordered)
                    .font(.caption)
                    .help("Fine tune short in/out without changing source media or the main episode edit.")
                }
                .padding(.horizontal, 7)
                .padding(.vertical, 6)
                .background(Color.black.opacity(0.14))
                .clipShape(RoundedRectangle(cornerRadius: 8))
            }

            Button {
                exportSelectedShortClipForAgent(directoryPath: nil, basename: nil)
            } label: {
                Label(exportEngine.isExporting ? "Exporting..." : "Export 9:16 Short", systemImage: "square.and.arrow.up")
                    .frame(maxWidth: .infinity)
            }
            .buttonStyle(.borderedProminent)
            .disabled(exportEngine.isExporting)
            .help("Render the selected short packet as a 9:16 MP4. This exports from proxy-backed Play Edit metadata; it does not cut source media.")

            if let exportPath = lastExportedShortPath(for: clip) {
                HStack(spacing: 6) {
                    Button {
                        revealShortExport(path: exportPath)
                    } label: {
                        Label("Reveal Export", systemImage: "finder")
                    }
                    Button {
                        copyShortExportPath(exportPath)
                    } label: {
                        Label("Copy Path", systemImage: "doc.on.doc")
                    }
                }
                .buttonStyle(.bordered)
                .font(.caption)
                .help("Open or copy the last exported file path for this short packet.")
            }

            VStack(alignment: .leading, spacing: 5) {
                shortEditorLabel("Destinations")
                ForEach(clip.destinationPresets) { preset in
                    HStack(spacing: 6) {
                        Image(systemName: "paperplane.fill")
                            .font(.caption2)
                            .foregroundStyle(.blue)
                        Text(preset.platform)
                            .font(.caption2)
                            .fontWeight(.semibold)
                            .lineLimit(1)
                        Spacer()
                        Text(preset.status)
                            .font(.caption2)
                            .foregroundStyle(.secondary)
                    }
                    .padding(.horizontal, 7)
                    .padding(.vertical, 4)
                    .background(Color.white.opacity(0.05))
                    .clipShape(RoundedRectangle(cornerRadius: 7))
                }
            }
        }
        .padding(10)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(Color.yellow.opacity(0.08))
        .overlay(
            RoundedRectangle(cornerRadius: 12)
                .stroke(Color.yellow.opacity(0.22), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 12))
    }

    private func shortEditorLabel(_ text: String) -> some View {
        Text(text.uppercased())
            .font(.caption2)
            .fontWeight(.black)
            .tracking(0.7)
            .foregroundStyle(.secondary)
    }

    private func shortStatusColor(_ status: String) -> Color {
        switch status.lowercased() {
        case "ready", "approved":
            return .green
        case "needs-captions", "needs-review":
            return .orange
        case "blocked":
            return .red
        default:
            return .blue
        }
    }

    private var selectedShortTitleBinding: Binding<String> {
        selectedShortStringBinding(\.title)
    }

    private var selectedShortHookBinding: Binding<String> {
        selectedShortStringBinding(\.hookText)
    }

    private var selectedShortOverlayBinding: Binding<String> {
        selectedShortStringBinding(\.primaryOverlayText)
    }

    private var selectedShortCaptionBinding: Binding<String> {
        selectedShortStringBinding(\.captionDraft)
    }

    private var selectedShortNotesBinding: Binding<String> {
        selectedShortStringBinding(\.notes)
    }

    private var selectedShortReviewStatusBinding: Binding<String> {
        selectedShortStringBinding(\.reviewStatus)
    }

    private var selectedShortExportStatusBinding: Binding<String> {
        selectedShortStringBinding(\.exportStatus)
    }

    private func selectedShortStringBinding(_ keyPath: WritableKeyPath<ShortClipCandidate, String>) -> Binding<String> {
        Binding(
            get: {
                selectedShortClipValue()?[keyPath: keyPath] ?? ""
            },
            set: { newValue in
                updateSelectedShortClip { clip in
                    clip[keyPath: keyPath] = newValue
                }
            }
        )
    }

    private func deliveryLaneCard(_ lane: DeliveryLaneReadiness) -> some View {
        let color = deliveryStatusColor(lane.status)
        return VStack(alignment: .leading, spacing: 7) {
            HStack(alignment: .top, spacing: 8) {
                Image(systemName: deliveryStatusIcon(lane.status))
                    .foregroundStyle(color)
                    .frame(width: 22, height: 22)
                    .background(color.opacity(0.12))
                    .clipShape(Circle())
                VStack(alignment: .leading, spacing: 2) {
                    Text(lane.label)
                        .font(.caption)
                        .fontWeight(.bold)
                        .lineLimit(2)
                    Text(lane.artifactType)
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                }
                Spacer()
                Text(deliveryStatusLabel(lane.status))
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(color)
                    .padding(.horizontal, 7)
                    .padding(.vertical, 3)
                    .background(color.opacity(0.12))
                    .clipShape(Capsule())
            }

            Text(lane.summary)
                .font(.caption2)
                .foregroundStyle(.secondary)
                .lineLimit(3)

            if !lane.blocker.isEmpty {
                Text(lane.blocker)
                    .font(.caption2)
                    .foregroundStyle(color)
                    .lineLimit(3)
            }

            HStack(spacing: 5) {
                ForEach(lane.destinations.prefix(4), id: \.self) { destination in
                    Text(destination)
                        .font(.caption2)
                        .fontWeight(.semibold)
                        .foregroundStyle(.secondary)
                        .padding(.horizontal, 6)
                        .padding(.vertical, 2)
                        .background(Color.secondary.opacity(0.08))
                        .clipShape(Capsule())
                }
            }
        }
        .padding(9)
        .background(color.opacity(0.06))
        .overlay(
            RoundedRectangle(cornerRadius: 12)
                .stroke(color.opacity(0.18), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 12))
    }

    private func deliveryStatusColor(_ status: String) -> Color {
        switch status {
        case "ready":
            return .green
        case "blocked":
            return .orange
        case "planned":
            return .blue
        default:
            return .secondary
        }
    }

    private func deliveryStatusIcon(_ status: String) -> String {
        switch status {
        case "ready":
            return "checkmark.seal.fill"
        case "blocked":
            return "exclamationmark.triangle.fill"
        case "planned":
            return "hammer.fill"
        default:
            return "circle.dashed"
        }
    }

    private func deliveryStatusLabel(_ status: String) -> String {
        switch status {
        case "ready":
            return "READY"
        case "blocked":
            return "BLOCKED"
        case "planned":
            return "PLANNED"
        default:
            return status.uppercased()
        }
    }

    private func publishLedgerSummaryText(
        recordCount: Int,
        readyCount: Int,
        scheduledCount: Int,
        uploadedCount: Int,
        publishedCount: Int,
        integrationNeededCount: Int
    ) -> String {
        "\(recordCount) platform record(s): \(readyCount) ready, \(scheduledCount) scheduled, \(uploadedCount) uploaded, \(publishedCount) published, \(integrationNeededCount) waiting for direct API integration."
    }

    private func publishStatPill(_ label: String, _ value: Int, _ color: Color) -> some View {
        VStack(spacing: 1) {
            Text("\(value)")
                .font(.caption.monospacedDigit())
                .fontWeight(.black)
            Text(label.uppercased())
                .font(.caption2)
                .fontWeight(.black)
                .tracking(0.4)
        }
        .foregroundStyle(color)
        .padding(.horizontal, 7)
        .padding(.vertical, 5)
        .background(color.opacity(0.10))
        .clipShape(RoundedRectangle(cornerRadius: 9))
    }

    private func publicationMissionControlPanel(records: [PublishReceiptRecord]) -> some View {
        let episodeRecord = records.first { $0.deliveryLaneId == "episode-16x9-master" }
        let episodeReady = episodeRecord.map { publishRecordArtifactReady($0) && publishRecordCopyReady($0) } ?? false
        let episodeReceiptCaptured = episodeRecord.map { publishRecordReceiptCaptured($0) } ?? false
        let socialReady = socialMasterQueueClipCount > 0 && socialMasterQueueStatus == "loaded"
        let podcastReady = podcastReadyPacketStatus == "generated"
            && !podcastReadyPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && FileManager.default.fileExists(atPath: podcastReadyPacketOutputPath)
        let receiptSummary = publicationReceiptCompletionSummary(for: projectStore.activeSequence)
        let publicationComplete = receiptSummary["publicationComplete"] as? Bool ?? false
        let captured = receiptSummary["receiptCapturedCount"] as? Int ?? 0
        let remaining = receiptSummary["receiptRemainingCount"] as? Int ?? records.count
        let total = receiptSummary["receiptTotalCount"] as? Int ?? records.count
        let readyLaneCount = [episodeReady, socialReady, podcastReady].filter { $0 }.count
        let releaseFolderPath = currentPublicationReleaseFolderPath()
        let headline = projectStore.activeSequence == nil
            ? "Load an episode session before publishing."
            : (records.isEmpty
                ? "Run Full prep to create the release queue."
                : (publicationComplete
                    ? "Publication proof is complete."
                    : (readyLaneCount == 3
                        ? "Ready to post or schedule. Capture receipts as you go."
                        : "Finish the missing handoff artifacts before platform posting.")))

        return VStack(alignment: .leading, spacing: 9) {
            HStack(alignment: .top, spacing: 10) {
                Image(systemName: "dot.scope")
                    .font(.headline)
                    .foregroundStyle(.yellow)
                    .frame(width: 30, height: 30)
                    .background(Color.yellow.opacity(0.14))
                    .clipShape(Circle())

                VStack(alignment: .leading, spacing: 2) {
                    Text("Publication mission control")
                        .font(.caption)
                        .fontWeight(.black)
                    Text(headline)
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }

                Spacer(minLength: 8)

                HStack(spacing: 6) {
                    publishStatPill("lanes ready", readyLaneCount, readyLaneCount == 3 ? .green : .yellow)
                    publishStatPill("receipts", captured, publicationComplete ? .green : .orange)
                    publishStatPill("missing", remaining, remaining == 0 ? .green : .red)
                }

                Button {
                    copyPublicationMissionControlJSON()
                } label: {
                    Label("Copy mission", systemImage: "doc.on.doc")
                }
                .controlSize(.small)
                .help("Copy the full read-only mission control JSON for Codex, another agent, or a manual publishing handoff.")
            }

            HStack(spacing: 7) {
                Button {
                    revealPublicationArtifactPath(releaseFolderPath, label: "current release folder")
                } label: {
                    Label("Reveal release", systemImage: "folder")
                }
                .controlSize(.small)
                .disabled(releaseFolderPath.isEmpty || !FileManager.default.fileExists(atPath: releaseFolderPath))
                .help("Reveal the best available release handoff folder: full release folder first, then cockpit/upload/publish packet folders.")

                Button {
                    copyMissingPublicationReceipts(records)
                } label: {
                    Label("Copy missing receipts", systemImage: "exclamationmark.bubble")
                }
                .controlSize(.small)
                .disabled(records.isEmpty)
                .help("Copy a plain-English checklist of missing publication proof and exact receipt-capture commands.")

                Button {
                    importSocialMasterQueueFromAgent(path: episode1FinalSocialPostingPacketManifestPath)
                } label: {
                    Label(socialReady ? "Reload E1 socials" : "Load E1 socials", systemImage: "square.grid.3x3.square")
                }
                .controlSize(.small)
                .disabled(!FileManager.default.fileExists(atPath: episode1FinalSocialPostingPacketManifestPath))
                .help("Load the current Episode 1 final 31-clip social posting packet into Mission Control. This is read-only review state; it does not upload or alter source media.")

                Button {
                    openSocialMasterQueueCandidateClip()
                } label: {
                    Label("Open selected short", systemImage: "play.rectangle")
                }
                .controlSize(.small)
                .disabled(!socialReady || selectedSocialMasterQueueCandidate() == nil)
                .help("Open the selected derivative social short for watch-once review before posting.")

                Button {
                    copySelectedSocialPostingPacketJSON()
                } label: {
                    Label("Copy social packet", systemImage: "paperplane")
                }
                .controlSize(.small)
                .disabled(!socialReady || selectedSocialMasterQueueCandidate() == nil)
                .help("Copy the selected social posting packet JSON: clip path, platform copy, captions, receipt checklist, and proof rule.")
            }

            LazyVGrid(columns: [GridItem(.adaptive(minimum: 210), spacing: 8)], spacing: 8) {
                publicationMissionDeliverableCard(
                    title: "16:9 episode",
                    destination: "YouTube + Patreon",
                    status: episodeReady ? (episodeReceiptCaptured ? "Receipt captured" : "Ready to post") : "Needs Full prep",
                    detail: episodeRecord?.artifactPath ?? "Export the 16:9 master and generate the publish ledger.",
                    color: episodeReady ? .green : .orange,
                    icon: "play.rectangle.fill",
                    nextAction: episodeReady ? "Upload/schedule, then capture receipt." : "Run Full prep."
                )

                publicationMissionDeliverableCard(
                    title: "9:16 shorts",
                    destination: "Shorts + Reels + LinkedIn",
                    status: socialReady ? "\(socialMasterQueueClipCount) clips loaded" : "Needs social packet",
                    detail: socialMasterQueueOutputPath.isEmpty ? "Generate or load the social master queue." : socialMasterQueueOutputPath,
                    color: socialReady ? .cyan : .orange,
                    icon: "rectangle.portrait.on.rectangle.portrait.fill",
                    nextAction: socialReady ? "Select a candidate and use its posting packet." : "Load the Episode 1 final social packet."
                )

                publicationMissionDeliverableCard(
                    title: "Podcast audio",
                    destination: "Spotify + Apple",
                    status: podcastReady ? "Ready packet generated" : "Needs podcast ready",
                    detail: podcastReadyPacketOutputPath.isEmpty ? "Generate Podcast Packet, then Podcast Ready." : podcastReadyPacketOutputPath,
                    color: podcastReady ? .mint : .orange,
                    icon: "dot.radiowaves.left.and.right",
                    nextAction: podcastReady ? "Listen-check, upload via host/RSS, capture URLs." : "Generate Podcast Ready."
                )
            }

            HStack(alignment: .top, spacing: 8) {
                Image(systemName: total > 0 && remaining == 0 ? "checkmark.seal.fill" : "exclamationmark.triangle.fill")
                    .foregroundStyle(total > 0 && remaining == 0 ? .green : .orange)
                Text(total == 0
                     ? "Receipt proof starts after the publish ledger exists. Until then, nothing should be called published."
                     : "\(captured) of \(total) platform receipt(s) captured. \(remaining) still need public/scheduled URLs or provider IDs.")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
            }
        }
        .padding(9)
        .background(Color.yellow.opacity(0.055))
        .overlay(
            RoundedRectangle(cornerRadius: 12)
                .stroke(Color.yellow.opacity(0.16), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 12))
    }

    private func publicationMissionDeliverableCard(
        title: String,
        destination: String,
        status: String,
        detail: String,
        color: Color,
        icon: String,
        nextAction: String
    ) -> some View {
        VStack(alignment: .leading, spacing: 6) {
            HStack(spacing: 7) {
                Image(systemName: icon)
                    .foregroundStyle(color)
                    .frame(width: 20, height: 20)
                    .background(color.opacity(0.12))
                    .clipShape(Circle())
                VStack(alignment: .leading, spacing: 1) {
                    Text(title)
                        .font(.caption2)
                        .fontWeight(.black)
                    Text(destination)
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                }
                Spacer()
            }

            Text(status)
                .font(.caption2.monospaced())
                .fontWeight(.bold)
                .foregroundStyle(color)

            Text(detail)
                .font(.caption2)
                .foregroundStyle(.secondary)
                .lineLimit(2)

            Text(nextAction)
                .font(.caption2)
                .fontWeight(.semibold)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(8)
        .background(color.opacity(0.075))
        .clipShape(RoundedRectangle(cornerRadius: 10))
    }

    private func publishReleaseChecklistPanel(records: [PublishReceiptRecord]) -> some View {
        let summary = publishReleaseChecklistSummary(records: records)
        let nextActions = publishReleaseChecklistNextActions(records: records, limit: 3)
        let readiness = summary["readinessLevel"] as? String ?? "drafting"
        let color = publishReleaseChecklistColor(readiness)

        return VStack(alignment: .leading, spacing: 8) {
            HStack(alignment: .top, spacing: 8) {
                Image(systemName: publishReleaseChecklistIcon(readiness))
                    .foregroundStyle(color)
                    .frame(width: 22, height: 22)
                    .background(color.opacity(0.13))
                    .clipShape(Circle())
                VStack(alignment: .leading, spacing: 2) {
                    Text("Release checklist")
                        .font(.caption)
                        .fontWeight(.black)
                    Text(publishReleaseChecklistSummaryText(summary))
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
                Spacer()
                Text(readiness.replacingOccurrences(of: "-", with: " ").uppercased())
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(color)
                    .padding(.horizontal, 7)
                    .padding(.vertical, 4)
                    .background(color.opacity(0.12))
                    .clipShape(Capsule())
            }

            HStack(spacing: 6) {
                publishStatPill("artifacts", summary["artifactReadyCount"] as? Int ?? 0, .green)
                publishStatPill("copy", summary["copyReadyCount"] as? Int ?? 0, .cyan)
                publishStatPill("receipts", summary["receiptCapturedCount"] as? Int ?? 0, .yellow)
                publishStatPill("blocked", summary["blockedCount"] as? Int ?? 0, .red)
            }

            VStack(alignment: .leading, spacing: 4) {
                ForEach(Array(nextActions.enumerated()), id: \.offset) { index, action in
                    HStack(alignment: .top, spacing: 6) {
                        Text("\(index + 1).")
                            .font(.caption2.monospacedDigit())
                            .fontWeight(.black)
                            .foregroundStyle(color)
                            .frame(width: 18, alignment: .leading)
                        VStack(alignment: .leading, spacing: 1) {
                            Text(action["label"] as? String ?? "Next action")
                                .font(.caption2)
                                .fontWeight(.semibold)
                                .lineLimit(1)
                            Text(action["action"] as? String ?? "")
                                .font(.caption2)
                                .foregroundStyle(.secondary)
                                .fixedSize(horizontal: false, vertical: true)
                        }
                    }
                }
            }
        }
        .padding(8)
        .background(color.opacity(0.055))
        .overlay(
            RoundedRectangle(cornerRadius: 10)
                .stroke(color.opacity(0.16), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 10))
    }

    private func socialPublicationQueuePanel(records: [PublishReceiptRecord]) -> some View {
        let socialRecords = socialShortPublishRecords(from: records)
        let exportedShorts = uniqueSocialShortArtifactPaths(from: socialRecords)
        let topTitles = socialPublicationTopTitles(from: socialRecords, limit: 4)
        let queueReady = !exportedShorts.isEmpty
        let color: Color = queueReady ? .green : .orange

        return VStack(alignment: .leading, spacing: 8) {
            HStack(alignment: .top, spacing: 8) {
                Image(systemName: queueReady ? "square.grid.3x3.square.fill" : "square.grid.3x3.square")
                    .foregroundStyle(color)
                    .frame(width: 22, height: 22)
                    .background(color.opacity(0.13))
                    .clipShape(Circle())
                VStack(alignment: .leading, spacing: 2) {
                    Text("Social publication queue")
                        .font(.caption)
                        .fontWeight(.black)
                    Text(queueReady
                         ? "\(exportedShorts.count) exported 9:16 short file(s) can be copied into a manual upload queue for YouTube Shorts, Instagram, Facebook, and LinkedIn."
                         : "Export at least one 9:16 short before building the upload queue.")
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
                Spacer()
                Button {
                    generateSocialPublicationQueueForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label("Generate", systemImage: "square.and.arrow.down")
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.mini)
                .disabled(!queueReady || socialPublicationQueueStatus == "generating")

                Button {
                    copySocialPublicationQueueChecklist(records: records)
                } label: {
                    Label("Copy checklist", systemImage: "doc.on.doc")
                }
                .controlSize(.mini)
                .disabled(!queueReady)
            }

            if !topTitles.isEmpty {
                HStack(spacing: 6) {
                    Text("Top candidates")
                        .font(.caption2)
                        .fontWeight(.bold)
                        .foregroundStyle(.secondary)
                    ForEach(topTitles, id: \.self) { title in
                        Text(title)
                            .font(.caption2)
                            .lineLimit(1)
                            .padding(.horizontal, 7)
                            .padding(.vertical, 3)
                            .background(Color.yellow.opacity(0.12))
                            .clipShape(Capsule())
                    }
                }
            }

            socialMasterQueuePanel()

            Divider().opacity(0.25)

            if let selectedReceipt = selectedPublishReceipt(from: records), isSocialShortReceipt(selectedReceipt) {
                VStack(alignment: .leading, spacing: 6) {
                    Text("Capture receipt for \(selectedReceipt.platform) / \(selectedReceipt.title)")
                        .font(.caption2)
                        .fontWeight(.bold)
                        .lineLimit(1)
                    HStack(spacing: 6) {
                        Picker("Status", selection: $socialReceiptCaptureStatus) {
                            Text("Uploaded").tag("uploaded")
                            Text("Scheduled").tag("scheduled")
                            Text("Published").tag("published")
                        }
                        .labelsHidden()
                        .frame(width: 112)

                        TextField("Public or scheduled URL", text: $socialReceiptCaptureURL)
                            .textFieldStyle(.roundedBorder)
                        TextField("Provider ID", text: $socialReceiptCaptureProviderId)
                            .textFieldStyle(.roundedBorder)
                            .frame(width: 135)
                        Button {
                            captureSocialReceiptForSelectedRecord(selectedReceipt)
                        } label: {
                            Label("Save receipt", systemImage: "checkmark.seal")
                        }
                        .buttonStyle(.borderedProminent)
                        .controlSize(.mini)
                        .disabled(socialReceiptCaptureURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                    }
                }
                .padding(7)
                .background(Color.white.opacity(0.045))
                .clipShape(RoundedRectangle(cornerRadius: 9))
