                            .lineLimit(1)
                        HStack(spacing: 5) {
                            socialCandidateArtifactStatusPill("clip", key: "clipPath")
                            socialCandidateArtifactStatusPill("thumb", key: "thumbnailPath")
                            socialCandidateArtifactStatusPill("captions", key: "captionSrtPath")
                            socialCandidateArtifactStatusPill("copy", key: "platformCopyPath")
                        }
                        socialMasterQueuePostingPacketCard(selectedCandidate)
                        HStack(spacing: 6) {
                            Button("Open clip") {
                                openSocialMasterQueueCandidateClip()
                            }
                            .controlSize(.mini)
                            Button("Reveal clip") {
                                revealSocialMasterQueueCandidateClip()
                            }
                            .controlSize(.mini)
                            Button("Copy handoff") {
                                copySocialMasterQueueCandidateSummary()
                            }
                            .controlSize(.mini)
                            Button("Copy packet JSON") {
                                copySelectedSocialPostingPacketJSON()
                            }
                            .controlSize(.mini)
                        }
                        HStack(spacing: 6) {
                            Button("Open copy") {
                                openSocialMasterQueueCandidateArtifact(key: "platformCopyPath", label: "platform copy")
                            }
                            .controlSize(.mini)
                            Button("Reveal captions") {
                                revealSocialMasterQueueCandidateArtifact(key: "captionSrtPath", label: "captions")
                            }
                            .controlSize(.mini)
                            Button("Reveal thumb") {
                                revealSocialMasterQueueCandidateArtifact(key: "thumbnailPath", label: "thumbnail")
                            }
                            .controlSize(.mini)
                            Button("Copy copy text") {
                                copySocialMasterQueueCandidatePlatformCopy()
                            }
                            .controlSize(.mini)
                        }
                        Divider().opacity(0.25)
                        VStack(alignment: .leading, spacing: 5) {
                            let receiptId = socialMasterQueueSelectedReceiptId()
                            Text(receiptId.isEmpty ? "Receipt tracking: promote this scout clip before posting" : "Receipt tracking: existing platform receipt ready")
                                .font(.caption2)
                                .fontWeight(.bold)
                                .foregroundStyle(receiptId.isEmpty ? .orange : .green)
                            HStack(spacing: 6) {
                                Picker("Platform", selection: $socialMasterReceiptCapturePlatform) {
                                    ForEach(socialMasterQueueSelectedPlatforms(), id: \.self) { platform in
                                        Text(platform).tag(platform)
                                    }
                                }
                                .labelsHidden()
                                .frame(width: 142)

                                Picker("Status", selection: $socialMasterReceiptCaptureStatus) {
                                    Text("Uploaded").tag("uploaded")
                                    Text("Scheduled").tag("scheduled")
                                    Text("Published").tag("published")
                                }
                                .labelsHidden()
                                .frame(width: 112)
                            }
                            HStack(spacing: 6) {
                                TextField("Public or scheduled URL", text: $socialMasterReceiptCaptureURL)
                                    .textFieldStyle(.roundedBorder)
                                TextField("Provider ID", text: $socialMasterReceiptCaptureProviderId)
                                    .textFieldStyle(.roundedBorder)
                                    .frame(width: 130)
                            }
                            HStack(spacing: 6) {
                                Button {
                                    captureSocialMasterQueueReceiptForSelectedCandidate()
                                } label: {
                                    Label("Save selected receipt", systemImage: "checkmark.seal")
                                }
                                .buttonStyle(.borderedProminent)
                                .controlSize(.mini)
                                .disabled(receiptId.isEmpty || socialMasterReceiptCaptureURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)

                                if !receiptId.isEmpty {
                                    Button("Copy receipt command") {
                                        copySocialMasterQueueReceiptCommand()
                                    }
                                    .controlSize(.mini)
                                }
                            }
                            if receiptId.isEmpty {
                                Text("Expansion candidates do not have durable receipt IDs yet. Watch, promote, or post manually with an explicit note; do not claim Quipsly captured the platform receipt.")
                                    .font(.caption2)
                                    .foregroundStyle(.secondary)
                                    .fixedSize(horizontal: false, vertical: true)
                            }
                        }
                    }
                    .padding(7)
                    .background(Color.cyan.opacity(0.08))
                    .clipShape(RoundedRectangle(cornerRadius: 8))
                }
            }

            if !socialMasterQueueErrorMessage.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                Text(socialMasterQueueErrorMessage)
                    .font(.caption2)
                    .foregroundStyle(.red)
                    .fixedSize(horizontal: false, vertical: true)
            }
        }
        .padding(7)
        .background(color.opacity(0.055))
        .overlay(
            RoundedRectangle(cornerRadius: 9)
                .stroke(color.opacity(0.16), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 9))
    }

    private func socialCandidateArtifactStatusPill(_ label: String, key: String) -> some View {
