            }
            Spacer()
            Button("Copy result") {
                copyPublishReceiptText(
                    publishConnectorWorkerResultJson,
                    successMessage: "Copied publish worker result JSON"
                )
            }
            .buttonStyle(.bordered)
            .controlSize(.mini)
            .disabled(publishConnectorWorkerResultJson.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
        }
        .padding(8)
        .background(color.opacity(0.07))
        .clipShape(RoundedRectangle(cornerRadius: 10))
    }

