    private func publishDestinationGuidancePanel(_ record: PublishReceiptRecord, compact: Bool) -> some View {
        let guidance = publishDestinationGuidance(for: record)
        let destinationId = guidance["destinationId"] as? String ?? publishDestinationId(for: record)
        let label = guidance["label"] as? String ?? record.platform
        let preferredFormat = guidance["preferredFormat"] as? String ?? record.format
        let requires = guidance["requires"] as? [String] ?? []
        let checklist = guidance["humanChecklist"] as? [String] ?? []
        let agentGuidance = guidance["agentGuidance"] as? String ?? "Use the destination catalog before upload."
        let visibleRequires = Array(requires.prefix(compact ? 3 : 8))
        let visibleChecklist = Array(checklist.prefix(compact ? 2 : 6))

        return VStack(alignment: .leading, spacing: compact ? 5 : 7) {
            HStack(alignment: .firstTextBaseline, spacing: 6) {
                Label(label, systemImage: "map")
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(.cyan)
                    .lineLimit(1)
                Spacer(minLength: 6)
                Text(destinationId)
                    .font(.caption2.monospaced())
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
            }

            HStack(spacing: 6) {
                Text("FORMAT \(preferredFormat)")
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(.yellow)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 3)
                    .background(Color.yellow.opacity(0.10))
                    .clipShape(Capsule())
                Text(agentGuidance)
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .lineLimit(compact ? 2 : 4)
            }

            if !visibleRequires.isEmpty {
                VStack(alignment: .leading, spacing: 2) {
                    Text("Requires")
                        .font(.caption2)
                        .fontWeight(.black)
                        .foregroundStyle(.secondary)
                    ForEach(visibleRequires, id: \.self) { item in
                        Text("• \(item)")
                            .font(.caption2)
                            .foregroundStyle(.secondary)
                    }
                }
            }

            if !compact && !visibleChecklist.isEmpty {
                VStack(alignment: .leading, spacing: 2) {
                    Text("Human checklist")
                        .font(.caption2)
                        .fontWeight(.black)
                        .foregroundStyle(.secondary)
                    ForEach(Array(visibleChecklist.enumerated()), id: \.offset) { index, item in
                        Text("\(index + 1). \(item)")
                            .font(.caption2)
                            .foregroundStyle(.secondary)
                    }
                }
            }
        }
        .padding(compact ? 8 : 10)
        .background(Color.cyan.opacity(compact ? 0.055 : 0.075))
        .overlay(
            RoundedRectangle(cornerRadius: compact ? 10 : 12)
                .stroke(Color.cyan.opacity(compact ? 0.13 : 0.18), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: compact ? 10 : 12))
        .help("Destination guidance from the publish destination catalog. This is the platform contract for metadata, manual upload, dry-run workers, and future API publishing.")
    }

