    private var programMonitor: some View {
        let shouldBlankProgram = programShouldShowBlankSlate()
        let blankState = programBlankSlateState()

        return VStack(alignment: .leading, spacing: 8) {
            HStack {
                Label("Program Output", systemImage: "rectangle.inset.filled.and.person.filled")
                    .font(.subheadline)
                    .fontWeight(.semibold)
                Spacer()
                Text(playbackEngine.playbackFormat.rawValue)
                    .font(.caption2)
                    .foregroundStyle(.secondary)
            }

            if let player = playbackEngine.player {
                ZStack(alignment: .topLeading) {
                    PlayerView(
                        player: player,
                        onScroll: { delta in
                            scrubProgramMonitor(by: delta)
                        },
                        onHoverChange: { isHovering in
                            isPointerOverProgramMonitor = isHovering
                        }
                    )
                        .opacity(shouldBlankProgram ? 0.0 : 1.0)

                    if shouldBlankProgram {
                        programBlankSlate(title: blankState.title, detail: blankState.detail, systemImage: blankState.systemImage)
                    }

                    if let lane = programCropGestureLane() {
                        programCropModeOverlay(lane: lane)
                            .padding(10)
                    }
                }
                .aspectRatio(playbackEngine.playbackFormat == .vertical9x16 ? 9/16 : 16/9, contentMode: .fit)
                .background(Color.black)
                .clipShape(RoundedRectangle(cornerRadius: 14))
                .overlay(
                    RoundedRectangle(cornerRadius: 14)
                        .stroke((shouldBlankProgram ? Color.red : Color.yellow).opacity(0.28), lineWidth: 1.5)
                )
                .shadow(color: Color.black.opacity(0.28), radius: 14, y: 6)
                .contentShape(Rectangle())
                .gesture(programDragGesture)
                .gesture(programMagnificationGesture)
                .help(programMonitorHelpText(shouldBlankProgram: shouldBlankProgram))
                .onAppear {
                    startYaw = yaw
                    startPitch = pitch
                    startFov = fov
                    startProgramCrop = programCropEditMode == .baseline
                        ? selectedProgramCropAdjustment()
                        : selectedProgramCropAtPlayheadAdjustment()
                }
            } else {
                monitorPlaceholder(title: "No program output", systemImage: "play.slash")
                    .aspectRatio(playbackEngine.playbackFormat == .vertical9x16 ? 9/16 : 16/9, contentMode: .fit)
            }
        }
    }

    private func programShouldShowBlankSlate() -> Bool {
        guard playbackEngine.playbackMode == .playEdit,
              let sequence = projectStore.activeSequence,
              !sequence.lanes.isEmpty else {
            return false
        }

        let programLanes = primaryProgramLanes(in: sequence)
        return !programLanes.contains { decisionAtPlayhead(for: $0)?.type == .active }
    }

    private func programBlankSlateState() -> (title: String, detail: String, systemImage: String) {
        guard let sequence = projectStore.activeSequence else {
            return (
                "No program output",
                "Load an episode before the program monitor can show edit truth.",
                "play.slash"
            )
        }

        let cutLanes = primaryProgramLanes(in: sequence).filter { decisionAtPlayhead(for: $0)?.type == .cut }
        if !cutLanes.isEmpty {
            return (
                "Skipped gap",
                "Play Edit intentionally shows nothing here. Play Through and the source wall still reveal the synced media.",
                "forward.end.fill"
            )
        }

        return (
            "No SHOW decision yet",
            "This sequence moment is synced source context only. Add a SHOW decision from the source wall when it belongs in the edit.",
            "rectangle.dashed"
        )
    }

    private func programBlankSlate(title: String, detail: String, systemImage: String) -> some View {
        VStack(spacing: 10) {
            Image(systemName: systemImage)
                .font(.system(size: 34, weight: .semibold))
                .foregroundStyle(Color.red.opacity(0.85))
            Text(title)
                .font(.headline)
                .foregroundStyle(.primary)
            Text(detail)
                .font(.caption)
                .foregroundStyle(.secondary)
                .multilineTextAlignment(.center)
                .lineLimit(3)
                .frame(maxWidth: 420)
            HStack(spacing: 6) {
                shortcutPill("1-6", "Add SHOW/SKIP")
                shortcutPill("Play Through", "Review sources")
            }
        }
        .padding(18)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(
            LinearGradient(
                colors: [Color.black.opacity(0.95), Color.red.opacity(0.18), Color.black.opacity(0.95)],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
        )
    }

    private func scrubProgramMonitor(by delta: Double) {
        guard abs(delta) > 0.001 else { return }
        let nextTime = max(0, playbackEngine.playhead + delta)
        playbackEngine.scrub(to: nextTime)
        lastMediaAction = String(format: "Scrubbed program monitor to %.2fs", nextTime)
        updateAgentState()
    }

    private var sourceMonitorGrid: some View {
        VStack(alignment: .leading, spacing: 6) {
            let videoLanes = monitorVideoLanes
            let supportLanes = monitorSupportLanes

            HStack {
                Label("Whole Synced Sources", systemImage: "rectangle.grid.2x2")
                    .font(.subheadline)
                    .fontWeight(.semibold)
                Spacer()
                if projectStore.activeSequence != nil {
                    Text("\(videoLanes.count) video sources")
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                }
            }

            Text("Each card is a full source lane at the current playhead. SHOW/SKIP are decisions on top, not chopped clips.")
                .font(.caption2)
                .foregroundStyle(.secondary)

            if !videoLanes.isEmpty {
                ScrollView(.horizontal, showsIndicators: true) {
                    HStack(alignment: .top, spacing: 10) {
                        ForEach(videoLanes) { lane in
                            sourceMonitorCard(for: lane, isSelected: selectedLaneId == lane.id)
                                .frame(width: 292)
                                .contentShape(Rectangle())
                                .onTapGesture {
                                    selectedLaneId = lane.id
                                    selectedTagId = nil
                                    lastMediaAction = "Selected source monitor: \(lane.name)"
                                    updateAgentState()
                                }
                        }
                    }
                    .padding(.bottom, 2)
                }
                .frame(minHeight: 275)
                .overlay(alignment: .trailing) {
                    LinearGradient(
                        colors: [Color.clear, Color.black.opacity(0.16)],
                        startPoint: .leading,
                        endPoint: .trailing
                    )
                    .frame(width: 22)
                    .allowsHitTesting(false)
                }
                if !supportLanes.isEmpty {
                    sourceSupportLaneStrip(supportLanes)
                }
            } else if projectStore.activeSequence != nil {
                monitorPlaceholder(title: "No video source lanes linked yet", systemImage: "video.slash")
                    .frame(minHeight: 180)
                if !supportLanes.isEmpty {
                    sourceSupportLaneStrip(supportLanes)
                }
            } else {
                monitorPlaceholder(title: "Import sources to build the wall", systemImage: "video.badge.plus")
                    .frame(minHeight: 180)
            }
        }
        .padding(10)
        .background(Color.secondary.opacity(0.07))
        .clipShape(RoundedRectangle(cornerRadius: 14))
    }

    private var monitorVideoLanes: [VideoLane] {
        projectStore.activeSequence?.lanes.filter { !isSupportOnlyLane($0) } ?? []
    }

    private var monitorSupportLanes: [VideoLane] {
        projectStore.activeSequence?.lanes.filter { isSupportOnlyLane($0) } ?? []
    }

    private func isSupportOnlyLane(_ lane: VideoLane) -> Bool {
        let role = lane.metadata?.role.lowercased() ?? ""
        let kind = lane.metadata?.mediaKind.lowercased() ?? ""
        if role.contains("audio") || kind == "audio" {
            return true
        }
        if let source = lane.sourceVideo, isAudioPath(source.mediaURL.path) {
            return true
        }
        return false
    }

    private func sourceSupportLaneStrip(_ lanes: [VideoLane]) -> some View {
        VStack(alignment: .leading, spacing: 5) {
            Label("\(lanes.count) audio/context lanes supporting sync and export", systemImage: "waveform")
                .font(.caption2)
                .fontWeight(.semibold)
                .foregroundStyle(.secondary)
            HStack(spacing: 6) {
                ForEach(lanes.prefix(5)) { lane in
                    Text(lane.name)
                        .font(.caption2)
                        .lineLimit(1)
                        .padding(.horizontal, 7)
                        .padding(.vertical, 4)
                        .background(Color.secondary.opacity(0.12))
                        .clipShape(Capsule())
                }
                if lanes.count > 5 {
                    Text("+\(lanes.count - 5) more")
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                }
            }
        }
        .padding(8)
        .background(Color.secondary.opacity(0.07))
        .clipShape(RoundedRectangle(cornerRadius: 10))
    }

    private func sourceMonitorCard(for lane: VideoLane, isSelected: Bool) -> some View {
        let currentTag = decisionAtPlayhead(for: lane)
        let accent = decisionColor(currentTag?.type)
        let readiness = sourceReadiness(for: lane)

        return VStack(alignment: .leading, spacing: 5) {
            sourceMonitorHeader(lane: lane, currentTag: currentTag, accent: accent)
            sourceMonitorReadinessRow(lane: lane, readiness: readiness)
            sourceMonitorPlayer(lane: lane, readiness: readiness)
            sourceMonitorDecisionBanner(lane: lane, currentTag: currentTag, accent: accent)
            sourceMonitorStatsRow(lane: lane)
            sourceMonitorReviewControls(lane: lane, isSelected: isSelected)
            sourceMonitorWholeLaneFooter(isSelected: isSelected)
        }
        .padding(8)
        .background(readiness.color.opacity(0.06))
        .overlay(
            RoundedRectangle(cornerRadius: 10)
                .stroke(isSelected ? Color.white.opacity(0.85) : accent.opacity(0.35), lineWidth: isSelected ? 2.5 : (currentTag == nil ? 1 : 2))
        )
        .shadow(color: isSelected ? Color.white.opacity(0.18) : Color.clear, radius: 8)
        .clipShape(RoundedRectangle(cornerRadius: 10))
        .help("Selects the whole source lane. Edit decisions stay as overlays on the timeline.")
    }

