    private func proxyDiagnosticJSON(for lane: VideoLane, readiness: SourceReadiness) -> String {
        let source = lane.sourceVideo
        let payload: [String: Any] = [
            "laneId": lane.id.uuidString,
            "laneName": lane.name,
            "mediaKind": lane.metadata?.mediaKind ?? "",
            "role": lane.metadata?.role ?? "",
            "sourcePath": source?.mediaURL.path ?? lane.metadata?.sourcePath ?? "",
            "expectedProxyPath": source?.proxyURL?.path ?? readiness.playbackPath,
            "readiness": readiness.label,
            "readinessDetail": readiness.detail,
            "isReady": readiness.isReady,
            "needsStorageAccess": readiness.needsStorageAccess,
            "durationSeconds": source?.duration ?? 0,
            "sourceOffsetSeconds": source?.offset ?? 0,
            "showDecisionCount": lane.tags.filter { $0.type == .active }.count,
            "skipDecisionCount": lane.tags.filter { $0.type == .cut }.count,
            "architectureInvariant": "Whole source lane with metadata decisions; do not create chopped clips."
        ]

        guard JSONSerialization.isValidJSONObject(payload),
              let data = try? JSONSerialization.data(withJSONObject: payload, options: [.prettyPrinted, .sortedKeys]),
              let text = String(data: data, encoding: .utf8) else {
            return """
            {
              "laneId": "\(lane.id.uuidString)",
              "laneName": "\(lane.name)",
              "readiness": "\(readiness.label)",
              "readinessDetail": "\(readiness.detail)"
            }
            """
        }
        return text
    }

    private func mediaRecoveryReportJSON() -> String {
        guard let sequence = projectStore.activeSequence else {
            return jsonString(from: [
                "status": "no_active_sequence",
                "activeSessionName": normalizedActiveSessionName(),
                "generatedAt": ISO8601DateFormatter().string(from: Date()),
                "architectureInvariant": "Whole source lanes plus metadata decisions; no chopped source clips."
            ])
        }

        return jsonString(from: mediaRecoveryReportPayload(for: sequence, summary: mediaReadinessSummary()))
    }

    private func mediaRecoveryReportPayload(
        for sequence: MediaSequence,
        summary: MediaReadinessSummary
    ) -> [String: Any] {
        let formatter = ISO8601DateFormatter()
        let laneReports = sequence.lanes.map { lane -> [String: Any] in
            let readiness = sourceReadiness(for: lane)
            let source = lane.sourceVideo
            let sourcePath = source?.mediaURL.path ?? lane.metadata?.sourcePath ?? ""
            let proxyPath = source?.proxyURL?.path ?? readiness.playbackPath
            let protectedSource = !sourcePath.isEmpty && ExternalMediaAccess.isProtectedUserMediaPath(sourcePath)
            let protectedProxy = !proxyPath.isEmpty && ExternalMediaAccess.isProtectedUserMediaPath(proxyPath)
            let sourceProbePolicy = protectedSource && !externalMediaAccess.canProbeWithoutPrompt(URL(fileURLWithPath: sourcePath))
                ? "not_probed_protected_original"
                : "safe_to_probe_if_needed"
            let proxyProbePolicy = protectedProxy && !externalMediaAccess.canProbeWithoutPrompt(URL(fileURLWithPath: proxyPath))
                ? "not_probed_protected_proxy"
                : "safe_to_probe_if_needed"

            return [
                "laneId": lane.id.uuidString,
                "laneName": lane.name,
                "mediaKind": lane.metadata?.mediaKind ?? "",
                "role": lane.metadata?.role ?? "",
                "durationSeconds": source?.duration ?? lane.duration,
                "offsetSeconds": source?.offset ?? 0,
                "sourcePath": sourcePath,
                "expectedProxyPath": proxyPath,
                "readiness": readiness.label,
                "readinessDetail": readiness.detail,
                "isReady": readiness.isReady,
                "needsStorageAccess": readiness.needsStorageAccess,
                "recoveryCategory": mediaRecoveryCategory(for: lane, readiness: readiness),
                "recoveryNextAction": mediaRecoveryNextStep(for: lane, readiness: readiness),
                "proxyError": proxyFailureByLaneId[lane.id] ?? "",
                "sourceProbePolicy": sourceProbePolicy,
                "proxyProbePolicy": proxyProbePolicy,
                "sourceMonitorPlayerReady": playbackEngine.sourcePlayers[lane.id] != nil,
                "showDecisionCount": lane.tags.filter { $0.type == .active }.count,
                "skipDecisionCount": lane.tags.filter { $0.type == .cut }.count,
                "trackIds": lane.metadata?.trackIds ?? [],
                "sourceLabel": lane.metadata?.sourceLabel ?? "",
                "assetFingerprint": lane.metadata?.assetFingerprint ?? "",
                "architectureInvariant": "This is a whole synced lane. Fix by relinking or attaching/generating a full-length proxy; do not replace it with a clipped media segment."
            ]
        }

        return [
            "status": "ok",
            "generatedAt": formatter.string(from: Date()),
            "activeSessionName": normalizedActiveSessionName(),
            "projectTitle": projectStore.project.title,
            "sequenceTitle": sequence.title,
            "sequenceDurationSeconds": sequence.duration,
            "laneCount": sequence.lanes.count,
            "sourceMonitorVideoCount": sequence.lanes.filter { !isSupportOnlyLane($0) }.count,
            "supportLaneCount": sequence.lanes.filter { isSupportOnlyLane($0) }.count,
            "sourcePlayerCount": playbackEngine.sourcePlayers.count,
            "productionReady": summary.isProductionReady,
            "productionReadinessDetail": summary.detail,
            "visualRoughCutReady": summary.isVideoRoughCutReady,
            "visualRoughCutDetail": summary.videoRoughCutDetail,
            "videoProxyReadyCount": summary.videoProxyReadyCount,
            "videoBlockedCount": summary.videoBlockedCount,
            "audioReadyCount": summary.audioReadyCount,
            "audioBlockedCount": summary.audioBlockedCount,
            "storageAccessNeededCount": summary.storageAccessNeededCount,
            "showDecisionCount": summary.showDecisionCount,
            "skipDecisionCount": summary.skipDecisionCount,
            "blockedLanes": laneReports.filter { report in
                (report["isReady"] as? Bool) == false
            },
            "lanes": laneReports,
            "externalMediaAccess": [
                "rootPath": externalMediaAccess.rootPath,
                "hasExplicitFolderGrant": externalMediaAccess.hasExplicitFolderGrant,
                "status": externalMediaAccess.status
            ],
            "rules": [
                "Passive UI and reports must not probe protected originals.",
                "Preview and export use MediaVault proxies.",
                "Original sources remain whole and untouched.",
                "SHOW/SKIP/camera choices are metadata overlays."
            ]
        ]
    }

    private func jsonString(from payload: [String: Any]) -> String {
        guard JSONSerialization.isValidJSONObject(payload),
              let data = try? JSONSerialization.data(withJSONObject: payload, options: [.prettyPrinted, .sortedKeys]),
              let text = String(data: data, encoding: .utf8) else {
            return #"{"status":"serialization_failed"}"#
        }
        return text
    }

