    private func editorProofSnapshotPayload(
        for sequence: MediaSequence,
        readinessSummary: MediaReadinessSummary,
        selectedLaneName: String,
        selectedTagType: String,
        programTitle: String,
        programDetail: String
    ) -> [String: Any] {
        let videoMonitorCount = sequence.lanes.filter { !isSupportOnlyLane($0) }.count
        let supportLaneCount = sequence.lanes.filter { isSupportOnlyLane($0) }.count
        let sourcePlayerCount = playbackEngine.sourcePlayers.count
        let hasShowDecisions = readinessSummary.showDecisionCount > 0
        let hasSkipDecisions = readinessSummary.skipDecisionCount > 0
        let canScrubSyncedSources = videoMonitorCount > 0 && sourcePlayerCount >= videoMonitorCount
        let canPlayEdit = !playbackEngine.validRanges.isEmpty && (hasShowDecisions || hasSkipDecisions)
        let proxyFirst = videoMonitorCount == 0 || readinessSummary.videoProxyReadyCount >= videoMonitorCount
        let canEditNow = readinessSummary.isVideoRoughCutReady && canScrubSyncedSources && canPlayEdit
        let status: String
        let statusLabel: String
        let nextSafeAction: [String: Any]

        if canEditNow {
            status = readinessSummary.isProductionReady ? "production_ready" : "visual_edit_ready"
            statusLabel = readinessSummary.isProductionReady ? "Ready to edit and proxy-export" : "Ready for visual rough cutting"
            nextSafeAction = [
                "label": selectedLaneName.isEmpty ? "Pick a source lane or scrub the timeline" : "Tune the selected lane/decision",
                "endpoint": selectedLaneName.isEmpty
                    ? "GET /focus_timeline"
                    : "GET /source_window?lane_id=\(selectedLaneName)&action=show|cut&duration=<seconds>",
                "explanation": selectedLaneName.isEmpty
                    ? "The editor is proxy-backed and synced. Scrub or select a source monitor to make the next decision."
                    : "The selected source lane is safe for metadata SHOW/SKIP decisions. Original media remains untouched."
            ]
        } else if readinessSummary.isVideoRoughCutReady {
            status = "review_ready_needs_play_edit_proof"
            statusLabel = "Sources are visible; edit ranges need attention"
            nextSafeAction = [
                "label": "Add or inspect SHOW/SKIP decisions",
                "endpoint": "GET /timeline_zoom?mode=precision",
                "explanation": "The source wall is proxy-backed, but Play Edit needs visible decision ranges before this feels like a true edit."
            ]
        } else {
            status = "needs_media_recovery"
            statusLabel = "Needs media recovery before editing"
            nextSafeAction = [
                "label": "Inspect media recovery report",
                "endpoint": "GET /state then read mediaRecoveryReport.blockedLanes",
                "explanation": "Recover full-length proxies or relink whole sources before judging edit behavior."
            ]
        }

        var blockers: [String] = []
        if videoMonitorCount == 0 {
            blockers.append("No video source monitor lanes are loaded.")
        }
        if sourcePlayerCount < videoMonitorCount {
            blockers.append("\(videoMonitorCount - sourcePlayerCount) video source monitor(s) are not playable yet.")
        }
        if !canPlayEdit {
            blockers.append("Play Edit does not yet have enough SHOW/SKIP decision evidence.")
        }
        if !proxyFirst {
            blockers.append("Not every video source monitor is proxy-backed.")
        }
        if readinessSummary.videoBlockedCount > 0 || readinessSummary.audioBlockedCount > 0 {
            blockers.append("Some media lanes still need recovery or proxy work.")
        }

        return [
            "status": status,
            "statusLabel": statusLabel,
            "canEditNow": canEditNow,
            "canScrubSyncedSources": canScrubSyncedSources,
            "canPlayEdit": canPlayEdit,
            "proxyFirst": proxyFirst,
            "generatedAt": ISO8601DateFormatter().string(from: Date()),
            "activeSessionName": normalizedActiveSessionName(),
            "projectTitle": projectStore.project.title,
            "sequenceTitle": sequence.title,
            "sequenceDuration": sequence.duration,
            "currentProgramTitle": programTitle,
            "currentProgramDetail": programDetail,
            "selectedLaneName": selectedLaneName,
            "selectedTagType": selectedTagType,
            "nextSafeAction": nextSafeAction,
            "blockers": blockers,
            "evidence": [
                "laneCount": sequence.lanes.count,
                "sourceMonitorVideoCount": videoMonitorCount,
                "supportLaneCount": supportLaneCount,
                "sourcePlayerCount": sourcePlayerCount,
                "videoProxyReadyCount": readinessSummary.videoProxyReadyCount,
                "videoBlockedCount": readinessSummary.videoBlockedCount,
                "audioReadyCount": readinessSummary.audioReadyCount,
                "audioBlockedCount": readinessSummary.audioBlockedCount,
                "validRangeCount": playbackEngine.validRanges.count,
                "showDecisionCount": readinessSummary.showDecisionCount,
                "skipDecisionCount": readinessSummary.skipDecisionCount,
                "playhead": playbackEngine.playhead,
                "playbackMode": playbackEngine.playbackMode.rawValue,
                "playbackFormat": playbackEngine.playbackFormat.rawValue,
                "timelinePixelsPerSecond": timelinePixelsPerSecond,
                "timelineFitToWindow": isTimelineFitToWindow
            ],
            "proofChecklist": [
                proofChecklistItem("sequence-loaded", "pass", "Loaded \(sequence.title)."),
                proofChecklistItem(
                    "whole-source-lanes",
                    sequence.lanes.isEmpty ? "fail" : "pass",
                    "\(sequence.lanes.count) whole lane(s) loaded; SHOW/SKIP decisions are metadata overlays."
                ),
                proofChecklistItem(
                    "proxy-first-preview",
                    proxyFirst ? "pass" : "needs_action",
                    "\(readinessSummary.videoProxyReadyCount)/\(videoMonitorCount) video monitor lane(s) are proxy-backed."
                ),
                proofChecklistItem(
                    "source-monitor-sync",
                    canScrubSyncedSources ? "pass" : "needs_action",
                    "\(sourcePlayerCount)/\(videoMonitorCount) video source monitor(s) have synchronized players."
                ),
                proofChecklistItem(
                    "play-edit-gaps",
                    canPlayEdit ? "pass" : "needs_action",
                    "\(playbackEngine.validRanges.count) Play Edit valid range(s), \(readinessSummary.showDecisionCount) SHOW, \(readinessSummary.skipDecisionCount) SKIP."
                )
            ],
            "architectureInvariant": "Whole source lanes plus metadata decisions; no chopped source clips."
        ]
    }

    private func proofChecklistItem(_ id: String, _ status: String, _ evidence: String) -> [String: Any] {
        [
            "id": id,
            "status": status,
            "evidence": evidence
        ]
    }

    #if os(macOS)
    private func copyTextToClipboard(_ text: String) {
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(text, forType: .string)
    }

    private func revealOrOpenFolder(_ url: URL) {
        let folderURL = url.hasDirectoryPath ? url : url.deletingLastPathComponent()
        if ExternalMediaAccess.isProtectedUserMediaPath(folderURL.path),
           !ExternalMediaAccess.shared.canProbeWithoutPrompt(folderURL) {
            NSWorkspace.shared.open(LocalMediaVault.shared.proxyRootURL)
            return
        }
        if FileManager.default.fileExists(atPath: folderURL.path) {
            NSWorkspace.shared.open(folderURL)
        } else if FileManager.default.fileExists(atPath: folderURL.deletingLastPathComponent().path) {
            NSWorkspace.shared.open(folderURL.deletingLastPathComponent())
        } else {
            NSWorkspace.shared.open(LocalMediaVault.shared.proxyRootURL)
        }
    }
    #endif

    private struct MediaReadinessSummary {
        var hasSequence: Bool
        var readyCount: Int
        var heldCount: Int
        var missingCount: Int
        var blockingCount: Int
        var videoProxyReadyCount: Int
        var videoBlockedCount: Int
        var audioReadyCount: Int
        var audioBlockedCount: Int
        var showDecisionCount: Int
        var skipDecisionCount: Int
        var rawVaultCount: Int
        var storageAccessNeededCount: Int
        var proxyBlockedCount: Int
        var detail: String

        var isProductionReady: Bool {
            hasSequence && blockingCount == 0 && videoBlockedCount == 0 && rawVaultCount == 0
        }

        var isVideoRoughCutReady: Bool {
            hasSequence
                && videoProxyReadyCount > 0
                && videoBlockedCount == 0
                && showDecisionCount > 0
                && rawVaultCount == 0
        }

        var videoRoughCutDetail: String {
            if !hasSequence {
                return "Load an episode before reviewing the visual rough cut."
            }
            if rawVaultCount > 0 {
                return "Some lanes still point at raw vault media. Keep originals external and preview from proxies."
            }
            if videoBlockedCount > 0 {
                return "\(videoBlockedCount) video lane(s) still need proxy playback before visual rough cutting."
            }
            if videoProxyReadyCount == 0 {
                return "No video proxy lanes are ready yet."
            }
            if showDecisionCount == 0 {
                return "Video proxies are ready, but no SHOW decisions exist yet."
            }
            if audioBlockedCount > 0 {
                return "You can review and switch the edit visually from video proxies. Finish audio proxies before waveform, sync review, export, or final production editing."
            }
            return "Video proxies and edit decisions are ready for visual review."
        }
    }

    private struct DeliveryLaneReadiness: Identifiable {
        var id: String
        var label: String
        var destinations: [String]
        var artifactType: String
        var format: String
        var status: String
        var isReady: Bool
        var summary: String
        var blocker: String
        var nextAction: String
        var humanAction: String
        var agentAction: String
        var proof: [String]
    }

    private func deliveryLaneReadiness(summary providedSummary: MediaReadinessSummary? = nil) -> [DeliveryLaneReadiness] {
        let summary = providedSummary ?? mediaReadinessSummary()
        let noSessionBlocker = "Load an episode session before delivery readiness can be evaluated."
        let renderBlocker = summary.hasSequence ? summary.detail : noSessionBlocker
        let renderReady = summary.isProductionReady
        let audioReadyForPlanning = summary.hasSequence && summary.audioReadyCount > 0 && summary.audioBlockedCount == 0
        let shortClipCount = projectStore.activeSequence?.shortClipQueue.count ?? 0

        func renderLane(
            id: String,
            label: String,
            destinations: [String],
            format: String,
            artifactType: String
        ) -> DeliveryLaneReadiness {
            DeliveryLaneReadiness(
                id: id,
                label: label,
                destinations: destinations,
                artifactType: artifactType,
                format: format,
                status: renderReady ? "ready" : "blocked",
                isReady: renderReady,
                summary: renderReady
                    ? "Proxy-backed render is ready. This proves file creation, not account publishing."
                    : "Render is blocked until the loaded session is proxy-safe.",
                blocker: renderReady ? "" : renderBlocker,
                nextAction: renderReady
                    ? "Run Export Proxy Package, inspect the output, then hand it to the publishing lane."
                    : "Resolve proxy/media readiness before rendering.",
                humanAction: "Export dual-format proxy package",
                agentAction: "GET /export_proxy_package?directory=<absolute-output-folder>&basename=<name>&proof_seconds=<seconds>",
                proof: ["GET /state", "GET /editor_snapshot", "GET /delivery_readiness"]
            )
        }

        return [
            renderLane(
                id: "episode-16x9-master",
                label: "16:9 episode master",
                destinations: ["YouTube", "Patreon"],
                format: "16:9",
                artifactType: "MP4 episode master"
            ),
            renderLane(
                id: "episode-9x16-master",
                label: "9:16 vertical episode render",
                destinations: ["Review", "Shorts source"],
                format: "9:16",
                artifactType: "MP4 vertical master"
            ),
            DeliveryLaneReadiness(
                id: "social-short-clips",
                label: "9:16 social clips",
                destinations: ["YouTube Shorts", "Instagram", "Facebook", "LinkedIn"],
                artifactType: "Short MP4 clip queue",
                format: "9:16",
                status: renderReady && shortClipCount > 0 ? "ready" : renderReady ? "planned" : "blocked",
                isReady: renderReady && shortClipCount > 0,
                summary: renderReady && shortClipCount > 0
                    ? "\(shortClipCount) short candidate(s) are queued and can export as 9:16 MP4 proof files. Batch export is available for publication prep; captions and platform upload are still later lanes."
                    : renderReady
                    ? "The vertical render foundation is ready, but social clips still need explicit clip ranges, captions, and per-platform presets."
                    : "Social clips depend on the episode render foundation first.",
                blocker: renderReady && shortClipCount > 0
                    ? ""
                    : renderReady ? "Needs a short-clip queue and per-platform export presets." : renderBlocker,
                nextAction: renderReady && shortClipCount > 0
                    ? "Batch export queued shorts, review the files, then add captions/templates before platform publishing."
                    : "Add a social clip queue: mark ranges, choose caption/template, render each clip, then publish/schedule.",
                humanAction: "Mark short clip ranges from the edited episode",
                agentAction: "GET /shorts_export_all?directory=<absolute-output-folder>&basename=<name>",
                proof: ["GET /shorts_queue", "GET /shorts_export_all", "GET /state"]
            ),
            DeliveryLaneReadiness(
                id: "podcast-audio-master",
                label: "Podcast audio master",
                destinations: ["Spotify", "Apple Podcasts"],
                artifactType: "Audio master + episode feed metadata",
                format: "audio",
                status: audioReadyForPlanning ? "ready" : "blocked",
                isReady: audioReadyForPlanning,
                summary: audioReadyForPlanning
                    ? "Audio proxies are available and Quipsly can export a proxy-backed M4A audio proof. Loudness normalization, metadata, and podcast host publishing are still next."
                    : "Podcast audio needs ready audio lanes before a master can be generated.",
                blocker: audioReadyForPlanning
                    ? ""
                    : (summary.hasSequence ? summary.detail : noSessionBlocker),
                nextAction: audioReadyForPlanning
                    ? "Export podcast audio proof, inspect it, then add loudness/metadata/feed publishing."
                    : "Recover or generate audio proxies before exporting podcast audio.",
                humanAction: "Prepare podcast audio master",
                agentAction: "GET /audio_master_export?directory=<absolute-output-folder>&basename=<name>&proof_seconds=<seconds>",
                proof: ["GET /audio_master_export", "GET /state", "GET /delivery_readiness"]
            ),
            DeliveryLaneReadiness(
                id: "channel-publishing",
                label: "Direct platform publishing",
                destinations: ["YouTube", "Patreon", "Instagram", "Facebook", "LinkedIn", "Spotify", "Apple Podcasts"],
                artifactType: "Authenticated upload/schedule workflow",
                format: "platform",
                status: "planned",
                isReady: false,
                summary: "Direct channel publishing is intentionally separate from render readiness.",
                blocker: "Needs OAuth/account connections, upload APIs, scheduling, entitlement checks, and publish receipts before this can be called ready.",
                nextAction: "Connect publishing-channel ledger/OAuth flows to exported artifacts and store publish receipts.",
                humanAction: "Connect and schedule channels",
                agentAction: "planned: publishing integration endpoints",
                proof: ["GET /delivery_readiness"]
            )
        ]
    }

    private func deliveryReadinessPayload(summary providedSummary: MediaReadinessSummary? = nil) -> [String: Any] {
        let summary = providedSummary ?? mediaReadinessSummary()
        let lanes = deliveryLaneReadiness(summary: summary)

        return [
            "model": "episode-to-platform-delivery-readiness",
            "version": "2026-06-16.delivery-readiness.v1",
            "sessionName": normalizedActiveSessionName(),
            "sourcePolicy": "proxy-first; originals stay untouched unless explicitly granted",
            "publishingTruth": "Export readiness is not account publishing. Channel OAuth/upload/schedule automation is a separate integration and is not ready until proven.",
            "readyForDirectPublishing": false,
            "renderFoundationReady": summary.isProductionReady,
            "visualRoughCutReady": summary.isVideoRoughCutReady,
            "counts": [
                "readyLanes": lanes.filter { $0.isReady }.count,
                "blockedLanes": lanes.filter { $0.status == "blocked" }.count,
                "plannedLanes": lanes.filter { $0.status == "planned" }.count,
                "videoProxyReady": summary.videoProxyReadyCount,
                "videoBlocked": summary.videoBlockedCount,
                "audioReady": summary.audioReadyCount,
                "audioBlocked": summary.audioBlockedCount,
                "shortClipQueue": projectStore.activeSequence?.shortClipQueue.count ?? 0,
                "showDecisions": summary.showDecisionCount,
                "skipDecisions": summary.skipDecisionCount
            ],
            "lanes": lanes.map { lane in
                [
                    "id": lane.id,
                    "label": lane.label,
                    "destinations": lane.destinations,
                    "artifactType": lane.artifactType,
                    "format": lane.format,
                    "status": lane.status,
                    "ready": lane.isReady,
                    "summary": lane.summary,
                    "blocker": lane.blocker,
                    "nextAction": lane.nextAction,
                    "humanAction": lane.humanAction,
                    "agentAction": lane.agentAction,
                    "proof": lane.proof
                ] as [String: Any]
            }
        ]
    }

    private func deliveryPacketPayload(summary providedSummary: MediaReadinessSummary? = nil) -> [String: Any] {
        let summary = providedSummary ?? mediaReadinessSummary()
        let lanes = deliveryLaneReadiness(summary: summary)
        let artifacts = deliveryPacketArtifacts(lanes: lanes)
        let destinations = deliveryPacketDestinations(artifacts: artifacts, lanes: lanes)
        let formatter = ISO8601DateFormatter()

        return [
            "model": "quipsly-episode-delivery-packet",
            "version": "2026-06-16.delivery-packet.v1",
            "status": deliveryPacketStatus,
            "sessionName": normalizedActiveSessionName(),
            "projectTitle": projectStore.project.title,
            "sequenceTitle": projectStore.activeSequence?.title ?? "",
            "sequenceDuration": projectStore.activeSequence?.duration ?? 0,
            "sourcePolicy": "proxy-first; originals stay untouched unless explicitly granted",
            "editingModel": "whole synced source lanes plus metadata output recipes",
            "publishingTruth": "This packet can make exports inspectable and platform-targeted, but direct upload/scheduling is not ready until channel integrations and receipts exist.",
            "readyForDirectPublishing": false,
            "renderFoundationReady": summary.isProductionReady,
            "visualRoughCutReady": summary.isVideoRoughCutReady,
            "generatedAt": deliveryPacketGeneratedAt.map { formatter.string(from: $0) } ?? "",
            "outputPath": deliveryPacketOutputPath,
            "error": deliveryPacketErrorMessage,
            "lastExportState": exportStatePayload(),
            "readiness": deliveryReadinessPayload(summary: summary),
            "artifacts": artifacts,
            "destinations": destinations,
            "nextHumanActions": deliveryPacketNextActions(lanes: lanes),
            "nextAgentActions": deliveryPacketAgentActions(lanes: lanes)
        ]
    }

    private func deliveryPacketArtifacts(lanes: [DeliveryLaneReadiness]) -> [[String: Any]] {
        lanes
            .filter { $0.id != "channel-publishing" }
            .map { lane in
                let outputPath = deliveryOutputPath(for: lane)
                let hasOutput = outputPath.map { FileManager.default.fileExists(atPath: $0) } ?? false
                let outputBytes = outputPath.flatMap { path -> Int64? in
                    guard let attrs = try? FileManager.default.attributesOfItem(atPath: path),
                          let size = attrs[.size] as? NSNumber else {
                        return nil
                    }
                    return size.int64Value
                }
                let status: String
                if hasOutput {
                    status = "exported"
                } else if lane.isReady {
                    status = "export-needed"
                } else {
                    status = lane.status
                }

                return [
                    "id": "\(lane.id)-artifact",
                    "laneId": lane.id,
                    "label": lane.label,
                    "artifactType": lane.artifactType,
                    "format": lane.format,
                    "status": status,
                    "outputPath": outputPath ?? "",
                    "fileExists": hasOutput,
                    "bytes": outputBytes ?? 0,
                    "destinations": lane.destinations,
                    "sourceExportKind": exportKind,
                    "sourceExportStatus": exportStatus,
                    "sourcePolicy": "proxy-first; output artifact only",
                    "nextAction": hasOutput ? "Review artifact, then attach platform metadata before publishing." : lane.nextAction
                ] as [String: Any]
            }
    }

    private func deliveryPacketDestinations(artifacts: [[String: Any]], lanes: [DeliveryLaneReadiness]) -> [[String: Any]] {
        var rows: [[String: Any]] = []
        for lane in lanes where lane.id != "channel-publishing" {
            let artifact = artifacts.first { ($0["laneId"] as? String) == lane.id }
            let artifactStatus = artifact?["status"] as? String ?? lane.status
            let outputPath = artifact?["outputPath"] as? String ?? ""
            let publishStatus: String
            if artifactStatus == "exported" {
                publishStatus = "artifact-ready-integration-needed"
            } else if lane.isReady {
                publishStatus = "needs-export"
            } else {
                publishStatus = "blocked"
            }

            for destination in lane.destinations {
                rows.append([
                    "platform": destination,
                    "laneId": lane.id,
                    "artifactType": lane.artifactType,
                    "format": lane.format,
                    "artifactStatus": artifactStatus,
                    "publishStatus": publishStatus,
                    "outputPath": outputPath,
                    "receiptStatus": "not-started",
                    "nextAction": artifactStatus == "exported"
                        ? "Add channel metadata/OAuth upload integration and save publish receipt."
                        : lane.nextAction
                ])
            }
        }

        rows.append([
            "platform": "Direct channel publishing",
            "laneId": "channel-publishing",
            "artifactType": "Authenticated upload/schedule workflow",
            "format": "platform",
            "artifactStatus": "planned",
            "publishStatus": "integration-needed",
            "outputPath": "",
            "receiptStatus": "not-started",
            "nextAction": "Build platform OAuth, upload/schedule APIs, entitlement checks, and publish receipts."
        ])
        return rows
    }

    private func deliveryOutputPath(for lane: DeliveryLaneReadiness) -> String? {
        let lowerKind = exportKind.lowercased()
        let existingPaths = exportOutputPaths.filter { FileManager.default.fileExists(atPath: $0) }
        switch lane.id {
        case "podcast-audio-master":
            return existingPaths.first { path in
                let lower = path.lowercased()
                return lower.hasSuffix(".m4a") || lower.hasSuffix(".mp3") || lowerKind.contains("audio")
            }
        case "episode-16x9-master":
            return existingPaths.first { path in
                let lower = path.lowercased()
                return lower.hasSuffix(".mp4") && (lower.contains("16x9") || lower.contains("16-9") || lower.contains("wide"))
            }
        case "episode-9x16-master":
            return existingPaths.first { path in
                let lower = path.lowercased()
                return lower.hasSuffix(".mp4") && !lowerKind.contains("short") && (lower.contains("9x16") || lower.contains("9-16") || lower.contains("vertical"))
            }
        case "social-short-clips":
            return existingPaths.first { path in
                let lower = path.lowercased()
                return lower.hasSuffix(".mp4") && (lowerKind.contains("short") || lower.contains("short"))
            }
        default:
            return nil
        }
    }

    private func deliveryPacketNextActions(lanes: [DeliveryLaneReadiness]) -> [[String: Any]] {
        lanes.map { lane in
            [
                "laneId": lane.id,
                "label": lane.label,
                "status": lane.status,
                "humanAction": lane.humanAction,
                "nextAction": lane.nextAction
            ]
        }
    }

    private func deliveryPacketAgentActions(lanes: [DeliveryLaneReadiness]) -> [[String: Any]] {
        lanes.map { lane in
            [
                "laneId": lane.id,
                "label": lane.label,
                "status": lane.status,
                "agentAction": lane.agentAction,
                "proof": lane.proof
            ]
        }
    }

    private func publishReleaseChecklistPayload(for sequence: MediaSequence?) -> [String: Any] {
        let records = sequence?.publishReceipts ?? []
        var payload = publishReleaseChecklistSummary(records: records)
        payload["model"] = "quipsly-publish-release-checklist"
        payload["version"] = "2026-06-16.publish-release-checklist.v1"
        payload["sessionName"] = normalizedActiveSessionName()
        payload["sequenceTitle"] = sequence?.title ?? ""
        payload["sourcePolicy"] = "checklist reports artifact/copy/receipt truth; it never mutates source media or platform state"
        payload["directPublishingReady"] = false
        payload["nextActions"] = publishReleaseChecklistNextActions(records: records, limit: 8)
        payload["records"] = records.map { publishReleaseChecklistRecordPayload($0) }
        return payload
    }

    private func publishReleaseChecklistSummary(records: [PublishReceiptRecord]) -> [String: Any] {
        let recordCount = records.count
        let artifactReadyCount = records.filter { publishRecordArtifactReady($0) }.count
        let copyReadyCount = records.filter { publishRecordCopyReady($0) }.count
        let receiptCapturedCount = records.filter { publishRecordReceiptCaptured($0) }.count
        let uploadJobReadyCount = records.filter { publishRecordUploadJobReady($0) }.count
        let apiNeededCount = records.filter { $0.uploadJobStatus == "integration-needed" }.count
        let blockedCount = records.filter { publishRecordBlocked($0) }.count
        let readyForManualUploadCount = records.filter {
            publishRecordArtifactReady($0) && publishRecordCopyReady($0) && !publishRecordReceiptCaptured($0)
        }.count

        let readinessLevel: String
        if recordCount == 0 {
            readinessLevel = "no-ledger"
        } else if blockedCount > 0 {
            readinessLevel = "needs-artifacts"
        } else if receiptCapturedCount == recordCount && records.allSatisfy({ $0.publishStatus == "published" }) {
            readinessLevel = "released"
        } else if receiptCapturedCount > 0 {
            readinessLevel = "partially-released"
        } else if artifactReadyCount == recordCount && copyReadyCount == recordCount {
            readinessLevel = "ready-for-manual-upload"
        } else if artifactReadyCount > 0 {
            readinessLevel = "needs-copy-review"
        } else {
            readinessLevel = "drafting"
        }

        return [
            "recordCount": recordCount,
            "artifactReadyCount": artifactReadyCount,
            "copyReadyCount": copyReadyCount,
            "receiptCapturedCount": receiptCapturedCount,
            "uploadJobReadyCount": uploadJobReadyCount,
            "apiNeededCount": apiNeededCount,
            "blockedCount": blockedCount,
            "readyForManualUploadCount": readyForManualUploadCount,
            "readinessLevel": readinessLevel
        ]
    }

    private func publishReleaseChecklistNextActions(records: [PublishReceiptRecord], limit: Int) -> [[String: Any]] {
        if records.isEmpty {
            return [[
                "label": "Generate publish ledger",
                "platform": "",
                "deliveryLaneId": "",
                "action": "Run release prep, then generate the publish ledger so Quipsly has platform-specific records.",
                "agentCommand": "script/agentctl.sh publish-ledger-generate"
            ]]
        }

        let ordered = records.sorted { lhs, rhs in
            let lhsPriority = publishRecordActionPriority(lhs)
            let rhsPriority = publishRecordActionPriority(rhs)
            if lhsPriority == rhsPriority {
                if lhs.deliveryLaneId == rhs.deliveryLaneId {
                    return lhs.platform < rhs.platform
                }
                return lhs.deliveryLaneId < rhs.deliveryLaneId
            }
            return lhsPriority < rhsPriority
        }
        return ordered.prefix(max(1, limit)).map { publishRecordNextAction($0) }
    }

    private func publishReceiptCaptureSummary(records: [PublishReceiptRecord]) -> [String: Any] {
        let captured = records.filter { publishRecordReceiptCaptured($0) }
        let missing = records.filter { !publishRecordReceiptCaptured($0) }
        let readyMissing = publishReceiptCaptureReadyMissingRecords(records: records)
        return [
            "model": "quipsly-publish-receipt-capture-summary",
            "version": "2026-06-17.publish-receipt-capture.v1",
            "recordCount": records.count,
            "capturedCount": captured.count,
            "missingCount": missing.count,
            "readyForReceiptCaptureCount": readyMissing.count,
            "capturedRecords": captured.map { publishReceiptCaptureRecordPayload($0) },
            "readyForReceiptCaptureRecords": readyMissing.map { publishReceiptCaptureRecordPayload($0) },
            "missingReceiptRecords": missing.map { publishReceiptCaptureRecordPayload($0) },
            "operatorRule": "After every manual upload or schedule, capture the public or scheduled URL on the exact publish receipt before moving to the next artifact."
        ]
    }

    private func publishReceiptCaptureReadyMissingRecords(records: [PublishReceiptRecord]) -> [PublishReceiptRecord] {
        records
            .filter {
                publishRecordArtifactReady($0)
                    && publishRecordCopyReady($0)
                    && !publishRecordReceiptCaptured($0)
            }
            .sorted { lhs, rhs in
                let leftPriority = publishRecordActionPriority(lhs)
                let rightPriority = publishRecordActionPriority(rhs)
                if leftPriority == rightPriority {
                    return publishReceiptDisplayLabel(lhs) < publishReceiptDisplayLabel(rhs)
                }
                return leftPriority < rightPriority
            }
    }

    private func publishReceiptCaptureRecordPayload(_ record: PublishReceiptRecord) -> [String: Any] {
        [
            "id": record.id.uuidString,
            "displayLabel": publishReceiptDisplayLabel(record),
            "platform": record.platform,
            "deliveryLaneId": record.deliveryLaneId,
            "title": record.title,
            "artifactPath": record.artifactPath,
            "format": record.format,
            "publishStatus": record.publishStatus,
            "publicURL": record.publicURL,
            "providerReceiptId": record.providerReceiptId,
            "receiptCaptured": publishRecordReceiptCaptured(record),
            "agentCaptureCommand": "script/agentctl.sh publish-receipt-update \(record.id.uuidString) published <public-url> <provider-id> \"manual receipt\""
        ]
    }

    private func publishUploadPacketPayload(_ record: PublishReceiptRecord) -> [String: Any] {
        let metadataObject = parseJSONObject(record.metadataJson) ?? [:]
        let uploadJobObject = parseJSONObject(record.uploadJobJson) ?? [:]
        return [
            "model": "quipsly-publish-upload-packet",
            "version": "2026-06-17.publish-upload-packet.v1",
            "receiptId": record.id.uuidString,
            "displayLabel": publishReceiptDisplayLabel(record),
            "platform": record.platform,
            "deliveryLaneId": record.deliveryLaneId,
            "destinationId": publishDestinationId(for: record),
            "destinationGuidance": publishDestinationGuidance(for: record),
            "title": record.title,
            "description": record.description,
            "artifactPath": record.artifactPath,
            "artifactType": record.artifactType,
            "artifactStatus": record.artifactStatus,
            "artifactExists": publishRecordArtifactExists(record),
            "format": record.format,
            "metadataStatus": record.metadataStatus,
            "metadata": metadataObject,
            "uploadJobKind": record.uploadJobKind,
            "uploadJobStatus": record.uploadJobStatus,
            "uploadJob": uploadJobObject,
            "publishStatus": record.publishStatus,
            "publicURL": record.publicURL,
            "providerReceiptId": record.providerReceiptId,
            "receiptCaptured": publishRecordReceiptCaptured(record),
            "sourcePolicy": "This packet references rendered derivative artifacts only; source media remains untouched.",
            "manualUploadChecklist": [
                "Confirm artifactExists is true.",
                "Open artifactPath and watch/listen once before upload.",
                "Use title and description as the platform copy draft.",
                "Upload or schedule manually until direct platform connectors are proven.",
                "After upload/schedule, capture the public or scheduled URL back onto this receipt."
            ],
            "agentReceiptCommand": "script/agentctl.sh publish-receipt-update \(record.id.uuidString) published <public-url> <provider-id> \"manual receipt\""
        ]
    }

    private func publishReleaseChecklistRecordPayload(_ record: PublishReceiptRecord) -> [String: Any] {
        [
            "id": record.id.uuidString,
            "displayLabel": publishReceiptDisplayLabel(record),
            "laneDisplayLabel": publishReceiptLaneDisplayLabel(record),
            "platform": record.platform,
            "deliveryLaneId": record.deliveryLaneId,
            "artifactPath": record.artifactPath,
            "artifactStatus": record.artifactStatus,
            "artifactExists": publishRecordArtifactExists(record),
            "artifactReady": publishRecordArtifactReady(record),
            "copyReady": publishRecordCopyReady(record),
            "uploadJobReady": publishRecordUploadJobReady(record),
            "apiNeeded": record.uploadJobStatus == "integration-needed",
            "receiptCaptured": publishRecordReceiptCaptured(record),
            "blocked": publishRecordBlocked(record),
            "publishStatus": record.publishStatus,
            "metadataStatus": record.metadataStatus,
            "uploadJobStatus": record.uploadJobStatus,
            "publicURL": record.publicURL,
            "providerReceiptId": record.providerReceiptId,
            "nextAction": publishRecordNextAction(record),
            "uploadPacket": publishUploadPacketPayload(record)
        ]
    }

    private func publishRecordActionPriority(_ record: PublishReceiptRecord) -> Int {
        if publishRecordBlocked(record) { return 0 }
        if !publishRecordCopyReady(record) { return 1 }
        if !publishRecordReceiptCaptured(record) { return 2 }
        if record.publishStatus != "published" { return 3 }
        return 4
    }

    private func publishRecordNextAction(_ record: PublishReceiptRecord) -> [String: Any] {
        let label = publishReceiptDisplayLabel(record)
        let command = "script/agentctl.sh publish-receipt-update-platform \"\(record.platform)\" \"\(record.deliveryLaneId)\" published <public-url> <provider-id>"
        let action: String
        if publishRecordBlocked(record) {
            action = "Export or repair the artifact for \(record.platform); current artifact status is \(record.artifactStatus.isEmpty ? "unknown" : record.artifactStatus)."
        } else if !publishRecordCopyReady(record) {
            action = "Review title, description, and metadata JSON before upload."
        } else if !publishRecordReceiptCaptured(record) {
            action = record.uploadJobStatus == "integration-needed"
                ? "Manual upload/schedule is ready; direct \(record.platform) API publishing is not wired yet, so save the receipt afterward."
                : "Upload or schedule this artifact, then save the receipt."
        } else if record.publishStatus != "published" {
            action = "Confirm the live URL when \(record.platform) publishes, then mark the receipt published."
        } else {
            action = "Published receipt captured. Future analytics can attach here."
        }

        return [
            "label": label,
            "laneDisplayLabel": publishReceiptLaneDisplayLabel(record),
            "platform": record.platform,
            "deliveryLaneId": record.deliveryLaneId,
            "publishStatus": record.publishStatus,
            "action": action,
            "agentCommand": command
        ]
    }

    private func publishRecordArtifactExists(_ record: PublishReceiptRecord) -> Bool {
        let path = record.artifactPath.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !path.isEmpty else { return false }
        guard publishRecordArtifactPathIsProductionHandoff(path) else { return false }
        return FileManager.default.fileExists(atPath: path)
    }

    private func publishRecordArtifactPathIsProductionHandoff(_ path: String) -> Bool {
        let lowercased = path.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !lowercased.isEmpty else { return false }
        let smokeOrTemporaryMarkers = [
            "/tmp/",
            "/var/folders/",
            "quipslystudio-publish-ledger-smoke",
            "smoke-ledger"
        ]
        return !smokeOrTemporaryMarkers.contains { lowercased.contains($0) }
    }

    private func publishRecordArtifactReady(_ record: PublishReceiptRecord) -> Bool {
        record.artifactStatus == "exported" && publishRecordArtifactExists(record)
    }

    private func publishRecordCopyReady(_ record: PublishReceiptRecord) -> Bool {
        !record.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && !record.description.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && !record.metadataJson.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    private func publishRecordUploadJobReady(_ record: PublishReceiptRecord) -> Bool {
        !record.uploadJobKind.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && !record.uploadJobStatus.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && !record.uploadJobJson.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    private func publishRecordReceiptCaptured(_ record: PublishReceiptRecord) -> Bool {
        hasRealPublicationProof(record.publicURL)
            || hasRealPublicationProof(record.providerReceiptId)
            || hasRealPublicationProof(record.receiptJson)
    }

    private func hasRealPublicationProof(_ value: String) -> Bool {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }
        let lowercased = trimmed.lowercased()
        let placeholderMarkers = [
            "<public-url>",
            "<provider-id>",
            "<public-or-scheduled-url>",
            "<provider-id-or-scheduled-id>",
            "example.com",
            "quipsly-smoke",
            "smoke-",
            "provider-id",
            "manual receipt placeholder"
        ]
        return !placeholderMarkers.contains { lowercased.contains($0) }
    }

    private func publishRecordBlocked(_ record: PublishReceiptRecord) -> Bool {
        if ["blocked", "failed", "needs-export"].contains(record.publishStatus) {
            return true
        }
        if record.publishStatus == "published" || publishRecordReceiptCaptured(record) {
            return false
        }
        return !publishRecordArtifactReady(record)
    }

