    private func publicationReceiptCompletionSummary(for sequence: MediaSequence?) -> [String: Any] {
        let records = sequence?.publishReceipts ?? []
        let captured = records.filter { publishRecordReceiptCaptured($0) }.count
        let remaining = max(0, records.count - captured)
        let complete = !records.isEmpty && remaining == 0
        return [
            "receiptTotalCount": records.count,
            "receiptCapturedCount": captured,
            "receiptRemainingCount": remaining,
            "publicationComplete": complete,
            "publicationPhase": complete ? "publication-complete" : "ready-for-human-review"
        ]
    }

    private func publicationReadyHandoffPayload(for sequence: MediaSequence?) -> [String: Any] {
        let records = sequence?.publishReceipts ?? []
        let episodeRecords = records.filter { $0.deliveryLaneId == "episode-16x9-master" }
        let ledgerEpisodeReady = episodeRecords.contains { publishRecordArtifactReady($0) && publishRecordCopyReady($0) }
        let completedExportArtifacts = exportArtifactStatePayloads()
        let completedEpisodeMasterPath = completedExportArtifacts.first { artifact in
            (artifact["kind"] as? String) == "episode-master"
                && (artifact["status"] as? String) == "ready"
                && fileSize(atPath: artifact["path"] as? String ?? "") > 0
        }?["path"] as? String ?? ""
        let episodeMasterPath = episodeRecords.first?.artifactPath.trimmingCharacters(in: .whitespacesAndNewlines) ?? completedEpisodeMasterPath
        let episodeMasterReady = fileSize(atPath: episodeMasterPath) > 0
        let episodeReady = ledgerEpisodeReady || episodeMasterReady
        let episodeReceiptCaptured = episodeRecords.contains { publishRecordReceiptCaptured($0) }
        let socialLoaded = socialMasterQueueClipCount > 0 && socialMasterQueueStatus == "loaded"
        let socialReadyPath = socialMasterQueueOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        let socialFinalFolderPath = episode1FinalSocialPostingPacketFolderPath
        let socialFinalManifestPath = episode1FinalSocialPostingPacketManifestPath
        let podcastReadyPath = podcastReadyPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        let podcastReadyFolderPath = podcastReadyPath.isEmpty ? "" : URL(fileURLWithPath: podcastReadyPath).deletingLastPathComponent().path
        let podcastReady = podcastReadyPacketStatus == "generated" && !podcastReadyPath.isEmpty && FileManager.default.fileExists(atPath: podcastReadyPath)
        let podcastTargets = podcastReceiptTargetsPayload(records: records)
        let podcastReceiptCaptured = podcastTargets.contains { ($0["receiptCaptured"] as? Bool) == true }
        let readyLaneCount = [episodeReady, socialLoaded, podcastReady].filter { $0 }.count
        let receiptSummary = publicationReceiptCompletionSummary(for: sequence)

        return [
            "model": "quipsly-publication-ready-handoff",
            "version": "2026-06-17.publication-ready-handoff.v1",
            "readyLaneCount": readyLaneCount,
            "laneCount": 3,
            "publishingTruth": "Local handoff artifacts can be ready before anything is uploaded. Platform publication is only true after receipt capture.",
            "receiptProof": [
                "summary": receiptSummary,
                "missingReceipts": missingPublicationReceiptsPayload(for: sequence),
                "operatorArtifacts": [
                    "receiptLogPath": publicationReceiptLogOutputPath,
                    "publishPacketPath": publishPacketOutputPath,
                    "uploadPacketBundlePath": publishUploadBundleOutputPath,
                    "publicationCockpitPath": publicationCockpitOutputPath
                ],
                "missingReceiptsCommand": "script/agentctl.sh missing-publication-receipts",
                "nextAction": (receiptSummary["publicationComplete"] as? Bool) == true
                    ? "Publication proof is complete. Keep the receipt log with the release folder."
                    : "After each manual/API upload or schedule, capture the platform URL/provider id back into Quipsly."
            ],
            "episode16x9": [
                "status": episodeReady
                    ? (episodeReceiptCaptured
                       ? "receipt-captured"
                       : (ledgerEpisodeReady ? "ready-for-youtube-patreon" : "master-rendered-needs-publish-packet"))
                    : "needs-release-prep",
                "artifactPath": episodeMasterPath,
                "operatorArtifacts": [
                    "masterPath": episodeMasterPath,
                    "publishPacketPath": publishPacketOutputPath,
                    "uploadPacketBundlePath": publishUploadBundleOutputPath,
                    "publicationCockpitPath": publicationCockpitOutputPath
                ],
                "receiptCaptured": episodeReceiptCaptured,
                "nextAction": episodeReady
                    ? (ledgerEpisodeReady
                       ? "Upload or schedule to YouTube/Patreon, then capture receipt."
                       : "Generate the publish packet/upload handoff for this rendered master, or manually upload then capture receipt.")
                    : "Run Full prep."
            ],
            "social9x16": [
                "status": socialLoaded ? "ready-for-social-review" : "needs-social-ready-packet",
                "clipCount": socialMasterQueueClipCount,
                "manifestPath": socialReadyPath,
                "operatorArtifacts": [
                    "loadedManifestPath": socialReadyPath,
                    "finalManifestPath": socialFinalManifestPath,
                    "finalFolderPath": socialFinalFolderPath,
                    "startHerePath": "\(socialFinalFolderPath)/START-HERE-EPISODE1-SOCIAL-PUBLISHING.md",
                    "postingTrackerPath": "\(socialFinalFolderPath)/episode1-the-wednesday-rule-platform-posting-tracker.csv",
                    "zipPath": "\(socialFinalFolderPath).zip",
                    "handoffPath": "\(socialFinalFolderPath)/episode1-the-wednesday-rule-social-posting-handoff.json"
                ],
                "receiptCaptureAvailable": !socialMasterQueueCandidatePreview.isEmpty,
                "nextAction": socialLoaded ? "Review top clips, post/schedule manually, then capture receipts." : "Generate or load the social ready packet."
            ],
            "podcastAudio": [
                "status": podcastReady ? (podcastReceiptCaptured ? "receipt-captured" : "ready-for-spotify-apple-handoff") : "needs-podcast-ready-packet",
                "manifestPath": podcastReadyPath,
                "operatorArtifacts": [
                    "readyManifestPath": podcastReadyPath,
                    "readyFolderPath": podcastReadyFolderPath,
                    "sourcePodcastManifestPath": podcastPacketOutputPath
                ],
                "receiptCaptured": podcastReceiptCaptured,
                "nextAction": podcastReady ? "Listen-check, upload via podcast host/RSS, then capture Spotify/Apple URLs." : "Generate Podcast Packet, then Podcast Ready."
            ]
        ]
    }

    private func publicationMissionControlPayload(for sequence: MediaSequence?) -> [String: Any] {
        let records = sequence?.publishReceipts ?? []
        let handoff = publicationReadyHandoffPayload(for: sequence)
        let missingReceipts = missingPublicationReceiptsPayload(for: sequence)
        let receiptSummary = publicationReceiptCompletionSummary(for: sequence)
        let readyLaneCount = handoff["readyLaneCount"] as? Int ?? 0
        let laneCount = handoff["laneCount"] as? Int ?? 3
        let missingCount = missingReceipts["missingCount"] as? Int ?? records.count
        let publicationComplete = receiptSummary["publicationComplete"] as? Bool ?? false
        let socialLoaded = socialMasterQueueClipCount > 0 && socialMasterQueueStatus == "loaded"
        let podcastReady = podcastReadyPacketStatus == "generated"
            && !podcastReadyPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && FileManager.default.fileExists(atPath: podcastReadyPacketOutputPath)
        let status: String
        if sequence == nil {
            status = "no-sequence-loaded"
        } else if records.isEmpty {
            status = "needs-full-release-prep"
        } else if publicationComplete {
            status = "publication-proof-complete"
        } else if readyLaneCount == laneCount {
            status = "ready-for-platform-posting"
        } else {
            status = "needs-handoff-artifacts"
        }

        return [
            "model": "quipsly-publication-mission-control",
            "version": "2026-06-17.publication-mission-control.v1",
            "status": status,
            "sessionName": normalizedActiveSessionName(),
            "sequenceTitle": sequence?.title ?? "",
            "summary": [
                "readyLaneCount": readyLaneCount,
                "laneCount": laneCount,
                "publishLedgerRecordCount": records.count,
                "missingReceiptCount": missingCount,
                "publicationComplete": publicationComplete,
                "socialQueueLoaded": socialLoaded,
                "podcastReadyPacketGenerated": podcastReady
            ] as [String: Any],
            "deliverables": [
                [
                    "id": "episode-16x9-master",
                    "label": "16:9 episode master",
                    "destinations": ["YouTube", "Patreon"],
                    "state": handoff["episode16x9"] ?? [:],
                    "nextCommand": "script/agentctl.sh publication-ready-handoff"
                ] as [String: Any],
                [
                    "id": "social-9x16-shorts",
                    "label": "9:16 social shorts",
                    "destinations": ["YouTube Shorts", "Instagram", "Facebook", "LinkedIn"],
                    "state": handoff["social9x16"] ?? [:],
                    "selectedPostingPacket": socialMasterQueueStatePayload()["selectedPostingPacket"] ?? [:],
                    "postingReadiness": socialMasterQueuePostingReadinessPayload(),
                    "nextCommand": socialLoaded ? "script/agentctl.sh selected-social-posting-packet" : "script/agentctl.sh episode1-socials-load"
                ] as [String: Any],
                [
                    "id": "podcast-audio",
                    "label": "Podcast audio handoff",
                    "destinations": ["Spotify", "Apple Podcasts"],
                    "state": handoff["podcastAudio"] ?? [:],
                    "nextCommand": podcastReady ? "script/agentctl.sh podcast-ready-packet" : "script/agentctl.sh podcast-ready-packet-generate /absolute/podcast-manifest.json /absolute/output/folder optional-basename --zip"
                ] as [String: Any]
            ],
            "receiptProof": handoff["receiptProof"] ?? [:],
            "missingReceipts": missingReceipts,
            "commands": [
                "inspect": "script/agentctl.sh publication-mission-control",
                "handoff": "script/agentctl.sh publication-ready-handoff",
                "missingReceipts": "script/agentctl.sh missing-publication-receipts",
                "selectedSocialPostingPacket": "script/agentctl.sh selected-social-posting-packet",
                "loadEpisode1SocialPacket": "script/agentctl.sh episode1-socials-load",
                "fullReleasePrep": "script/agentctl.sh full-release-prepare /absolute/output/folder basename 8",
                "publicationCockpit": "script/agentctl.sh publication-cockpit-generate /absolute/output/folder optional-basename"
            ],
            "nextAction": sequence == nil
                ? "Load an episode session before publishing."
                : (records.isEmpty
                    ? "Run Full prep to export derivative artifacts and generate the publish ledger."
                    : (publicationComplete
                        ? "Publication proof is complete. Keep the receipt log with the release folder."
                        : (readyLaneCount == laneCount
                            ? "Post or schedule the ready artifacts, then capture every platform URL/provider receipt."
                            : "Generate the missing handoff artifacts before platform posting."))),
            "sourcePolicy": "Mission control is read-only. It aggregates rendered derivative artifacts, packet paths, selected social posting state, and receipt proof without touching source media or edit decisions."
        ]
    }

