    private func selectedSocialMasterQueuePostingPacketPayload() -> [String: Any] {
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            return [
                "model": "quipsly-selected-social-posting-packet",
                "version": "2026-06-17.selected-social-posting-packet.v1",
                "status": "no-candidate-selected",
                "readyToPost": false,
                "summary": "Load and select a social candidate before building a posting packet."
            ]
        }

        let clipPath = (candidate["clipPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let thumbnailPath = (candidate["thumbnailPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let captionPath = (candidate["captionSrtPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let copyPath = (candidate["platformCopyPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let artifactReadiness = selectedSocialMasterQueueArtifactReadinessPayload()
        let receiptChecklist = selectedSocialMasterQueueReceiptChecklistPayload()
        let readyToReview = artifactReadiness["readyToReview"] as? Bool ?? false
        let readyReceiptCount = receiptChecklist["readyPlatformCount"] as? Int ?? 0
        let platformCopy: [String: Any]

        if copyPath.isEmpty {
            platformCopy = [
                "path": "",
                "status": "missing",
                "text": ""
            ]
        } else {
            do {
                platformCopy = [
                    "path": copyPath,
                    "status": "loaded",
                    "text": try String(contentsOfFile: copyPath, encoding: .utf8)
                ]
            } catch {
                platformCopy = [
                    "path": copyPath,
                    "status": "unreadable",
                    "error": error.localizedDescription,
                    "text": ""
                ]
            }
        }

        return [
            "model": "quipsly-selected-social-posting-packet",
            "version": "2026-06-17.selected-social-posting-packet.v1",
            "status": readyToReview ? "ready-for-human-posting-review" : "needs-artifacts",
            "readyToPost": readyToReview,
            "selectedCandidateRank": candidate["rank"] ?? "",
            "title": candidate["title"] ?? "",
            "hook": candidate["hook"] ?? "",
            "durationSeconds": candidate["duration"] ?? "",
            "sourcePack": candidate["sourcePack"] ?? "",
            "candidate": candidate,
            "platforms": socialMasterQueueSelectedPlatforms(),
            "artifacts": [
                "clipPath": clipPath,
                "clipExists": !clipPath.isEmpty && FileManager.default.fileExists(atPath: clipPath),
                "thumbnailPath": thumbnailPath,
                "thumbnailExists": !thumbnailPath.isEmpty && FileManager.default.fileExists(atPath: thumbnailPath),
                "captionSrtPath": captionPath,
                "captionSrtExists": !captionPath.isEmpty && FileManager.default.fileExists(atPath: captionPath),
                "platformCopyPath": copyPath,
                "platformCopyExists": !copyPath.isEmpty && FileManager.default.fileExists(atPath: copyPath)
            ] as [String: Any],
            "platformCopy": platformCopy,
            "artifactReadiness": artifactReadiness,
            "receiptChecklist": receiptChecklist,
            "readyReceiptPlatformCount": readyReceiptCount,
            "commands": [
                "inspect": "script/agentctl.sh selected-social-posting-packet",
                "openClip": "script/agentctl.sh social-master-open-selected-clip",
                "copyPlatformCopy": "script/agentctl.sh social-master-copy-selected-platform-copy",
                "receiptChecklist": "script/agentctl.sh selected-social-receipts",
                "captureReceipt": "script/agentctl.sh social-master-queue-receipt <rank> \"YouTube Shorts\" published <public-url> <provider-id> \"manual receipt\""
            ],
            "safeChecklist": [
                "Watch the derivative 9:16 clip once before posting.",
                "Read the loaded platform copy and adjust it for the target platform if needed.",
                "Attach captions/SRT when the platform supports it.",
                "Post or schedule manually/API-side.",
                "Capture the real public URL, scheduled URL, or provider receipt back into Quipsly."
            ],
            "proofRule": "A platform is not complete until a real public/scheduled URL or provider receipt is captured.",
            "sourcePolicy": "Posting packets reference derivative clips, copy, captions, thumbnails, and receipts only. They do not mutate source media or edit decisions.",
            "nonGoals": [
                "This packet does not upload, schedule, or publish.",
                "This packet does not claim receipt proof without a platform URL/provider receipt.",
                "This packet does not touch source media."
            ]
        ]
    }

    private func selectedSocialMasterQueueReceiptChecklistPayload() -> [String: Any] {
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            return [
                "status": "no-candidate-selected",
                "readyPlatformCount": 0,
                "blockedPlatformCount": 0,
                "items": [],
                "summary": "Load and select a social candidate before receipt capture."
            ]
        }

        let platforms = socialMasterQueueSelectedPlatforms()
        let items: [[String: Any]] = platforms.map { platform in
            let receiptId = socialMasterQueueSelectedReceiptId(platform: platform)
            let ready = !receiptId.isEmpty
            return [
                "platform": platform,
                "receiptId": receiptId,
                "readyForCapture": ready,
                "candidateRank": candidate["rank"] ?? "",
                "title": candidate["title"] ?? "",
                "clipPath": candidate["clipPath"] ?? "",
                "platformCopyPath": candidate["platformCopyPath"] ?? "",
                "captionSrtPath": candidate["captionSrtPath"] ?? "",
                "captureCommand": ready
                    ? "script/agentctl.sh social-master-queue-receipt \(candidate["rank"] ?? "") \"\(platform)\" published <public-url> <provider-id> \"manual receipt\""
                    : "No receipt id is attached for \(platform). Generate/promote a publish receipt before claiming Quipsly captured this post.",
                "proofRule": "Only mark this platform uploaded, scheduled, or published after a real public/scheduled URL or provider receipt exists."
            ] as [String: Any]
        }
        let readyCount = items.filter { ($0["readyForCapture"] as? Bool) == true }.count
        return [
            "model": "quipsly-selected-social-receipt-checklist",
            "version": "2026-06-17.selected-social-receipt-checklist.v1",
            "status": readyCount == 0 ? "needs-receipt-ids" : "ready-for-receipt-capture",
            "selectedCandidateRank": candidate["rank"] ?? "",
            "selectedTitle": candidate["title"] ?? "",
            "readyPlatformCount": readyCount,
            "blockedPlatformCount": max(0, items.count - readyCount),
            "items": items,
            "nextAction": readyCount == 0
                ? "Promote/generate platform receipt rows for this selected candidate before claiming Quipsly captured publication proof."
                : "Post or schedule manually/API-side, then run the listed capture command for each platform URL/provider receipt.",
            "nonGoals": [
                "This checklist does not upload, schedule, or publish.",
                "Do not mark a platform complete without a real URL or provider receipt.",
                "Do not mutate source media or edit decisions from receipt capture."
            ]
        ]
    }

    private func selectedSocialMasterQueueArtifactReadinessPayload() -> [String: Any] {
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            return [
                "status": "no-candidate-selected",
                "readyToReview": false,
                "items": []
            ]
        }

        let specs: [(key: String, label: String, required: Bool)] = [
            ("clipPath", "derivative clip", true),
            ("thumbnailPath", "thumbnail", false),
            ("captionSrtPath", "captions", false),
            ("platformCopyPath", "platform copy", true)
        ]
        let items = specs.map { spec -> [String: Any] in
            let path = (candidate[spec.key] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
            let exists = !path.isEmpty && FileManager.default.fileExists(atPath: path)
            return [
                "key": spec.key,
                "label": spec.label,
                "path": path,
                "required": spec.required,
                "exists": exists,
                "status": exists ? "ready" : (spec.required ? "missing-required" : "missing-optional")
            ]
        }
        let missingRequired = items.contains { item in
            (item["required"] as? Bool ?? false) && !(item["exists"] as? Bool ?? false)
        }
        return [
            "status": missingRequired ? "needs-files" : "ready-to-review",
            "readyToReview": !missingRequired,
            "items": items
        ]
    }

    private func selectedSocialMasterQueueCandidate() -> [String: String]? {
        if !selectedSocialMasterQueueRank.isEmpty,
           let candidate = socialMasterQueueCandidatePreview.first(where: { ($0["rank"] ?? "") == selectedSocialMasterQueueRank }) {
            return candidate
        }
        return socialMasterQueueCandidatePreview.first
    }

