    private func publishConnectorReadinessPayload(for sequence: MediaSequence?) -> [String: Any] {
        let records = sequence?.publishReceipts ?? []
        let connectorRows = records.map { publishConnectorReadinessRow(for: $0) }
        let manualReadyCount = connectorRows.filter {
            let status = $0["manualStatus"] as? String
            return status == "ready-for-manual-upload" || status == "receipt-captured"
        }.count
        let receiptCapturedCount = connectorRows.filter { ($0["receiptCaptured"] as? Bool) == true }.count
        let artifactReadyCount = connectorRows.filter { ($0["artifactReady"] as? Bool) == true }.count
        let copyReadyCount = connectorRows.filter { ($0["copyReady"] as? Bool) == true }.count
        let blockedCount = connectorRows.filter { ($0["blocked"] as? Bool) == true }.count
        let directReadyCount = connectorRows.filter { ($0["directUploadReady"] as? Bool) == true }.count

        return [
            "model": "quipsly-publish-connector-readiness",
            "version": "2026-06-16.publish-connector-readiness.v1",
            "sessionName": normalizedActiveSessionName(),
            "recordCount": records.count,
            "manualReadyCount": manualReadyCount,
            "artifactReadyCount": artifactReadyCount,
            "copyReadyCount": copyReadyCount,
            "receiptCapturedCount": receiptCapturedCount,
            "blockedCount": blockedCount,
            "directReadyCount": directReadyCount,
            "directPublishingReady": records.count > 0 && directReadyCount == records.count,
            "manualPublishingReady": records.count > 0 && manualReadyCount > 0,
            "connectorPolicy": "Direct platform upload is not ready until a connector has auth, executable upload code, and receipt capture proof. Manual upload can proceed from ready artifacts and copy.",
            "rows": connectorRows,
            "nextActions": publishConnectorNextActions(rows: connectorRows)
        ]
    }

    private func publishConnectorReadinessRow(for record: PublishReceiptRecord) -> [String: Any] {
        let artifactReady = publishRecordArtifactReady(record)
        let copyReady = publishRecordCopyReady(record)
        let receiptCaptured = publishRecordReceiptCaptured(record)
        let blocked = publishRecordBlocked(record)
        let directUploadReady = publishDirectUploadReady(for: record)
        let manualStatus: String
        if receiptCaptured {
            manualStatus = "receipt-captured"
        } else if artifactReady && copyReady {
            manualStatus = "ready-for-manual-upload"
        } else if blocked {
            manualStatus = "blocked"
        } else {
            manualStatus = "needs-prep"
        }
        let connectorStatus: String
        if directUploadReady {
            connectorStatus = "direct-upload-ready"
        } else if artifactReady && copyReady {
            connectorStatus = "manual-ready-api-missing"
        } else if blocked {
            connectorStatus = "blocked-before-upload"
        } else {
            connectorStatus = "needs-artifact-or-copy"
        }

        return [
            "platform": record.platform,
            "deliveryLaneId": record.deliveryLaneId,
            "artifactType": record.artifactType,
            "format": record.format,
            "destinationId": publishDestinationId(for: record),
            "destinationGuidance": publishDestinationGuidance(for: record),
            "artifactPath": record.artifactPath,
            "artifactReady": artifactReady,
            "copyReady": copyReady,
            "receiptCaptured": receiptCaptured,
            "blocked": blocked,
            "publishStatus": record.publishStatus,
            "manualStatus": manualStatus,
            "connectorStatus": connectorStatus,
            "directUploadReady": directUploadReady,
            "uploadJobKind": record.uploadJobKind.isEmpty ? defaultUploadJobKind(platform: record.platform) : record.uploadJobKind,
            "uploadJobStatus": record.uploadJobStatus,
            "requiredIntegration": requiredIntegration(platform: record.platform),
            "safeAgentAction": directUploadReady ? "ready-for-upload-worker" : "prepare-manual-handoff-or-build-connector",
            "proofRequired": [
                "artifact exists at artifactPath",
                "title and description are present",
                "platform auth is connected",
                "upload worker returns provider receipt or public URL",
                "receipt is written back to publish ledger"
            ],
            "nextAction": publishConnectorNextAction(for: record, artifactReady: artifactReady, copyReady: copyReady, receiptCaptured: receiptCaptured, blocked: blocked)
        ] as [String: Any]
    }

    private func publishDirectUploadReady(for record: PublishReceiptRecord) -> Bool {
        let status = record.uploadJobStatus.trimmingCharacters(in: .whitespacesAndNewlines)
        return status == "direct-upload-ready"
    }

    private func publishConnectorNextActions(rows: [[String: Any]]) -> [[String: Any]] {
        rows
            .filter { ($0["receiptCaptured"] as? Bool) != true }
            .prefix(8)
            .map { row in
                [
                    "platform": row["platform"] ?? "",
                    "deliveryLaneId": row["deliveryLaneId"] ?? "",
                    "status": row["connectorStatus"] ?? "",
                    "action": row["nextAction"] ?? ""
                ] as [String: Any]
            }
    }

    private func publishConnectorNextAction(for record: PublishReceiptRecord, artifactReady: Bool, copyReady: Bool, receiptCaptured: Bool, blocked: Bool) -> String {
        if receiptCaptured {
            return "Receipt captured. Future analytics can attach to this platform record."
        }
        if artifactReady && copyReady {
            return "Manual upload is ready. Direct API upload still needs \(requiredIntegration(platform: record.platform)) and receipt-write proof."
        }
        if blocked {
            return "Resolve the artifact or export blocker before platform upload."
        }
        if !artifactReady {
            return "Run full release prep or export the required artifact first."
        }
        if !copyReady {
            return "Add title, description, and metadata copy before upload."
        }
        return "Prepare platform handoff."
    }

    private func publishConnectorPreflightPayload(for sequence: MediaSequence?) -> [String: Any] {
        let records = sequence?.publishReceipts ?? []
        let rows = records.map { publishConnectorPreflightRow(for: $0) }
        let readyCount = rows.filter { ($0["status"] as? String) == "ready-for-upload-worker" }.count
        let authMissingCount = rows.filter { ($0["authConfigured"] as? Bool) != true }.count
        let workerMissingCount = rows.filter { ($0["workerExecutableReady"] as? Bool) != true }.count
        let bundledDryRunWorkerReadyCount = rows.filter { ($0["bundledDryRunWorkerExecutableReady"] as? Bool) == true }.count
        let artifactMissingCount = rows.filter { ($0["artifactReady"] as? Bool) != true }.count
        let copyMissingCount = rows.filter { ($0["copyReady"] as? Bool) != true }.count

        return [
            "model": "quipsly-publish-connector-preflight",
            "version": "2026-06-16.publish-connector-preflight.v1",
            "sessionName": normalizedActiveSessionName(),
            "recordCount": records.count,
            "readyCount": readyCount,
            "authMissingCount": authMissingCount,
            "workerMissingCount": workerMissingCount,
            "bundledDryRunWorkerReadyCount": bundledDryRunWorkerReadyCount,
            "artifactMissingCount": artifactMissingCount,
            "copyMissingCount": copyMissingCount,
            "safeToUploadAutomatically": records.count > 0 && readyCount == records.count,
            "secretPolicy": "Only environment variable names and booleans are reported. Secret values are never exposed.",
            "connectorPolicy": "Upload workers may run only when artifact, copy, auth, executable worker, and receipt-write path are all proven.",
            "dryRunWorkerPolicy": "Bundled workers are proof tools. They validate payloads and ledger safety, but they do not replace real auth-backed upload workers.",
            "rows": rows,
            "nextActions": publishConnectorPreflightNextActions(rows: rows)
        ]
    }

    private func publishConnectorWorkerStatePayload() -> [String: Any] {
        let formatter = ISO8601DateFormatter()
        return [
            "model": "quipsly-publish-connector-worker-state",
            "version": "2026-06-16.publish-connector-worker-state.v1",
            "status": publishConnectorWorkerStatus,
            "platform": publishConnectorWorkerPlatform,
            "deliveryLaneId": publishConnectorWorkerLaneId,
            "workerPath": publishConnectorWorkerPath,
            "payloadPath": publishConnectorWorkerPayloadPath,
            "resultJson": publishConnectorWorkerResultJson,
            "error": publishConnectorWorkerErrorMessage,
            "updatedAt": publishConnectorWorkerUpdatedAt.map { formatter.string(from: $0) } ?? "",
            "safety": "Dry-run workers may validate payloads and update uploadJobStatus. They must not mark a platform uploaded, scheduled, or published without a real provider receipt."
        ]
    }

    private func publishConnectorPreflightRow(for record: PublishReceiptRecord) -> [String: Any] {
        let artifactReady = publishRecordArtifactReady(record)
        let copyReady = publishRecordCopyReady(record)
        let receiptCaptured = publishRecordReceiptCaptured(record)
        let authKeys = publishConnectorAuthEnvKeys(platform: record.platform)
        let authConfigured = authKeys.contains { key in
            !(ProcessInfo.processInfo.environment[key] ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        }
        let workerEnvKey = publishConnectorWorkerEnvKey(platform: record.platform)
        let workerPath = (ProcessInfo.processInfo.environment[workerEnvKey] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let workerExecutableReady = !workerPath.isEmpty && FileManager.default.isExecutableFile(atPath: workerPath)
        let bundledWorker = bundledPublishDryRunWorker(for: record.platform)
        let receiptWriteReady = !record.id.uuidString.isEmpty
        var missing: [String] = []
        if !artifactReady { missing.append("artifact") }
        if !copyReady { missing.append("platform-copy") }
        if !authConfigured { missing.append("auth-env") }
        if !workerExecutableReady { missing.append("upload-worker") }
        if !receiptWriteReady { missing.append("receipt-write-path") }

        let status: String
        if receiptCaptured {
            status = "receipt-captured"
        } else if missing.isEmpty {
            status = "ready-for-upload-worker"
        } else if !artifactReady || !copyReady {
            status = "handoff-not-ready"
        } else if !authConfigured {
            status = "auth-missing"
        } else if !workerExecutableReady {
            status = "worker-missing"
        } else {
            status = "blocked"
        }

        return [
            "platform": record.platform,
            "deliveryLaneId": record.deliveryLaneId,
            "destinationId": publishDestinationId(for: record),
            "destinationGuidance": publishDestinationGuidance(for: record),
            "artifactPath": record.artifactPath,
            "artifactReady": artifactReady,
            "copyReady": copyReady,
            "receiptCaptured": receiptCaptured,
            "authConfigured": authConfigured,
            "authEnvKeys": authKeys,
            "workerEnvKey": workerEnvKey,
            "workerPathConfigured": !workerPath.isEmpty,
            "workerExecutableReady": workerExecutableReady,
            "bundledDryRunWorkerFilename": bundledWorker.filename,
            "bundledDryRunWorkerPath": bundledWorker.path,
            "bundledDryRunWorkerExists": bundledWorker.exists,
            "bundledDryRunWorkerExecutableReady": bundledWorker.executable,
            "bundledDryRunCommand": bundledWorker.command(platform: record.platform, laneId: record.deliveryLaneId),
            "receiptWriteReady": receiptWriteReady,
            "requiredIntegration": requiredIntegration(platform: record.platform),
            "uploadJobKind": record.uploadJobKind.isEmpty ? defaultUploadJobKind(platform: record.platform) : record.uploadJobKind,
            "status": status,
            "safeToUploadAutomatically": status == "ready-for-upload-worker",
            "missing": missing,
            "nextAction": publishConnectorPreflightNextAction(status: status, platform: record.platform, missing: missing, workerEnvKey: workerEnvKey)
        ] as [String: Any]
    }

    private func publishConnectorPreflightNextActions(rows: [[String: Any]]) -> [[String: Any]] {
        rows
            .filter { ($0["status"] as? String) != "receipt-captured" && ($0["status"] as? String) != "ready-for-upload-worker" }
            .prefix(8)
            .map { row in
                [
                    "platform": row["platform"] ?? "",
                    "deliveryLaneId": row["deliveryLaneId"] ?? "",
                    "status": row["status"] ?? "",
                    "action": row["nextAction"] ?? ""
                ] as [String: Any]
            }
    }

    private func publishConnectorPreflightNextAction(status: String, platform: String, missing: [String], workerEnvKey: String) -> String {
        switch status {
        case "receipt-captured":
            return "Receipt already captured. No upload worker should run unless intentionally republishing."
        case "ready-for-upload-worker":
            return "All preflight gates are ready. A connector worker may upload and must write back a receipt."
        case "handoff-not-ready":
            return "Run full release prep and make sure platform title/description metadata exists before upload."
        case "auth-missing":
            return "Configure auth for \(platform) using the listed env key names. Do not paste secrets into logs or packets."
        case "worker-missing":
            return "Set \(workerEnvKey) to an executable upload worker path, then rerun preflight."
        default:
            return "Resolve missing preflight gates: \(missing.joined(separator: ", "))."
        }
    }

    private func publishConnectorAuthEnvKeys(platform: String) -> [String] {
        switch platform {
        case "YouTube", "YouTube Shorts":
            return ["QUIPSLY_YOUTUBE_OAUTH_TOKEN", "QUIPSLY_YOUTUBE_REFRESH_TOKEN", "QUIPSLY_GOOGLE_OAUTH_REFRESH_TOKEN"]
        case "Patreon":
            return ["QUIPSLY_PATREON_ACCESS_TOKEN", "QUIPSLY_PATREON_REFRESH_TOKEN"]
        case "Instagram", "Facebook":
            return ["QUIPSLY_META_ACCESS_TOKEN", "QUIPSLY_FACEBOOK_PAGE_TOKEN"]
        case "LinkedIn":
            return ["QUIPSLY_LINKEDIN_ACCESS_TOKEN"]
        case "Spotify", "Apple Podcasts":
            return ["QUIPSLY_PODCAST_HOSTING_TOKEN", "QUIPSLY_PODCAST_HOSTING_REFRESH_TOKEN"]
        default:
            return ["QUIPSLY_PLATFORM_ACCESS_TOKEN"]
        }
    }

    private func publishConnectorWorkerEnvKey(platform: String) -> String {
        switch platform {
        case "YouTube", "YouTube Shorts":
            return "QUIPSLY_YOUTUBE_UPLOAD_WORKER"
        case "Patreon":
            return "QUIPSLY_PATREON_UPLOAD_WORKER"
        case "Instagram", "Facebook":
            return "QUIPSLY_META_UPLOAD_WORKER"
        case "LinkedIn":
            return "QUIPSLY_LINKEDIN_UPLOAD_WORKER"
        case "Spotify", "Apple Podcasts":
            return "QUIPSLY_PODCAST_UPLOAD_WORKER"
        default:
            return "QUIPSLY_PLATFORM_UPLOAD_WORKER"
        }
    }

    private struct BundledPublishDryRunWorker {
        var filename: String
        var path: String
        var exists: Bool
        var executable: Bool

        func command(platform: String, laneId: String) -> String {
            guard executable, !path.isEmpty else { return "" }
            return "script/agentctl.sh publish-connector-worker-dry-run \"\(platform)\" \(laneId) \"\(path)\""
        }
    }

    private func bundledPublishDryRunWorker(for platform: String) -> BundledPublishDryRunWorker {
        let filename: String
        switch platform {
        case "YouTube", "YouTube Shorts":
            filename = "youtube_upload_worker.py"
        case "Patreon":
            filename = "patreon_upload_worker.py"
        case "Instagram", "Facebook", "LinkedIn":
            filename = "social_upload_worker.py"
        case "Spotify", "Apple Podcasts":
            filename = "podcast_upload_worker.py"
        default:
            filename = ""
        }

        guard !filename.isEmpty else {
            return BundledPublishDryRunWorker(filename: "", path: "", exists: false, executable: false)
        }

        let fileManager = FileManager.default
        let roots = [
            ProcessInfo.processInfo.environment["QUIPSLY_STUDIO_ROOT"],
            fileManager.currentDirectoryPath,
            Bundle.main.resourceURL?.path
        ]
        .compactMap { raw -> String? in
            let trimmed = (raw ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
            return trimmed.isEmpty ? nil : trimmed
        }

        for root in roots {
            let candidate = URL(fileURLWithPath: root)
                .appendingPathComponent("script")
                .appendingPathComponent("publish_workers")
                .appendingPathComponent(filename)
                .path
            if fileManager.fileExists(atPath: candidate) {
                return BundledPublishDryRunWorker(
                    filename: filename,
                    path: candidate,
                    exists: true,
                    executable: fileManager.isExecutableFile(atPath: candidate)
                )
            }
        }

        let fallback = URL(fileURLWithPath: fileManager.currentDirectoryPath)
            .appendingPathComponent("script")
            .appendingPathComponent("publish_workers")
            .appendingPathComponent(filename)
            .path
        return BundledPublishDryRunWorker(filename: filename, path: fallback, exists: false, executable: false)
    }

    private func publishConnectorWorkerPayload(record: PublishReceiptRecord, mode: String) -> [String: Any] {
        var metadata: [String: Any] = [:]
        let trimmedMetadata = record.metadataJson.trimmingCharacters(in: .whitespacesAndNewlines)
        if !trimmedMetadata.isEmpty,
           let data = trimmedMetadata.data(using: .utf8),
           let parsed = try? JSONSerialization.jsonObject(with: data) as? [String: Any] {
            metadata = parsed
        }
        var uploadJob: [String: Any] = [:]
        let trimmedJob = record.uploadJobJson.trimmingCharacters(in: .whitespacesAndNewlines)
        if !trimmedJob.isEmpty,
           let data = trimmedJob.data(using: .utf8),
           let parsed = try? JSONSerialization.jsonObject(with: data) as? [String: Any] {
            uploadJob = parsed
        }

        return [
            "model": "quipsly-publish-worker-payload",
            "version": "2026-06-16.publish-worker.v2",
            "mode": mode,
            "platform": record.platform,
            "deliveryLaneId": record.deliveryLaneId,
            "receiptId": record.id.uuidString,
            "destination": publishDestinationGuidance(for: record),
            "artifact": [
                "path": record.artifactPath,
                "type": record.artifactType,
                "format": record.format,
                "status": record.artifactStatus,
                "exists": publishRecordArtifactExists(record)
            ],
            "copy": [
                "title": record.title,
                "description": record.description,
                "metadataStatus": record.metadataStatus,
                "metadata": metadata
            ],
            "uploadJob": uploadJob,
            "requiredIntegration": requiredIntegration(platform: record.platform),
            "receiptContract": [
                "writeProviderReceiptIdTo": "publishReceipts.providerReceiptId",
                "writePublicURLTo": "publishReceipts.publicURL",
                "writeReceiptJSONTo": "publishReceipts.receiptJson",
                "dryRunMustNotMarkPublished": true
            ],
            "secretPolicy": "Worker receives no secret values from Quipsly payload. It must read auth from its own environment."
        ] as [String: Any]
    }

    private func runPublishConnectorWorkerDryRunFromAgent(values: [String: String]) {
        guard var sequence = projectStore.activeSequence else {
            publishConnectorWorkerStatus = "blocked"
            publishConnectorWorkerErrorMessage = "No active sequence loaded."
            publishConnectorWorkerUpdatedAt = Date()
            lastMediaAction = "Publish worker dry-run blocked: no active sequence"
            updateAgentState()
            return
        }
        let platform = (values["platform"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let laneId = (values["lane_id"] ?? values["delivery_lane_id"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let workerPath = (values["worker_path"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        guard !platform.isEmpty else {
            publishConnectorWorkerStatus = "blocked"
            publishConnectorWorkerErrorMessage = "Choose a platform before running a publish worker."
            publishConnectorWorkerUpdatedAt = Date()
            updateAgentState()
            return
        }
        guard !workerPath.isEmpty, FileManager.default.isExecutableFile(atPath: workerPath) else {
            publishConnectorWorkerStatus = "blocked"
            publishConnectorWorkerPlatform = platform
            publishConnectorWorkerLaneId = laneId
            publishConnectorWorkerPath = workerPath
            publishConnectorWorkerErrorMessage = "Worker path is missing or not executable."
            publishConnectorWorkerUpdatedAt = Date()
            lastMediaAction = "Publish worker dry-run blocked: missing executable worker"
            updateAgentState()
            return
        }
        guard let recordIndex = sequence.publishReceipts.firstIndex(where: { record in
            record.platform == platform && publishLaneMatches(record.deliveryLaneId, targetLaneId: laneId)
        }) else {
            publishConnectorWorkerStatus = "blocked"
            publishConnectorWorkerPlatform = platform
            publishConnectorWorkerLaneId = laneId
            publishConnectorWorkerPath = workerPath
            publishConnectorWorkerErrorMessage = "No publish record matched platform \(platform) and lane \(laneId)."
            publishConnectorWorkerUpdatedAt = Date()
            lastMediaAction = "Publish worker dry-run blocked: record not found"
            updateAgentState()
            return
        }

        let record = sequence.publishReceipts[recordIndex]
        let payload = publishConnectorWorkerPayload(record: record, mode: "dry-run")
        let payloadDirectory = FileManager.default.temporaryDirectory
            .appendingPathComponent("quipsly-publish-worker", isDirectory: true)
        let payloadURL = payloadDirectory
            .appendingPathComponent("\(sanitizedExportBasename(record.platform))-\(sanitizedExportBasename(record.deliveryLaneId))-payload.json")

        do {
            try FileManager.default.createDirectory(at: payloadDirectory, withIntermediateDirectories: true)
            try writeJSONObject(payload, to: payloadURL)
        } catch {
            publishConnectorWorkerStatus = "failed"
            publishConnectorWorkerPlatform = platform
            publishConnectorWorkerLaneId = record.deliveryLaneId
            publishConnectorWorkerPath = workerPath
            publishConnectorWorkerPayloadPath = payloadURL.path
            publishConnectorWorkerErrorMessage = "Could not write worker payload: \(error.localizedDescription)"
            publishConnectorWorkerUpdatedAt = Date()
            lastMediaAction = "Publish worker payload failed: \(error.localizedDescription)"
            updateAgentState()
            return
        }

        publishConnectorWorkerStatus = "running"
        publishConnectorWorkerPlatform = platform
        publishConnectorWorkerLaneId = record.deliveryLaneId
        publishConnectorWorkerPath = workerPath
        publishConnectorWorkerPayloadPath = payloadURL.path
        publishConnectorWorkerResultJson = ""
        publishConnectorWorkerErrorMessage = ""
        publishConnectorWorkerUpdatedAt = Date()
        lastMediaAction = "Publish worker dry-run started for \(platform)"
        updateAgentState()

        Task {
            let result = runPublishWorkerProcess(workerPath: workerPath, payloadPath: payloadURL.path)
            await MainActor.run {
                switch result {
                case .success(let output):
                    let trimmedOutput = output.trimmingCharacters(in: .whitespacesAndNewlines)
                    let parsed = parseJSONObject(trimmedOutput)
                    let status = parsed?["status"] as? String ?? "unknown"
                    publishConnectorWorkerResultJson = trimmedOutput
                    publishConnectorWorkerUpdatedAt = Date()
                    if status == "dry-run-passed" {
                        sequence.publishReceipts[recordIndex].uploadJobStatus = "dry-run-passed"
                        sequence.publishReceipts[recordIndex].uploadJobJson = trimmedOutput
                        sequence.publishReceipts[recordIndex].lastUploadAttemptAt = Date()
                        sequence.publishReceipts[recordIndex].notes = "Dry-run worker validated artifact, metadata, and receipt contract. No platform upload was performed."
                        sequence.publishReceipts[recordIndex].updatedAt = Date()
                        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Publish Worker Dry Run")
                        scheduleAutosave(reason: "publish worker dry-run")
                        publishConnectorWorkerStatus = "dry-run-passed"
                        publishConnectorWorkerErrorMessage = ""
                        lastMediaAction = "Publish worker dry-run passed for \(platform)"
                    } else {
                        publishConnectorWorkerStatus = "failed"
                        publishConnectorWorkerErrorMessage = parsed?["error"] as? String ?? "Worker did not return dry-run-passed."
                        lastMediaAction = "Publish worker dry-run failed for \(platform): \(publishConnectorWorkerErrorMessage)"
                    }
                case .failure(let error):
                    publishConnectorWorkerStatus = "failed"
                    publishConnectorWorkerResultJson = ""
                    publishConnectorWorkerErrorMessage = error.localizedDescription
                    publishConnectorWorkerUpdatedAt = Date()
                    lastMediaAction = "Publish worker dry-run failed: \(error.localizedDescription)"
                }
                updateAgentState()
            }
        }
    }

    private func runAllBundledPublishConnectorWorkersDryRunFromAgent(values: [String: String]) {
        guard let sequence = projectStore.activeSequence else {
            publishConnectorWorkerStatus = "blocked"
            publishConnectorWorkerPlatform = "all"
            publishConnectorWorkerLaneId = values["lane_id"] ?? values["delivery_lane_id"] ?? ""
            publishConnectorWorkerPath = "bundled"
            publishConnectorWorkerPayloadPath = ""
            publishConnectorWorkerResultJson = ""
            publishConnectorWorkerErrorMessage = "No active sequence loaded."
            publishConnectorWorkerUpdatedAt = Date()
            lastMediaAction = "All publish worker dry-run blocked: no active sequence"
            updateAgentState()
            return
        }

        let targetPlatform = (values["platform"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let targetLaneId = (values["lane_id"] ?? values["delivery_lane_id"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let payloadDirectory = FileManager.default.temporaryDirectory
            .appendingPathComponent("quipsly-publish-worker", isDirectory: true)
            .appendingPathComponent("all-bundled-dry-run", isDirectory: true)

        var jobs: [(index: Int, record: PublishReceiptRecord, worker: BundledPublishDryRunWorker, payloadPath: String)] = []
        var setupErrors: [[String: Any]] = []

        do {
            try FileManager.default.createDirectory(at: payloadDirectory, withIntermediateDirectories: true)
        } catch {
            publishConnectorWorkerStatus = "failed"
            publishConnectorWorkerPlatform = targetPlatform.isEmpty ? "all" : targetPlatform
            publishConnectorWorkerLaneId = targetLaneId
            publishConnectorWorkerPath = "bundled"
            publishConnectorWorkerPayloadPath = payloadDirectory.path
            publishConnectorWorkerResultJson = ""
            publishConnectorWorkerErrorMessage = "Could not prepare worker payload folder: \(error.localizedDescription)"
            publishConnectorWorkerUpdatedAt = Date()
            lastMediaAction = "All publish worker dry-run failed: payload folder"
            updateAgentState()
            return
        }

        for (index, record) in sequence.publishReceipts.enumerated() {
            if !targetPlatform.isEmpty && record.platform != targetPlatform { continue }
            if !publishLaneMatches(record.deliveryLaneId, targetLaneId: targetLaneId) { continue }

            let worker = bundledPublishDryRunWorker(for: record.platform)
            guard worker.executable else {
                setupErrors.append([
                    "platform": record.platform,
                    "deliveryLaneId": record.deliveryLaneId,
                    "status": "blocked",
                    "error": "Bundled dry-run worker is missing or not executable.",
                    "workerPath": worker.path
                ])
                continue
            }

            let payload = publishConnectorWorkerPayload(record: record, mode: "dry-run")
            let payloadURL = payloadDirectory
                .appendingPathComponent("\(sanitizedExportBasename(record.platform))-\(sanitizedExportBasename(record.deliveryLaneId))-payload.json")
            do {
                try writeJSONObject(payload, to: payloadURL)
                jobs.append((index: index, record: record, worker: worker, payloadPath: payloadURL.path))
            } catch {
                setupErrors.append([
                    "platform": record.platform,
                    "deliveryLaneId": record.deliveryLaneId,
                    "status": "failed",
                    "error": "Could not write worker payload: \(error.localizedDescription)",
                    "workerPath": worker.path
                ])
            }
        }

        guard !jobs.isEmpty || !setupErrors.isEmpty else {
            publishConnectorWorkerStatus = "blocked"
            publishConnectorWorkerPlatform = targetPlatform.isEmpty ? "all" : targetPlatform
            publishConnectorWorkerLaneId = targetLaneId
            publishConnectorWorkerPath = "bundled"
            publishConnectorWorkerPayloadPath = payloadDirectory.path
            publishConnectorWorkerResultJson = ""
            publishConnectorWorkerErrorMessage = "No publish records matched the requested platform/lane filters."
            publishConnectorWorkerUpdatedAt = Date()
            lastMediaAction = "All publish worker dry-run blocked: no matching records"
            updateAgentState()
            return
        }

        publishConnectorWorkerStatus = "running-all"
        publishConnectorWorkerPlatform = targetPlatform.isEmpty ? "all" : targetPlatform
        publishConnectorWorkerLaneId = targetLaneId
        publishConnectorWorkerPath = "bundled"
        publishConnectorWorkerPayloadPath = payloadDirectory.path
        publishConnectorWorkerResultJson = ""
        publishConnectorWorkerErrorMessage = ""
        publishConnectorWorkerUpdatedAt = Date()
        lastMediaAction = "All bundled publish worker dry-run started"
        updateAgentState()

        Task {
            var workerResults: [[String: Any]] = setupErrors
            for job in jobs {
                let result = runPublishWorkerProcess(workerPath: job.worker.path, payloadPath: job.payloadPath)
                switch result {
                case .success(let output):
                    let trimmedOutput = output.trimmingCharacters(in: .whitespacesAndNewlines)
                    let parsed = parseJSONObject(trimmedOutput)
                    workerResults.append([
                        "platform": job.record.platform,
                        "deliveryLaneId": job.record.deliveryLaneId,
                        "status": parsed?["status"] as? String ?? "unknown",
                        "workerFilename": job.worker.filename,
                        "workerPath": job.worker.path,
                        "payloadPath": job.payloadPath,
                        "resultJson": trimmedOutput
                    ])
                case .failure(let error):
                    workerResults.append([
                        "platform": job.record.platform,
                        "deliveryLaneId": job.record.deliveryLaneId,
                        "status": "failed",
                        "workerFilename": job.worker.filename,
                        "workerPath": job.worker.path,
                        "payloadPath": job.payloadPath,
                        "error": error.localizedDescription
                    ])
                }
            }

            await MainActor.run {
                var nextSequence = sequence
                var passedCount = 0
                var failedCount = 0
                for result in workerResults {
                    let status = result["status"] as? String ?? ""
                    if status == "dry-run-passed" {
                        passedCount += 1
                    } else {
                        failedCount += 1
                    }
                    guard status == "dry-run-passed",
                          let platform = result["platform"] as? String,
                          let deliveryLaneId = result["deliveryLaneId"] as? String,
                          let recordIndex = nextSequence.publishReceipts.firstIndex(where: {
                              $0.platform == platform && $0.deliveryLaneId == deliveryLaneId
                          }) else {
                        continue
                    }
                    nextSequence.publishReceipts[recordIndex].uploadJobStatus = "dry-run-passed"
                    nextSequence.publishReceipts[recordIndex].uploadJobJson = result["resultJson"] as? String ?? "{}"
                    nextSequence.publishReceipts[recordIndex].lastUploadAttemptAt = Date()
                    nextSequence.publishReceipts[recordIndex].notes = "Bundled dry-run worker validated artifact, metadata, and receipt contract. No platform upload was performed."
                    nextSequence.publishReceipts[recordIndex].updatedAt = Date()
                }

                if passedCount > 0 {
                    projectStore.updateSequence(nextSequence, undoManager: nil, actionName: "All Publish Worker Dry Run")
                    scheduleAutosave(reason: "all publish worker dry-run")
                }

                let summary: [String: Any] = [
                    "model": "quipsly-all-bundled-publish-workers-dry-run",
                    "version": "2026-06-16.all-bundled-workers.v1",
                    "status": failedCount == 0 ? "dry-run-all-passed" : (passedCount > 0 ? "dry-run-all-partial" : "dry-run-all-failed"),
                    "passedCount": passedCount,
                    "failedCount": failedCount,
                    "recordCount": workerResults.count,
                    "platformFilter": targetPlatform,
                    "deliveryLaneFilter": targetLaneId,
                    "payloadDirectory": payloadDirectory.path,
                    "safety": "Bundled dry-runs update uploadJobStatus/uploadJobJson only. They do not upload, schedule, publish, create provider receipts, or create public URLs.",
                    "results": workerResults
                ]

                publishConnectorWorkerStatus = summary["status"] as? String ?? "dry-run-all-failed"
                publishConnectorWorkerResultJson = stableJSONString(summary)
                publishConnectorWorkerErrorMessage = failedCount == 0 ? "" : "\(failedCount) bundled dry-run worker(s) failed or were blocked."
                publishConnectorWorkerUpdatedAt = Date()
                lastMediaAction = failedCount == 0
                    ? "All bundled publish worker dry-runs passed"
                    : "Bundled publish worker dry-run finished with \(failedCount) issue(s)"
                updateAgentState()
            }
        }
    }

    private func runPublishWorkerProcess(workerPath: String, payloadPath: String) -> Result<String, Error> {
        do {
            let process = Process()
            process.executableURL = URL(fileURLWithPath: workerPath)
            process.arguments = [payloadPath]
            let stdout = Pipe()
            let stderr = Pipe()
            process.standardOutput = stdout
            process.standardError = stderr
            try process.run()
            process.waitUntilExit()
            let output = String(data: stdout.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
            let errorOutput = String(data: stderr.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
            guard process.terminationStatus == 0 else {
                throw NSError(
                    domain: "QuipslyPublishWorker",
                    code: Int(process.terminationStatus),
                    userInfo: [NSLocalizedDescriptionKey: errorOutput.isEmpty ? "Worker exited with status \(process.terminationStatus)." : errorOutput]
                )
            }
            return .success(output)
        } catch {
            return .failure(error)
        }
    }

    private func parseJSONObject(_ text: String) -> [String: Any]? {
        guard let data = text.data(using: .utf8),
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return nil
        }
        return object
    }

    private func publishLaneMatches(_ recordLaneId: String, targetLaneId: String) -> Bool {
        let target = targetLaneId.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !target.isEmpty else { return true }
        let record = recordLaneId.trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedRecord = record.lowercased()
        let normalizedTarget = target.lowercased()
        return normalizedRecord == normalizedTarget || normalizedRecord.hasPrefix("\(normalizedTarget)/")
    }

    private func generatePublishLedgerFromCurrentDelivery() {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Publish ledger blocked: no active sequence"
            updateAgentState()
            return
        }

        let lanes = deliveryLaneReadiness(summary: mediaReadinessSummary())
        let artifacts = deliveryPacketArtifacts(lanes: lanes)
        let destinations = deliveryPacketDestinations(artifacts: artifacts, lanes: lanes)
        let publishablePlatforms = Set([
            "YouTube",
            "Patreon",
            "YouTube Shorts",
            "Instagram",
            "Facebook",
            "LinkedIn",
            "Spotify",
            "Apple Podcasts"
        ])
        let terminalStatuses = Set(["uploaded", "scheduled", "published"])
        var existingByKey: [String: PublishReceiptRecord] = [:]
        for receipt in sequence.publishReceipts {
            let key = publishReceiptKey(receipt.platform, receipt.deliveryLaneId, receipt.artifactPath)
            if let existing = existingByKey[key] {
                if existing.updatedAt < receipt.updatedAt {
                    existingByKey[key] = receipt
                }
            } else {
                existingByKey[key] = receipt
            }
        }
        var nextRecords: [PublishReceiptRecord] = []
        let hasQueuedShorts = !sequence.shortClipQueue.isEmpty

        for destination in destinations {
            guard let platform = destination["platform"] as? String,
                  publishablePlatforms.contains(platform),
                  let deliveryLaneId = destination["laneId"] as? String else {
                continue
            }
            if deliveryLaneId == "social-short-clips", hasQueuedShorts {
                continue
            }

            let artifactPath = destination["outputPath"] as? String ?? ""
            let artifactStatus = destination["artifactStatus"] as? String ?? "unknown"
            let artifactType = destination["artifactType"] as? String ?? ""
            let format = destination["format"] as? String ?? ""
            let nextAction = destination["nextAction"] as? String ?? ""
            let key = publishReceiptKey(platform, deliveryLaneId, artifactPath)
            let now = Date()
            let generatedStatus: String
            if artifactStatus == "exported" && !artifactPath.isEmpty {
                generatedStatus = "ready-to-upload"
            } else if artifactStatus == "export-needed" {
                generatedStatus = "needs-export"
            } else {
                generatedStatus = "blocked"
            }

            var record = existingByKey[key] ?? PublishReceiptRecord(
                platform: platform,
                deliveryLaneId: deliveryLaneId,
                artifactType: artifactType,
                format: format,
                artifactPath: artifactPath,
                artifactStatus: artifactStatus,
                publishStatus: generatedStatus,
                title: defaultPublishTitle(platform: platform, sequence: sequence),
                description: defaultPublishDescription(platform: platform, sequence: sequence),
                metadataJson: defaultPublishMetadataJSON(
                    platform: platform,
                    deliveryLaneId: deliveryLaneId,
                    artifactPath: artifactPath,
                    artifactType: artifactType,
                    format: format,
                    sequence: sequence
                ),
                metadataStatus: "draft",
                uploadJobKind: defaultUploadJobKind(platform: platform),
                uploadJobStatus: generatedStatus == "ready-to-upload" ? "integration-needed" : generatedStatus,
                uploadJobJson: defaultUploadJobJSON(
                    platform: platform,
                    deliveryLaneId: deliveryLaneId,
                    artifactPath: artifactPath,
                    artifactType: artifactType,
                    format: format,
                    sequence: sequence
                ),
                notes: nextAction,
                createdAt: now,
                updatedAt: now
            )
            if !terminalStatuses.contains(record.publishStatus) {
                record.artifactType = artifactType
                record.format = format
                record.artifactPath = artifactPath
                record.artifactStatus = artifactStatus
                record.publishStatus = generatedStatus
                if record.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    record.title = defaultPublishTitle(platform: platform, sequence: sequence)
                }
                if record.description.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    record.description = defaultPublishDescription(platform: platform, sequence: sequence)
                }
                if record.metadataJson.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    record.metadataJson = defaultPublishMetadataJSON(
                        platform: platform,
                        deliveryLaneId: deliveryLaneId,
                        artifactPath: artifactPath,
                        artifactType: artifactType,
                        format: format,
                        sequence: sequence
                    )
                    record.metadataStatus = "draft"
                }
                if record.uploadJobKind.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    record.uploadJobKind = defaultUploadJobKind(platform: platform)
                }
                record.uploadJobStatus = generatedStatus == "ready-to-upload" ? "integration-needed" : generatedStatus
                record.uploadJobJson = defaultUploadJobJSON(
                    platform: platform,
                    deliveryLaneId: deliveryLaneId,
                    artifactPath: artifactPath,
                    artifactType: artifactType,
                    format: format,
                    sequence: sequence
                )
                record.notes = nextAction
                record.updatedAt = now
            } else {
                var hydratedLegacyReceipt = false
                if record.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    record.title = defaultPublishTitle(platform: platform, sequence: sequence)
                    hydratedLegacyReceipt = true
                }
                if record.description.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    record.description = defaultPublishDescription(platform: platform, sequence: sequence)
                    hydratedLegacyReceipt = true
                }
                if record.metadataJson.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    record.metadataJson = defaultPublishMetadataJSON(
                        platform: platform,
                        deliveryLaneId: deliveryLaneId,
                        artifactPath: artifactPath,
                        artifactType: artifactType,
                        format: format,
                        sequence: sequence
                    )
                    record.metadataStatus = "draft"
                    hydratedLegacyReceipt = true
                }
                if record.metadataStatus.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    record.metadataStatus = "draft"
                    hydratedLegacyReceipt = true
                }
                if record.uploadJobKind.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    record.uploadJobKind = defaultUploadJobKind(platform: platform)
                    hydratedLegacyReceipt = true
                }
                if record.uploadJobStatus.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    record.uploadJobStatus = "receipt-recorded"
                    hydratedLegacyReceipt = true
                }
                if record.uploadJobJson.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    record.uploadJobJson = defaultUploadJobJSON(
                        platform: platform,
                        deliveryLaneId: deliveryLaneId,
                        artifactPath: artifactPath,
                        artifactType: artifactType,
                        format: format,
                        sequence: sequence
                    )
                    hydratedLegacyReceipt = true
                }
                if hydratedLegacyReceipt {
                    record.updatedAt = now
                }
            }
            nextRecords.append(record)
            existingByKey.removeValue(forKey: key)
        }

        appendQueuedShortPublishRecords(
            sequence: sequence,
            existingByKey: &existingByKey,
            terminalStatuses: terminalStatuses,
            nextRecords: &nextRecords
        )

        let manuallyTracked = existingByKey.values
            .filter { receipt in
                if hasQueuedShorts,
                   receipt.deliveryLaneId == "social-short-clips",
                   !terminalStatuses.contains(receipt.publishStatus) {
                    return false
                }
                return !["needs-export", "blocked"].contains(receipt.publishStatus)
            }
            .sorted { $0.createdAt < $1.createdAt }
        sequence.publishReceipts = (nextRecords + manuallyTracked).sorted {
            if $0.deliveryLaneId == $1.deliveryLaneId {
                return $0.platform < $1.platform
            }
            return $0.deliveryLaneId < $1.deliveryLaneId
        }
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Generate Publish Ledger")
        scheduleAutosave(reason: "generated publish ledger")
        lastMediaAction = "Generated publish ledger: \(sequence.publishReceipts.count) platform record(s)"
        updateAgentState()
    }

    private func appendQueuedShortPublishRecords(
        sequence: MediaSequence,
        existingByKey: inout [String: PublishReceiptRecord],
        terminalStatuses: Set<String>,
        nextRecords: inout [PublishReceiptRecord]
    ) {
        let publishablePlatforms = Set(["YouTube Shorts", "Instagram", "Facebook", "LinkedIn"])
        let now = Date()

        for clip in sequence.shortClipQueue {
            let laneId = "social-short-clips/\(clip.id.uuidString)"
            let artifactPath = lastExportedShortPath(for: clip) ?? ""
            let artifactReady = !artifactPath.isEmpty && FileManager.default.fileExists(atPath: artifactPath)
            let artifactStatus = artifactReady ? "exported" : "export-needed"
            let generatedStatus = artifactReady ? "ready-to-upload" : "needs-export"
            let presets = clip.destinationPresets.isEmpty
                ? clip.destinations.map { ShortDestinationPreset(platform: $0, title: clip.title) }
                : clip.destinationPresets

            for preset in presets where publishablePlatforms.contains(preset.platform) {
                let platform = preset.platform
                let title = socialShortPublishTitle(clip: clip, preset: preset)
                let description = socialShortPublishDescription(clip: clip, preset: preset, sequence: sequence)
                let key = publishReceiptKey(platform, laneId, artifactPath)
                var record = existingByKey[key] ?? PublishReceiptRecord(
                    platform: platform,
                    deliveryLaneId: laneId,
                    artifactType: "Short MP4 clip",
                    format: "9:16",
                    artifactPath: artifactPath,
                    artifactStatus: artifactStatus,
                    publishStatus: generatedStatus,
                    title: title,
                    description: description,
                    metadataJson: socialShortPublishMetadataJSON(
                        sequence: sequence,
                        clip: clip,
                        preset: preset,
                        platform: platform,
                        deliveryLaneId: laneId,
                        artifactPath: artifactPath,
                        artifactStatus: artifactStatus
                    ),
                    metadataStatus: "draft",
                    uploadJobKind: defaultUploadJobKind(platform: platform),
                    uploadJobStatus: generatedStatus == "ready-to-upload" ? "integration-needed" : generatedStatus,
                    uploadJobJson: socialShortUploadJobJSON(
                        sequence: sequence,
                        clip: clip,
                        preset: preset,
                        platform: platform,
                        deliveryLaneId: laneId,
                        artifactPath: artifactPath,
                        artifactStatus: artifactStatus
                    ),
                    notes: socialShortPublishNotes(clip: clip, sequence: sequence),
                    createdAt: now,
                    updatedAt: now
                )

                if !terminalStatuses.contains(record.publishStatus) {
                    record.artifactType = "Short MP4 clip"
                    record.format = "9:16"
                    record.artifactPath = artifactPath
                    record.artifactStatus = artifactStatus
                    record.publishStatus = generatedStatus
                    record.title = title
                    record.description = description
                    record.metadataJson = socialShortPublishMetadataJSON(
                        sequence: sequence,
                        clip: clip,
                        preset: preset,
                        platform: platform,
                        deliveryLaneId: laneId,
                        artifactPath: artifactPath,
                        artifactStatus: artifactStatus
                    )
                    record.metadataStatus = "draft"
                    record.uploadJobKind = defaultUploadJobKind(platform: platform)
                    record.uploadJobStatus = generatedStatus == "ready-to-upload" ? "integration-needed" : generatedStatus
                    record.uploadJobJson = socialShortUploadJobJSON(
                        sequence: sequence,
                        clip: clip,
                        preset: preset,
                        platform: platform,
                        deliveryLaneId: laneId,
                        artifactPath: artifactPath,
                        artifactStatus: artifactStatus
                    )
                    record.notes = socialShortPublishNotes(clip: clip, sequence: sequence)
                    record.updatedAt = now
                }

                nextRecords.append(record)
                existingByKey.removeValue(forKey: key)
            }
        }
    }

    private func publishReceiptKey(_ platform: String, _ deliveryLaneId: String, _ _: String) -> String {
        // A publish task is "send this delivery lane to this platform." The
        // artifact path can change every time release prep writes a new folder,
        // so it must not create duplicate ledger identities.
        "\(platform.lowercased())|\(deliveryLaneId.lowercased())"
    }

    private func defaultPublishTitle(platform: String, sequence: MediaSequence) -> String {
        let base = sequence.title.replacingOccurrences(of: " Premiere Rescue", with: "")
        switch platform {
        case "YouTube Shorts", "Instagram", "Facebook", "LinkedIn":
            return "\(base) - short"
        case "Spotify", "Apple Podcasts":
            return "\(base) podcast audio"
        default:
            return base
        }
    }

    private func defaultPublishDescription(platform: String, sequence: MediaSequence) -> String {
        switch platform {
        case "Patreon":
            return "Patreon release draft for \(sequence.title)."
        case "Spotify", "Apple Podcasts":
            return "Podcast audio release draft for \(sequence.title)."
        case "YouTube Shorts", "Instagram", "Facebook", "LinkedIn":
            return "Short-form video release draft from \(sequence.title)."
        default:
            return "Episode release draft for \(sequence.title)."
        }
    }

    private func socialShortPublishTitle(clip: ShortClipCandidate, preset: ShortDestinationPreset) -> String {
        let presetTitle = preset.title.trimmingCharacters(in: .whitespacesAndNewlines)
        if !presetTitle.isEmpty {
            return presetTitle
        }
        let clipTitle = clip.title.trimmingCharacters(in: .whitespacesAndNewlines)
        return clipTitle.isEmpty ? "Untitled short" : clipTitle
    }

    private func socialShortPublishDescription(
        clip: ShortClipCandidate,
        preset: ShortDestinationPreset,
        sequence: MediaSequence
    ) -> String {
        let presetCaption = preset.caption.trimmingCharacters(in: .whitespacesAndNewlines)
        if !presetCaption.isEmpty {
            return presetCaption
        }
        let caption = clip.captionDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        if !caption.isEmpty {
            return caption
        }
        let hook = clip.hookText.trimmingCharacters(in: .whitespacesAndNewlines)
        if !hook.isEmpty {
            return hook
        }
        return "Short-form video release draft from \(sequence.title)."
    }

    private func socialShortPublishNotes(clip: ShortClipCandidate, sequence: MediaSequence) -> String {
        let sequenceStart = sequenceStartTime(for: clip, in: sequence)
        let sequenceEnd = sequenceStart + clip.duration
        var lines = [
            String(format: "Sequence range %.2fs -> %.2fs", sequenceStart, sequenceEnd),
            "Short id: \(clip.id.uuidString)"
        ]
        let notes = clip.notes.trimmingCharacters(in: .whitespacesAndNewlines)
        if !notes.isEmpty {
            lines.append(notes)
        }
        let publishNotes = clip.publishNotes.trimmingCharacters(in: .whitespacesAndNewlines)
        if !publishNotes.isEmpty {
            lines.append(publishNotes)
        }
        return lines.joined(separator: "\n")
    }

    private func socialShortPublishMetadataJSON(
        sequence: MediaSequence,
        clip: ShortClipCandidate,
        preset: ShortDestinationPreset,
        platform: String,
        deliveryLaneId: String,
        artifactPath: String,
        artifactStatus: String
    ) -> String {
        let sequenceStart = sequenceStartTime(for: clip, in: sequence)
        return stableJSONString([
            "platform": platform,
            "deliveryLaneId": deliveryLaneId,
            "artifactPath": artifactPath,
            "artifactStatus": artifactStatus,
            "artifactType": "Short MP4 clip",
            "format": "9:16",
            "title": socialShortPublishTitle(clip: clip, preset: preset),
            "description": socialShortPublishDescription(clip: clip, preset: preset, sequence: sequence),
            "hashtags": preset.hashtags,
            "sequenceTitle": sequence.title,
            "shortClipId": clip.id.uuidString,
            "timeBase": "sequence-seconds",
            "sequenceStartTime": sequenceStart,
            "sequenceEndTime": sequenceStart + clip.duration,
            "duration": clip.duration,
            "hookText": clip.hookText,
            "captionDraft": clip.captionDraft,
            "primaryOverlayText": clip.primaryOverlayText,
            "visibility": defaultVisibility(platform: platform),
            "audience": defaultAudience(platform: platform),
            "category": defaultPublishCategory(platform: platform),
            "destinationGuidance": publishDestinationGuidance(
                platform: platform,
                deliveryLaneId: "social-short-clips",
                format: "9:16"
            ),
            "humanReviewRequired": true,
            "sourcePolicy": "proxy-rendered short over whole synced source lanes"
        ])
    }

    private func socialShortUploadJobJSON(
        sequence: MediaSequence,
        clip: ShortClipCandidate,
        preset: ShortDestinationPreset,
        platform: String,
        deliveryLaneId: String,
        artifactPath: String,
        artifactStatus: String
    ) -> String {
        stableJSONString([
            "kind": defaultUploadJobKind(platform: platform),
            "platform": platform,
            "deliveryLaneId": deliveryLaneId,
            "artifactPath": artifactPath,
            "artifactStatus": artifactStatus,
            "format": "9:16",
            "shortClipId": clip.id.uuidString,
            "title": socialShortPublishTitle(clip: clip, preset: preset),
            "description": socialShortPublishDescription(clip: clip, preset: preset, sequence: sequence),
            "hashtags": preset.hashtags,
            "status": artifactStatus == "exported" ? "integration-needed" : "needs-export",
            "directUploadReady": false,
            "manualUploadReady": artifactStatus == "exported",
            "dryRunOnly": true,
            "sourcePolicy": "upload job references exported derivative artifact only"
        ])
    }

    private func defaultPublishMetadataJSON(
        platform: String,
        deliveryLaneId: String,
        artifactPath: String,
        artifactType: String,
        format: String,
        sequence: MediaSequence
    ) -> String {
        let baseTitle = defaultPublishTitle(platform: platform, sequence: sequence)
        let baseDescription = defaultPublishDescription(platform: platform, sequence: sequence)
        let destinationId = publishDestinationId(
            platform: platform,
            deliveryLaneId: deliveryLaneId,
            format: format
        )
        let destinationGuidance = publishDestinationGuidance(
            platform: platform,
            deliveryLaneId: deliveryLaneId,
            format: format
        )
        var metadata: [String: Any] = [
            "platform": platform,
            "deliveryLaneId": deliveryLaneId,
            "destinationId": destinationId,
            "destinationGuidance": destinationGuidance,
            "title": baseTitle,
            "description": baseDescription,
            "format": format,
            "artifactType": artifactType,
            "artifactPath": artifactPath,
            "visibility": defaultVisibility(platform: platform),
            "audience": defaultAudience(platform: platform),
            "tags": defaultPublishTags(platform: platform, sequence: sequence),
            "category": defaultPublishCategory(platform: platform),
            "sourcePolicy": "proxy-rendered artifact over whole synced source lanes",
            "humanReviewRequired": true
        ]
        defaultDestinationRequiredFieldValues(
            platform: platform,
            deliveryLaneId: deliveryLaneId,
            artifactPath: artifactPath,
            artifactType: artifactType,
            format: format,
            sequence: sequence,
            baseTitle: baseTitle,
            baseDescription: baseDescription,
            destinationGuidance: destinationGuidance
        ).forEach { key, value in
            if metadata[key] == nil {
                metadata[key] = value
            }
        }
        return stableJSONString(metadata)
    }

    private func defaultDestinationRequiredFieldValues(
        platform: String,
        deliveryLaneId: String,
        artifactPath: String,
        artifactType: String,
        format: String,
        sequence: MediaSequence,
        baseTitle: String,
        baseDescription: String,
        destinationGuidance: [String: Any]
    ) -> [String: Any] {
        let requiredFields = destinationGuidance["requires"] as? [String] ?? []
        var values: [String: Any] = [
            "scheduleIntent": "manual-review-required",
            "publishOrScheduleIntent": "manual-review-required",
            "thumbnailIntent": "manual-review-required"
        ]

        for field in requiredFields {
            switch field {
            case "title":
                values[field] = baseTitle
            case "description":
                values[field] = baseDescription
            case "thumbnail":
                values[field] = "manual-review-required"
                values["thumbnailIntent"] = "manual-review-required"
            case "visibility":
                values[field] = defaultVisibility(platform: platform)
            case "scheduleIntent":
                values[field] = "manual-review-required"
            case "memberCopy":
                values[field] = baseDescription
            case "attachmentOrEmbedIntent":
                values[field] = artifactPath.isEmpty ? "export-artifact-then-choose-upload-or-embed" : "manual-review-upload-or-embed"
            case "visibilityTierIntent":
                values[field] = "manual-tier-review-required"
            case "shortTitle":
                values[field] = baseTitle
            case "verticalVideo", "video", "audioMaster":
                values[field] = artifactPath
            case "captionIntent":
                values[field] = "use-description-or-transcript"
            case "caption":
                values[field] = baseDescription
            case "hashtags":
                values[field] = defaultPublishTags(platform: platform, sequence: sequence)
            case "professionalContextCopy":
                values[field] = baseDescription
            case "episodeTitle":
                values[field] = baseTitle
            case "showNotes":
                values[field] = baseDescription
            case "publishOrScheduleIntent":
                values[field] = "manual-review-required"
            default:
                values[field] = "manual-review-required"
            }
        }

        values["destinationRequiredFieldPolicy"] = "Required destination fields are represented in metadata. Values marked manual-review-required must be resolved before real API publishing."
        values["artifactType"] = artifactType
        values["format"] = format
        values["sequenceTitle"] = sequence.title
        values["deliveryLaneId"] = deliveryLaneId
        return values
    }

    private func defaultUploadJobKind(platform: String) -> String {
        switch platform {
        case "YouTube":
            return "youtube-video-upload"
        case "Patreon":
            return "patreon-post-draft"
        case "YouTube Shorts":
            return "youtube-shorts-upload"
        case "Instagram":
            return "instagram-reel-upload"
        case "Facebook":
            return "facebook-reel-upload"
        case "LinkedIn":
            return "linkedin-video-post"
        case "Spotify", "Apple Podcasts":
            return "podcast-feed-or-hosting-publish"
        default:
            return "manual-platform-upload"
        }
    }

    private func defaultUploadJobJSON(
        platform: String,
        deliveryLaneId: String,
        artifactPath: String,
        artifactType: String,
        format: String,
        sequence: MediaSequence
    ) -> String {
        let destinationId = publishDestinationId(
            platform: platform,
            deliveryLaneId: deliveryLaneId,
            format: format
        )
        let destinationGuidance = publishDestinationGuidance(
            platform: platform,
            deliveryLaneId: deliveryLaneId,
            format: format
        )
        let job: [String: Any] = [
            "platform": platform,
            "jobKind": defaultUploadJobKind(platform: platform),
            "status": artifactPath.isEmpty ? "needs-export" : "integration-needed",
            "requiredIntegration": requiredIntegration(platform: platform),
            "deliveryLaneId": deliveryLaneId,
            "destinationId": destinationId,
            "destinationGuidance": destinationGuidance,
            "artifactPath": artifactPath,
            "artifactType": artifactType,
            "format": format,
            "sequenceTitle": sequence.title,
            "receiptWritesTo": "publishReceipts.providerReceiptId publicURL receiptJson publishedAt",
            "safeToRunAutomatically": false,
            "reason": "Platform OAuth/API upload is not wired yet; this is the job shape future integration should execute."
        ]
        return stableJSONString(job)
    }

    private func requiredIntegration(platform: String) -> String {
        switch platform {
        case "YouTube", "YouTube Shorts":
            return "youtube-data-api-oauth-upload"
        case "Patreon":
            return "patreon-api-oauth-post"
        case "Instagram", "Facebook":
            return "meta-graph-api-publishing"
        case "LinkedIn":
            return "linkedin-marketing-api-video"
        case "Spotify", "Apple Podcasts":
            return "podcast-host-rss-feed-or-platform-api"
        default:
            return "manual-upload"
        }
    }

    private func defaultVisibility(platform: String) -> String {
        switch platform {
        case "Patreon":
            return "patrons-only-draft"
        case "LinkedIn":
            return "draft"
        default:
            return "private-draft"
        }
    }

    private func defaultAudience(platform: String) -> String {
        switch platform {
        case "YouTube Shorts", "Instagram", "Facebook", "LinkedIn":
            return "short-form discovery"
        case "Spotify", "Apple Podcasts":
            return "podcast listeners"
        case "Patreon":
            return "supporters"
        default:
            return "episode viewers"
        }
    }

    private func defaultPublishCategory(platform: String) -> String {
        switch platform {
        case "YouTube", "YouTube Shorts":
            return "Education"
        case "Spotify", "Apple Podcasts":
            return "Podcast"
        default:
            return "Creative work"
        }
    }

    private func defaultPublishTags(platform: String, sequence: MediaSequence) -> [String] {
        var tags = ["Quipsly", "High Ground Odyssey", "podcast"]
        if platform == "YouTube Shorts" || platform == "Instagram" || platform == "Facebook" || platform == "LinkedIn" {
            tags.append("shorts")
        }
        if platform == "Spotify" || platform == "Apple Podcasts" {
            tags.append("audio")
        }
        if sequence.title.lowercased().contains("episode") {
            tags.append("episode")
        }
        return tags
    }

    private func stableJSONString(_ object: [String: Any]) -> String {
        guard JSONSerialization.isValidJSONObject(object),
              let data = try? JSONSerialization.data(withJSONObject: object, options: [.prettyPrinted, .sortedKeys]),
              let text = String(data: data, encoding: .utf8) else {
            return "{}"
        }
        return text
    }

    private func publishMetadataJSON(
        updating existingJSON: String,
        title: String,
        description: String,
        platform: String,
        deliveryLaneId: String,
        artifactPath: String,
        artifactType: String,
        format: String
    ) -> String {
        var object: [String: Any] = [:]
        let trimmed = existingJSON.trimmingCharacters(in: .whitespacesAndNewlines)
        if !trimmed.isEmpty,
           let data = trimmed.data(using: .utf8),
           let parsed = try? JSONSerialization.jsonObject(with: data) as? [String: Any] {
            object = parsed
        }
        object["title"] = title
        object["description"] = description
        object["platform"] = object["platform"] ?? platform
        object["deliveryLaneId"] = object["deliveryLaneId"] ?? deliveryLaneId
        object["artifactPath"] = object["artifactPath"] ?? artifactPath
        object["artifactType"] = object["artifactType"] ?? artifactType
        object["format"] = object["format"] ?? format
        object["humanReviewRequired"] = true
        object["sourcePolicy"] = object["sourcePolicy"] ?? "proxy-rendered artifact over whole synced source lanes"
        return stableJSONString(object)
    }

    private func updatePublishReceiptFromAgent(values: [String: String]) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Publish receipt update blocked: no active sequence"
            updateAgentState()
            return
        }
        guard let rawId = values["id"],
              let receiptId = UUID(uuidString: rawId),
              let index = sequence.publishReceipts.firstIndex(where: { $0.id == receiptId }) else {
            lastMediaAction = "Publish receipt update blocked: receipt not found"
            updateAgentState()
            return
        }

        var shouldSyncMetadataCopy = false
        var explicitMetadataJSON = false
        if let status = values["status"], !status.isEmpty {
            sequence.publishReceipts[index].publishStatus = status
            if status == "published" {
                sequence.publishReceipts[index].publishedAt = Date()
            }
        }
        if let title = values["title"], !title.isEmpty {
            sequence.publishReceipts[index].title = title
            shouldSyncMetadataCopy = true
        }
        if let description = values["description"], !description.isEmpty {
            sequence.publishReceipts[index].description = description
            shouldSyncMetadataCopy = true
        }
        if let providerReceiptId = values["provider_receipt_id"], !providerReceiptId.isEmpty {
            sequence.publishReceipts[index].providerReceiptId = providerReceiptId
        }
        if let publicURL = values["public_url"], !publicURL.isEmpty {
            sequence.publishReceipts[index].publicURL = publicURL
        }
        if let receiptJson = values["receipt_json"], !receiptJson.isEmpty {
            sequence.publishReceipts[index].receiptJson = receiptJson
        }
        if let metadataJson = values["metadata_json"], !metadataJson.isEmpty {
            sequence.publishReceipts[index].metadataJson = metadataJson
            sequence.publishReceipts[index].metadataStatus = "custom"
            explicitMetadataJSON = true
        }
        if let metadataStatus = values["metadata_status"], !metadataStatus.isEmpty {
            sequence.publishReceipts[index].metadataStatus = metadataStatus
        }
        if let uploadJobStatus = values["upload_job_status"], !uploadJobStatus.isEmpty {
            sequence.publishReceipts[index].uploadJobStatus = uploadJobStatus
            if uploadJobStatus == "attempted" {
                sequence.publishReceipts[index].lastUploadAttemptAt = Date()
            }
        }
        if let uploadJobJson = values["upload_job_json"], !uploadJobJson.isEmpty {
            sequence.publishReceipts[index].uploadJobJson = uploadJobJson
        }
        if let notes = values["notes"], !notes.isEmpty {
            sequence.publishReceipts[index].notes = notes
        }
        if shouldSyncMetadataCopy && !explicitMetadataJSON {
            sequence.publishReceipts[index].metadataJson = publishMetadataJSON(
                updating: sequence.publishReceipts[index].metadataJson,
                title: sequence.publishReceipts[index].title,
                description: sequence.publishReceipts[index].description,
                platform: sequence.publishReceipts[index].platform,
                deliveryLaneId: sequence.publishReceipts[index].deliveryLaneId,
                artifactPath: sequence.publishReceipts[index].artifactPath,
                artifactType: sequence.publishReceipts[index].artifactType,
                format: sequence.publishReceipts[index].format
            )
            sequence.publishReceipts[index].metadataStatus = "custom"
        }
        sequence.publishReceipts[index].updatedAt = Date()
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Update Publish Receipt")
        scheduleAutosave(reason: "updated publish receipt")
        lastMediaAction = "Updated publish receipt: \(sequence.publishReceipts[index].platform)"
        updateAgentState()
    }

    private func updatePublishReceiptByPlatformFromAgent(values: [String: String]) {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Publish receipt update blocked: no active sequence"
            updateAgentState()
            return
        }

        let platform = (values["platform"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !platform.isEmpty else {
            lastMediaAction = "Publish receipt update blocked: missing platform"
            updateAgentState()
            return
        }

        let laneId = (values["lane_id"] ?? values["delivery_lane_id"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let format = (values["format"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let artifactType = (values["artifact_type"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedPlatform = platform.lowercased()

        let candidates = sequence.publishReceipts.filter { record in
            guard record.platform.lowercased() == normalizedPlatform else { return false }
            if !publishLaneMatches(record.deliveryLaneId, targetLaneId: laneId) { return false }
            if !format.isEmpty && record.format.lowercased() != format.lowercased() { return false }
            if !artifactType.isEmpty && record.artifactType.lowercased() != artifactType.lowercased() { return false }
            return true
        }
        guard let receipt = candidates.sorted(by: { lhs, rhs in
            if lhs.publishStatus == rhs.publishStatus {
                return lhs.updatedAt > rhs.updatedAt
            }
            if lhs.publishStatus == "ready-to-upload" { return true }
            if rhs.publishStatus == "ready-to-upload" { return false }
            return lhs.updatedAt > rhs.updatedAt
        }).first else {
            lastMediaAction = "Publish receipt update blocked: no record for \(platform)"
            updateAgentState()
            return
        }

        var updateValues = values
        updateValues["id"] = receipt.id.uuidString
        if let status = updateValues["status"],
           updateValues["upload_job_status"]?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true {
            updateValues["upload_job_status"] = uploadJobStatusForManualReceipt(status)
        }
        updatePublishReceiptFromAgent(values: updateValues)
    }

    private func copyPublishLedgerJSON() {
