    private func beginEditingPublishReceipt(_ record: PublishReceiptRecord) {
        publishReceiptEditId = record.id
        publishReceiptEditStatus = record.publishStatus == "ready-to-upload" ? "uploaded" : record.publishStatus
        publishReceiptEditTitle = record.title
        publishReceiptEditDescription = record.description
        publishReceiptEditPublicURL = record.publicURL
        publishReceiptEditProviderId = record.providerReceiptId
        publishReceiptEditNotes = record.notes
        publishReceiptQuickStatus = publishReceiptEditStatus
        publishReceiptQuickURL = record.publicURL
        publishReceiptQuickProviderId = record.providerReceiptId
        lastMediaAction = "Editing \(record.platform) publish receipt"
        updateAgentState()
    }

    private func clearPublishReceiptEditor() {
        publishReceiptEditId = nil
        publishReceiptEditStatus = "uploaded"
        publishReceiptEditTitle = ""
        publishReceiptEditDescription = ""
        publishReceiptEditPublicURL = ""
        publishReceiptEditProviderId = ""
        publishReceiptEditNotes = ""
        publishReceiptQuickStatus = "published"
        publishReceiptQuickURL = ""
        publishReceiptQuickProviderId = ""
        lastMediaAction = "Closed publish receipt editor"
        updateAgentState()
    }

    private func savePublishReceiptEditor() {
        guard let publishReceiptEditId else {
            lastMediaAction = "Publish receipt save blocked: no selected receipt"
            updateAgentState()
            return
        }

        var values: [String: String] = [
            "id": publishReceiptEditId.uuidString,
            "status": publishReceiptEditStatus,
            "upload_job_status": uploadJobStatusForManualReceipt(publishReceiptEditStatus)
        ]
        let title = publishReceiptEditTitle.trimmingCharacters(in: .whitespacesAndNewlines)
        if !title.isEmpty {
            values["title"] = title
        }
        let description = publishReceiptEditDescription.trimmingCharacters(in: .whitespacesAndNewlines)
        if !description.isEmpty {
            values["description"] = description
        }
        let publicURL = publishReceiptEditPublicURL.trimmingCharacters(in: .whitespacesAndNewlines)
        if !publicURL.isEmpty {
            values["public_url"] = publicURL
        }
        let providerId = publishReceiptEditProviderId.trimmingCharacters(in: .whitespacesAndNewlines)
        if !providerId.isEmpty {
            values["provider_receipt_id"] = providerId
        }
        let notes = publishReceiptEditNotes.trimmingCharacters(in: .whitespacesAndNewlines)
        if !notes.isEmpty {
            values["notes"] = notes
        }

        updatePublishReceiptFromAgent(values: values)
    }

    private func uploadJobStatusForManualReceipt(_ publishStatus: String) -> String {
        switch publishStatus {
        case "uploaded":
            return "manual-upload-recorded"
        case "scheduled":
            return "manual-schedule-recorded"
        case "published":
            return "manual-publish-recorded"
        case "failed":
            return "failed"
        default:
            return publishStatus
        }
    }

