    private func copyPublishUploadPacketFromAgent(values: [String: String]) {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Upload packet copy blocked: no active sequence"
            updateAgentState()
            return
        }
        let rawId = (values["id"] ?? values["receipt_id"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        guard let receiptId = UUID(uuidString: rawId),
              let record = sequence.publishReceipts.first(where: { $0.id == receiptId }) else {
            lastMediaAction = "Upload packet copy blocked: receipt_id not found"
            updateAgentState()
            return
        }
        copyPublishUploadPacket(record)
    }

    private func generatePublishUploadPacketBundleForAgent(directoryPath: String?, basename: String?) {
        guard let sequence = projectStore.activeSequence else {
            publishUploadBundleStatus = "blocked"
            publishUploadBundleOutputPath = ""
            publishUploadBundleErrorMessage = "Load an episode session before generating upload packets."
            publishUploadBundleGeneratedAt = Date()
            lastMediaAction = "Upload packet bundle blocked: no loaded session"
            updateAgentState()
            return
        }
        guard !sequence.publishReceipts.isEmpty else {
            publishUploadBundleStatus = "blocked"
            publishUploadBundleOutputPath = ""
            publishUploadBundleErrorMessage = "Generate the publish ledger before generating upload packets."
            publishUploadBundleGeneratedAt = Date()
            lastMediaAction = "Upload packet bundle blocked: no publish records"
            updateAgentState()
            return
        }

        publishUploadBundleStatus = "generating"
        publishUploadBundleOutputPath = ""
        publishUploadBundleErrorMessage = ""
        publishUploadBundleGeneratedAt = Date()

        do {
            let rootDirectory: URL
            if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                rootDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
            } else {
                rootDirectory = defaultPublishPacketDirectory()
                    .appendingPathComponent("UploadPacketBundles", isDirectory: true)
            }
            let safeBase = sanitizedExportBasename(basename?.isEmpty == false ? basename! : "\(normalizedActiveSessionName())-upload-packets")
            let bundleDirectory = rootDirectory.appendingPathComponent("\(safeBase)-upload-packet-bundle", isDirectory: true)
            let packetsDirectory = bundleDirectory.appendingPathComponent("upload-packets", isDirectory: true)
            try FileManager.default.createDirectory(at: packetsDirectory, withIntermediateDirectories: true)

            let sortedRecords = sequence.publishReceipts.sorted {
                let left = publishReceiptDisplayLabel($0)
                let right = publishReceiptDisplayLabel($1)
                if left == right {
                    return $0.platform < $1.platform
                }
                return left < right
            }

            var packetRows: [[String: Any]] = []
            for (index, record) in sortedRecords.enumerated() {
                let packet = publishUploadPacketPayload(record)
                let packetNumber = String(format: "%02d", index + 1)
                let filename = "\(packetNumber)-\(sanitizedExportBasename(record.platform).lowercased())-\(sanitizedExportBasename(publishReceiptLaneDisplayLabel(record)).lowercased()).json"
                let packetURL = packetsDirectory.appendingPathComponent(filename)
                try writeJSONObject(packet, to: packetURL)
                packetRows.append([
                    "index": index + 1,
                    "receiptId": record.id.uuidString,
                    "platform": record.platform,
                    "displayLabel": publishReceiptDisplayLabel(record),
                    "deliveryLaneId": record.deliveryLaneId,
                    "format": record.format,
                    "artifactPath": record.artifactPath,
                    "artifactExists": publishRecordArtifactExists(record),
                    "receiptCaptured": publishRecordReceiptCaptured(record),
                    "publishStatus": record.publishStatus,
                    "receiptCaptureCommand": "script/agentctl.sh publish-receipt-update \(record.id.uuidString) published <public-url> <provider-id> \"manual receipt\"",
                    "packetPath": packetURL.path
                ])
            }

            let manifestURL = bundleDirectory.appendingPathComponent("\(safeBase)-upload-packet-bundle.json")
            let csvURL = bundleDirectory.appendingPathComponent("\(safeBase)-upload-packet-index.csv")
            let readmeURL = bundleDirectory.appendingPathComponent("README.md")
            try writeJSONObject(
                publishUploadPacketBundleManifest(sequence: sequence, bundleDirectory: bundleDirectory.path, packetRows: packetRows),
                to: manifestURL
            )
            try publishUploadPacketBundleCSV(rows: packetRows).write(to: csvURL, atomically: true, encoding: .utf8)
            try publishUploadPacketBundleReadme(sequence: sequence, packetRows: packetRows, manifestURL: manifestURL, csvURL: csvURL)
                .write(to: readmeURL, atomically: true, encoding: .utf8)

            publishUploadBundleStatus = "generated"
            publishUploadBundleOutputPath = bundleDirectory.path
            publishUploadBundleErrorMessage = ""
            publishUploadBundleGeneratedAt = Date()
            lastMediaAction = "Generated upload packet bundle: \(bundleDirectory.lastPathComponent)"
        } catch {
            publishUploadBundleStatus = "failed"
            publishUploadBundleOutputPath = ""
            publishUploadBundleErrorMessage = error.localizedDescription
            publishUploadBundleGeneratedAt = Date()
            lastMediaAction = "Upload packet bundle failed: \(error.localizedDescription)"
        }
        updateAgentState()
    }

    private func publishUploadPacketBundleManifest(sequence: MediaSequence, bundleDirectory: String, packetRows: [[String: Any]]) -> [String: Any] {
        let formatter = ISO8601DateFormatter()
        return [
            "model": "quipsly-publish-upload-packet-bundle",
            "version": "2026-06-17.publish-upload-packet-bundle.v1",
            "generatedAt": formatter.string(from: Date()),
            "sessionName": normalizedActiveSessionName(),
            "sequenceTitle": sequence.title,
            "bundleFolder": bundleDirectory,
            "recordCount": packetRows.count,
            "artifactReadyCount": packetRows.filter { ($0["artifactExists"] as? Bool) == true }.count,
            "receiptCapturedCount": packetRows.filter { ($0["receiptCaptured"] as? Bool) == true }.count,
            "sourcePolicy": "Upload packets reference rendered derivative artifacts and platform copy; source media remains untouched.",
            "operatorRule": "Use each packet to upload or schedule, then capture the platform URL back onto the exact receipt id.",
            "receiptCaptureRule": "After every manual or API upload, write the public or scheduled URL back through the receiptCaptureCommand in the packet row.",
            "packets": packetRows
        ]
    }

    private func publishUploadPacketBundleCSV(rows: [[String: Any]]) -> String {
        let headers = ["index", "receipt_id", "platform", "delivery_lane_id", "format", "display_label", "artifact_exists", "publish_status", "receipt_captured", "artifact_path", "packet_path", "receipt_capture_command"]
        let body = rows.map { row -> [String] in
            [
                "\(row["index"] as? Int ?? 0)",
                row["receiptId"] as? String ?? "",
                row["platform"] as? String ?? "",
                row["deliveryLaneId"] as? String ?? "",
                row["format"] as? String ?? "",
                row["displayLabel"] as? String ?? "",
                "\((row["artifactExists"] as? Bool) == true)",
                row["publishStatus"] as? String ?? "",
                "\((row["receiptCaptured"] as? Bool) == true)",
                row["artifactPath"] as? String ?? "",
                row["packetPath"] as? String ?? "",
                row["receiptCaptureCommand"] as? String ?? ""
            ]
        }
        return ([headers] + body)
            .map { $0.map(csvEscape).joined(separator: ",") }
            .joined(separator: "\n") + "\n"
    }

    private func publishUploadPacketBundleReadme(sequence: MediaSequence, packetRows: [[String: Any]], manifestURL: URL, csvURL: URL) -> String {
        let list = packetRows.map { row -> String in
            let index = row["index"] as? Int ?? 0
            let platform = row["platform"] as? String ?? "Unknown"
            let label = row["displayLabel"] as? String ?? ""
            let packet = URL(fileURLWithPath: row["packetPath"] as? String ?? "").lastPathComponent
            let receiptCommand = row["receiptCaptureCommand"] as? String ?? ""
            return "\(index). \(platform) - \(label)\n   - Packet: `upload-packets/\(packet)`\n   - Receipt command: `\(receiptCommand)`"
        }.joined(separator: "\n")
        return """
        # Publish Upload Packet Bundle

        Episode: \(sequence.title.isEmpty ? normalizedActiveSessionName() : sequence.title)

        This folder is the manual/Codex upload handoff. It does not upload,
        schedule, or publish anything by itself.

        ## Files
        - `upload-packets/`: one JSON upload packet per platform record.
        - `\(manifestURL.lastPathComponent)`: machine-readable bundle manifest.
        - `\(csvURL.lastPathComponent)`: spreadsheet-friendly upload index.

        ## Upload order
        \(list)

        ## Operator rule
        For each packet: upload or schedule the rendered artifact, then capture
        the public/scheduled URL back onto the exact receipt id in Quipsly.

        Do not mark a platform complete just because the file exists. A platform
        is complete only after the public or scheduled URL is captured back into
        the publish ledger with that packet's receipt command.
        """
    }

    private func generatePublicationCockpitForAgent(directoryPath: String?, basename: String?) {
        guard let sequence = projectStore.activeSequence else {
            publicationCockpitStatus = "blocked"
            publicationCockpitOutputPath = ""
            publicationReceiptLogOutputPath = ""
            publicationCockpitErrorMessage = "Load an episode session before generating a publication cockpit."
            publicationCockpitGeneratedAt = Date()
            lastMediaAction = "Publication cockpit blocked: no loaded session"
            updateAgentState()
            return
        }
        guard !sequence.publishReceipts.isEmpty else {
            publicationCockpitStatus = "blocked"
            publicationCockpitOutputPath = ""
            publicationReceiptLogOutputPath = ""
            publicationCockpitErrorMessage = "Generate the publish ledger before generating the publication cockpit."
            publicationCockpitGeneratedAt = Date()
            lastMediaAction = "Publication cockpit blocked: no publish records"
            updateAgentState()
            return
        }

        publicationCockpitStatus = "generating"
        publicationCockpitOutputPath = ""
        publicationReceiptLogOutputPath = ""
        publicationCockpitErrorMessage = ""
        publicationCockpitGeneratedAt = Date()

        do {
            let rootDirectory: URL
            if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                rootDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
            } else {
                let safeBase = sanitizedExportBasename(basename?.isEmpty == false ? basename! : "\(normalizedActiveSessionName())-publication-cockpit")
                rootDirectory = defaultPublishPacketDirectory()
                    .appendingPathComponent("PublicationCockpits", isDirectory: true)
                    .appendingPathComponent(safeBase, isDirectory: true)
            }
            try FileManager.default.createDirectory(at: rootDirectory, withIntermediateDirectories: true)
            let safeBase = sanitizedExportBasename(basename?.isEmpty == false ? basename! : normalizedActiveSessionName())
            let jsonURL = rootDirectory.appendingPathComponent("publication-cockpit.json")
            let markdownURL = rootDirectory.appendingPathComponent("PUBLICATION-COCKPIT.md")
            let receiptLogURL = rootDirectory.appendingPathComponent("publication-receipt-log.csv")
            let payload = publicationCockpitPayload(
                sequence: sequence,
                rootDirectory: rootDirectory,
                basename: safeBase,
                markdownURL: markdownURL,
                receiptLogURL: receiptLogURL
            )
            try writeJSONObject(payload, to: jsonURL)
            try publicationCockpitMarkdown(payload: payload)
                .write(to: markdownURL, atomically: true, encoding: .utf8)
            try publicationReceiptLogCSV(payload: payload)
                .write(to: receiptLogURL, atomically: true, encoding: .utf8)

            publicationCockpitStatus = "generated"
            publicationCockpitOutputPath = markdownURL.path
            publicationReceiptLogOutputPath = receiptLogURL.path
            publicationCockpitErrorMessage = ""
            publicationCockpitGeneratedAt = Date()
            lastMediaAction = "Generated publication cockpit: \(markdownURL.lastPathComponent)"
        } catch {
            publicationCockpitStatus = "failed"
            publicationCockpitOutputPath = ""
            publicationReceiptLogOutputPath = ""
            publicationCockpitErrorMessage = error.localizedDescription
            publicationCockpitGeneratedAt = Date()
            lastMediaAction = "Publication cockpit failed: \(error.localizedDescription)"
        }
        updateAgentState()
    }

    private func publicationCockpitPayload(
        sequence: MediaSequence,
        rootDirectory: URL,
        basename: String,
        markdownURL: URL,
        receiptLogURL: URL
    ) -> [String: Any] {
        let formatter = ISO8601DateFormatter()
        let records = sequence.publishReceipts
        let completion = publicationReceiptCompletionSummary(for: sequence)
        let platformCounts = Dictionary(grouping: records, by: { $0.platform })
            .mapValues { $0.count }
        let receiptCounts = Dictionary(grouping: records.filter { publishRecordReceiptCaptured($0) }, by: { $0.platform })
            .mapValues { $0.count }
        let readyHandoff = publicationReadyHandoffPayload(for: sequence)
        let topShorts = sequence.shortClipQueue.prefix(8).map { clip in
            [
                "id": clip.id.uuidString,
                "title": clip.title,
                "hook": clip.hookText,
                "duration": clip.duration,
                "format": clip.format.rawValue,
                "status": clip.status,
                "reviewStatus": clip.reviewStatus,
                "exportStatus": clip.exportStatus,
                "destinations": clip.destinations,
                "exportPath": lastExportedShortPath(for: clip) ?? "",
                "captionDraft": clip.captionDraft,
                "primaryOverlayText": clip.primaryOverlayText
            ] as [String: Any]
        }
        let packetRows = records.sorted { left, right in
            if left.platform == right.platform {
                return publishReceiptDisplayLabel(left) < publishReceiptDisplayLabel(right)
            }
            return left.platform < right.platform
        }.map { record in
            [
                "receiptId": record.id.uuidString,
                "platform": record.platform,
                "deliveryLaneId": record.deliveryLaneId,
                "format": record.format,
                "displayLabel": publishReceiptDisplayLabel(record),
                "artifactPath": record.artifactPath,
                "artifactExists": publishRecordArtifactExists(record),
                "receiptCaptured": publishRecordReceiptCaptured(record),
                "publishStatus": record.publishStatus,
                "publicURL": record.publicURL,
                "providerReceiptId": record.providerReceiptId,
                "notes": record.notes,
                "receiptCaptureCommand": "script/agentctl.sh publish-receipt-update \(record.id.uuidString) published <public-url> <provider-id> \"manual receipt\""
            ] as [String: Any]
        }

        return [
            "model": "quipsly-publication-cockpit",
            "version": "2026-06-17.native-publication-cockpit.v2",
            "generatedAt": formatter.string(from: Date()),
            "sessionName": normalizedActiveSessionName(),
            "sequenceTitle": sequence.title,
            "basename": basename,
            "cockpitMarkdownPath": markdownURL.path,
            "receiptLogPath": receiptLogURL.path,
            "cockpitFolder": rootDirectory.path,
            "status": completion["publicationPhase"] ?? "ready-for-human-review",
            "sourcePolicy": "Rendered derivatives and packet manifests only. Do not touch or upload raw source media from the cockpit.",
            "closedLoopRule": "A post is not complete until the public or scheduled URL is captured back into the matching Quipsly receipt.",
            "summary": [
                "publishRecordCount": records.count,
                "artifactReadyCount": records.filter { publishRecordArtifactExists($0) }.count,
                "receiptCapturedCount": records.filter { publishRecordReceiptCaptured($0) }.count,
                "receiptRemainingCount": completion["receiptRemainingCount"] ?? 0,
                "publicationPhase": completion["publicationPhase"] ?? "ready-for-human-review",
                "publicationComplete": completion["publicationComplete"] ?? false,
                "shortCandidateCount": sequence.shortClipQueue.count,
                "platformCounts": platformCounts,
                "receiptCounts": receiptCounts
            ],
            "handoffArtifacts": [
                "deliveryPacketOutputPath": deliveryPacketOutputPath,
                "publishPacketOutputPath": publishPacketOutputPath,
                "publishUploadBundleOutputPath": publishUploadBundleOutputPath,
                "socialShortsPacketOutputPath": socialShortsPacketOutputPath,
                "socialPublicationQueueOutputPath": socialPublicationQueueOutputPath,
                "podcastPacketOutputPath": podcastPacketOutputPath,
                "podcastReadyPacketOutputPath": podcastReadyPacketOutputPath
            ],
            "publicationReadyHandoff": readyHandoff,
            "topShorts": topShorts,
            "uploadPackets": packetRows,
            "nextActions": [
                "Review the 16:9 episode master once.",
                "Review the 9:16 full vertical master once.",
                "Review top short candidates before posting.",
                "Upload or schedule platform packets manually until direct connectors are proven.",
                "Capture public or scheduled URLs back using each receiptCaptureCommand."
            ]
        ]
    }

    private func publicationCockpitMarkdown(payload: [String: Any]) -> String {
        let summary = payload["summary"] as? [String: Any] ?? [:]
        let artifacts = payload["handoffArtifacts"] as? [String: String] ?? [:]
        let readyHandoff = payload["publicationReadyHandoff"] as? [String: Any] ?? [:]
        let shorts = payload["topShorts"] as? [[String: Any]] ?? []
        let packets = payload["uploadPackets"] as? [[String: Any]] ?? []
        let groupedPackets = Dictionary(grouping: packets, by: { $0["platform"] as? String ?? "Unknown" })
        let shortList = shorts.enumerated().map { index, clip -> String in
            let title = clip["title"] as? String ?? "Untitled short"
            let hook = clip["hook"] as? String ?? ""
            let path = clip["exportPath"] as? String ?? ""
            return "\(index + 1). \(title)\n   - Hook: \(hook)\n   - File: `\(path)`"
        }.joined(separator: "\n")
        let artifactList = artifacts.sorted { $0.key < $1.key }.map { key, value in
            "- \(key): `\(value)`"
        }.joined(separator: "\n")
        let readyHandoffSection = publicationReadyHandoffMarkdown(readyHandoff)
        let platformSections = groupedPackets.keys.sorted().map { platform -> String in
            let rows = groupedPackets[platform] ?? []
            let captured = rows.filter { ($0["receiptCaptured"] as? Bool) == true }.count
            let uploadRows = rows.map { row -> String in
                let label = row["displayLabel"] as? String ?? "Untitled"
                let artifact = row["artifactPath"] as? String ?? ""
                let command = row["receiptCaptureCommand"] as? String ?? ""
                return "- \(label)\n  - Artifact: `\(artifact)`\n  - Receipt: `\(command)`"
            }.joined(separator: "\n")
            return "### \(platform)\n\nReceipts captured: \(captured)/\(rows.count)\n\n\(uploadRows)"
        }.joined(separator: "\n\n")

        return """
        # Episode Publication Cockpit

        Session: \(payload["sessionName"] as? String ?? "")
        Sequence: \(payload["sequenceTitle"] as? String ?? "")
        Generated: \(payload["generatedAt"] as? String ?? "")

        ## North star

        Use this cockpit to publish rendered episode assets without touching source media.

        - Source policy: \(payload["sourcePolicy"] as? String ?? "")
        - Closed-loop rule: \(payload["closedLoopRule"] as? String ?? "")

        ## Readiness

        - Publish records: \(summary["publishRecordCount"] ?? 0)
        - Artifacts ready: \(summary["artifactReadyCount"] ?? 0)
        - Receipts captured: \(summary["receiptCapturedCount"] ?? 0)
        - Receipts remaining: \(summary["receiptRemainingCount"] ?? 0)
        - Publication phase: **\(summary["publicationPhase"] ?? "ready-for-human-review")**
        - Short candidates: \(summary["shortCandidateCount"] ?? 0)
        - Receipt log: `\(payload["receiptLogPath"] as? String ?? "")`

        ## Ready-to-publish lanes

        \(readyHandoffSection)

        ## Handoff artifacts

        \(artifactList)

        ## 9:16 short candidates

        \(shortList.isEmpty ? "No short candidates queued yet." : shortList)

        ## Platform upload checklist

        \(platformSections)

        ## Operator next actions

        1. Review the 16:9 master.
        2. Review the 9:16 master and short candidates.
        3. Upload or schedule from the platform packets.
        4. Capture public or scheduled URLs back into Quipsly receipts.
        5. Refresh handoff artifacts and verify `publication-complete` before archiving the release.
        """
    }

    private func publicationReadyHandoffMarkdown(_ payload: [String: Any]) -> String {
        guard !payload.isEmpty else {
            return "No publication handoff summary was generated."
        }

        let lanes: [(String, String, String)] = [
            ("16:9 episode", "episode16x9", "YouTube / Patreon"),
            ("9:16 shorts", "social9x16", "YouTube Shorts / Instagram / Facebook / LinkedIn"),
            ("Podcast audio", "podcastAudio", "Spotify / Apple Podcasts")
        ]

        let laneLines = lanes.map { laneSpec -> String in
            let (title, key, destinations) = laneSpec
            let lane = payload[key] as? [String: Any] ?? [:]
            let status = lane["status"] as? String ?? "unknown"
            let nextAction = lane["nextAction"] as? String ?? "Review the release state in Quipsly."
            let artifactPath = (lane["artifactPath"] as? String)
                ?? (lane["manifestPath"] as? String)
                ?? ""
            let clipCount = lane["clipCount"] as? Int
            let receiptCaptured = lane["receiptCaptured"] as? Bool
            var metadata: [String] = []
            if let clipCount {
                metadata.append("clips: \(clipCount)")
            }
            if let receiptCaptured {
                metadata.append("receipt captured: \(receiptCaptured)")
            }
            let metadataLine = metadata.isEmpty ? "" : "\n  - \(metadata.joined(separator: "; "))"
            return """
            - **\(title)** (\(destinations))
              - Status: `\(status)`
              - Next: \(nextAction)
              - Artifact/manifest: `\(artifactPath.isEmpty ? "not generated yet" : artifactPath)`\(metadataLine)
            """
        }.joined(separator: "\n")

        let readyLaneCount = payload["readyLaneCount"] as? Int ?? 0
        let laneCount = payload["laneCount"] as? Int ?? 3
        let publishingTruth = payload["publishingTruth"] as? String ?? "Platform publication is only true after receipt capture."
        let receiptProof = payload["receiptProof"] as? [String: Any] ?? [:]
        let receiptSummary = receiptProof["summary"] as? [String: Any] ?? [:]
        let receiptArtifacts = receiptProof["operatorArtifacts"] as? [String: Any] ?? [:]
        let receiptTotal = receiptSummary["receiptTotalCount"] as? Int ?? 0
        let receiptCaptured = receiptSummary["receiptCapturedCount"] as? Int ?? 0
        let receiptRemaining = receiptSummary["receiptRemainingCount"] as? Int ?? max(0, receiptTotal - receiptCaptured)
        let publicationPhase = receiptSummary["publicationPhase"] as? String ?? "ready-for-human-review"
        let receiptNextAction = receiptProof["nextAction"] as? String ?? "Capture platform URLs/provider ids after manual or API publishing."
        let receiptLogPath = receiptArtifacts["receiptLogPath"] as? String ?? ""
        return """
        Ready lanes: **\(readyLaneCount)/\(laneCount)**

        \(publishingTruth)

        \(laneLines)

        ## Publication proof

        - Phase: `\(publicationPhase)`
        - Receipts captured: **\(receiptCaptured)/\(receiptTotal)** (\(receiptRemaining) remaining)
        - Receipt log: `\(receiptLogPath.isEmpty ? "not generated yet" : receiptLogPath)`
        - Next: \(receiptNextAction)
        """
    }

    private func publicationReceiptLogCSV(payload: [String: Any]) -> String {
        let headers = [
            "receipt_id",
            "platform",
            "display_label",
            "delivery_lane_id",
            "format",
            "artifact_path",
            "artifact_exists",
            "current_publish_status",
            "current_public_url",
            "current_provider_receipt_id",
            "new_status",
            "public_url",
            "provider_receipt_id",
            "notes",
            "metadata_json",
            "receipt_capture_command"
        ]
        let rows = (payload["uploadPackets"] as? [[String: Any]] ?? []).map { row -> [String] in
            let currentURL = row["publicURL"] as? String ?? ""
            let currentProvider = row["providerReceiptId"] as? String ?? ""
            let currentStatus = row["publishStatus"] as? String ?? ""
            return [
                row["receiptId"] as? String ?? "",
                row["platform"] as? String ?? "",
                row["displayLabel"] as? String ?? "",
                row["deliveryLaneId"] as? String ?? "",
                row["format"] as? String ?? "",
                row["artifactPath"] as? String ?? "",
                "\((row["artifactExists"] as? Bool) == true)",
                currentStatus,
                currentURL,
                currentProvider,
                (currentURL.isEmpty && currentProvider.isEmpty) ? "published" : currentStatus,
                currentURL,
                currentProvider,
                row["notes"] as? String ?? "",
                "",
                row["receiptCaptureCommand"] as? String ?? ""
            ]
        }
        return ([headers] + rows)
            .map { $0.map(csvEscape).joined(separator: ",") }
            .joined(separator: "\n") + "\n"
    }

