    private func copyPublishReceiptText(_ text: String, successMessage: String) {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            lastMediaAction = "Publish ledger copy blocked: no text to copy"
            updateAgentState()
            return
        }
        #if os(macOS)
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(text, forType: .string)
        #endif
        lastMediaAction = successMessage
        updateAgentState()
    }

