    private func receiptCaptureSummaryText(_ summary: [String: Any]) -> String {
        let recordCount = summary["recordCount"] as? Int ?? 0
        let capturedCount = summary["capturedCount"] as? Int ?? 0
        let missingCount = summary["missingCount"] as? Int ?? 0
        let readyCount = summary["readyForReceiptCaptureCount"] as? Int ?? 0
        if recordCount == 0 {
            return "No publish records yet. Generate the ledger after export so Quipsly can track YouTube, Patreon, social, and podcast receipts."
        }
        if missingCount == 0 {
            return "All \(recordCount) publish receipt(s) have captured URLs or provider receipts."
        }
        if readyCount > 0 {
            return "\(capturedCount)/\(recordCount) receipt(s) captured. \(readyCount) artifact(s) are ready for upload/schedule URL capture."
        }
        return "\(capturedCount)/\(recordCount) receipt(s) captured. \(missingCount) record(s) still need artifact/copy readiness before receipt capture."
    }

    private func publishReceiptCaptureChecklistText(records: [PublishReceiptRecord]) -> String {
        let summary = publishReceiptCaptureSummary(records: records)
        let readyMissing = publishReceiptCaptureReadyMissingRecords(records: records)
        let missing = records.filter { !publishRecordReceiptCaptured($0) }
        let readyLines = readyMissing.enumerated().map { index, record in
            "\(index + 1). \(publishReceiptDisplayLabel(record))\n   receipt id: \(record.id.uuidString)\n   artifact: \(record.artifactPath)"
        }.joined(separator: "\n")
        let blockedLines = missing.filter { !readyMissing.contains($0) }.prefix(8).enumerated().map { index, record in
            "\(index + 1). \(publishReceiptDisplayLabel(record)) - needs artifact/copy readiness before receipt capture"
        }.joined(separator: "\n")
        return """
        Quipsly publish receipt capture checklist

        \(receiptCaptureSummaryText(summary))

        Ready for receipt capture:
        \(readyLines.isEmpty ? "None yet." : readyLines)

        Missing but not ready:
        \(blockedLines.isEmpty ? "None." : blockedLines)

        Agent command:
        script/agentctl.sh publish-receipt-update RECEIPT_ID published https://example.com provider-id "manual receipt"

        Operator rule: after every manual upload or scheduled post, capture the public/scheduled URL on the exact publish record before moving to the next artifact.
        """
    }

