    private func importSocialMasterQueue(from url: URL) {
        do {
            let data = try Data(contentsOf: url)
            let object = try JSONSerialization.jsonObject(with: data)
            guard let payload = object as? [String: Any] else {
                throw NSError(
                    domain: "QuipslySocialMasterQueue",
                    code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "The selected file is not a JSON object."]
                )
            }
            let clips = payload["clips"] as? [[String: Any]] ?? []
            guard !clips.isEmpty else {
                throw NSError(
                    domain: "QuipslySocialMasterQueue",
                    code: 2,
                    userInfo: [NSLocalizedDescriptionKey: "The selected social master queue has no clips."]
                )
            }

            let titles = clips.compactMap { clip -> String? in
                let title = (clip["title"] as? String ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
                return title.isEmpty ? nil : title
            }
            var packCounts: [String: Int] = [:]
            for clip in clips {
                let pack = (clip["sourcePack"] as? String ?? "unknown").trimmingCharacters(in: .whitespacesAndNewlines)
                let key = pack.isEmpty ? "unknown" : pack
                packCounts[key, default: 0] += 1
            }
            let candidatePreview: [[String: String]] = clips.map { clip in
                let rankNumber = clip["rank"] as? NSNumber
                let queueIndexNumber = clip["queueIndex"] as? NSNumber
                let durationNumber = clip["duration"] as? NSNumber ?? clip["durationSeconds"] as? NSNumber
                let sourceStartNumber = clip["sourceSequenceStartSeconds"] as? NSNumber
                let sourceEndNumber = clip["sourceSequenceEndSeconds"] as? NSNumber
                let platforms: String
                if let platformList = clip["platforms"] as? [String] {
                    platforms = platformList.joined(separator: ", ")
                } else {
                    platforms = clip["platforms"] as? String ?? ""
                }
                let rawPlatformReceiptIds = clip["platformReceiptIds"] as? [String: Any] ?? [:]
                let platformReceiptIds = rawPlatformReceiptIds.reduce(into: [String: String]()) { result, item in
                    if let value = item.value as? String {
                        result[item.key] = value
                    }
                }
                let sourceReceiptIds = (clip["sourcePublishReceiptIds"] as? [String] ?? []).joined(separator: ", ")
                return [
                    "rank": rankNumber.map { "\($0.intValue)" } ?? "",
                    "queueIndex": queueIndexNumber.map { "\($0.intValue)" } ?? "",
                    "sourcePack": clip["sourcePack"] as? String ?? "",
                    "sourceManifest": clip["sourceManifest"] as? String ?? "",
                    "reviewStatus": clip["reviewStatus"] as? String ?? "",
                    "title": clip["title"] as? String ?? "",
                    "hook": clip["hook"] as? String ?? "",
                    "roughTranscript": clip["roughTranscript"] as? String ?? "",
                    "duration": durationNumber.map { String(format: "%.1f", $0.doubleValue) } ?? "",
                    "sourceSequenceStartSeconds": sourceStartNumber.map { String(format: "%.3f", $0.doubleValue) } ?? "",
                    "sourceSequenceEndSeconds": sourceEndNumber.map { String(format: "%.3f", $0.doubleValue) } ?? "",
                    "sourceShortClipId": clip["sourceShortClipId"] as? String ?? "",
                    "sourcePublishReceiptIds": sourceReceiptIds,
                    "youtubeShortsReceiptId": platformReceiptIds["YouTube Shorts"] ?? clip["youtubeShortsReceiptId"] as? String ?? "",
                    "instagramReceiptId": platformReceiptIds["Instagram"] ?? platformReceiptIds["Instagram Reels"] ?? clip["instagramReceiptId"] as? String ?? "",
                    "facebookReceiptId": platformReceiptIds["Facebook"] ?? platformReceiptIds["Facebook Reels"] ?? clip["facebookReceiptId"] as? String ?? "",
                    "linkedinReceiptId": platformReceiptIds["LinkedIn"] ?? clip["linkedinReceiptId"] as? String ?? "",
                    "platformReceiptCount": "\(platformReceiptIds.count)",
                    "clipPath": clip["clipPath"] as? String ?? "",
                    "thumbnailPath": clip["thumbnailPath"] as? String ?? "",
                    "captionSrtPath": clip["captionSrtPath"] as? String ?? "",
                    "platformCopyPath": clip["platformCopyPath"] as? String ?? "",
                    "platforms": platforms,
                    "humanCheck": clip["humanCheck"] as? String ?? ""
                ]
            }

            socialMasterQueueStatus = "loaded"
            socialMasterQueueOutputPath = url.path
            socialMasterQueueErrorMessage = ""
            socialMasterQueueGeneratedAt = Date()
            socialMasterQueueClipCount = clips.count
            socialMasterQueueTopTitles = Array(titles.prefix(8))
            socialMasterQueueCandidatePreview = candidatePreview
            selectedSocialMasterQueueRank = candidatePreview.first?["rank"] ?? ""
            socialMasterReceiptCapturePlatform = socialMasterQueueSelectedPlatforms().first ?? "YouTube Shorts"
            socialMasterReceiptCaptureURL = ""
            socialMasterReceiptCaptureProviderId = ""
            socialMasterQueueSourcePackSummary = packCounts
                .sorted { left, right in
                    if left.value == right.value { return left.key < right.key }
                    return left.value > right.value
                }
                .map { "\($0.key): \($0.value)" }
            lastMediaAction = "Loaded social master queue: \(clips.count) clip(s)"
        } catch {
            socialMasterQueueStatus = "failed"
            socialMasterQueueOutputPath = url.path
            socialMasterQueueErrorMessage = error.localizedDescription
            socialMasterQueueGeneratedAt = Date()
            socialMasterQueueClipCount = 0
            socialMasterQueueTopTitles = []
            socialMasterQueueSourcePackSummary = []
            socialMasterQueueCandidatePreview = []
            selectedSocialMasterQueueRank = ""
            lastMediaAction = "Social master queue load failed: \(error.localizedDescription)"
        }
        updateAgentState()
    }

    private func importSocialMasterQueueFromAgent(path: String?) {
        let trimmedPath = (path ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedPath.isEmpty else {
            socialMasterQueueStatus = "blocked"
            socialMasterQueueOutputPath = ""
            socialMasterQueueErrorMessage = "Agent load blocked: provide an absolute social-master-queue.json path."
            socialMasterQueueGeneratedAt = Date()
            lastMediaAction = "Social master queue agent load blocked: missing path"
            updateAgentState()
            return
        }

        let url = URL(fileURLWithPath: trimmedPath)
        guard url.pathExtension.lowercased() == "json" else {
            socialMasterQueueStatus = "blocked"
            socialMasterQueueOutputPath = trimmedPath
            socialMasterQueueErrorMessage = "Agent load blocked: expected a JSON file."
            socialMasterQueueGeneratedAt = Date()
            lastMediaAction = "Social master queue agent load blocked: non-JSON path"
            updateAgentState()
            return
        }

        importSocialMasterQueue(from: url)
    }

    private func generateSocialReadyPacketFromAgent(values: [String: String]) {
        let queuePath = (values["queue_path"] ?? values["path"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let outputPath = (values["output"] ?? values["directory"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let basename = sanitizedExportBasename(values["basename"]?.isEmpty == false ? values["basename"]! : "social-clips-ready")
        let topCount = max(1, Int(values["top_count"] ?? "") ?? 12)
        let shouldZip = ["1", "true", "yes", "zip", "--zip"].contains((values["zip"] ?? "").lowercased())

        guard !queuePath.isEmpty, !outputPath.isEmpty else {
            socialMasterQueueStatus = "blocked"
            socialMasterQueueOutputPath = outputPath
            socialMasterQueueErrorMessage = "Social ready packet blocked: provide queue_path and output."
            socialMasterQueueGeneratedAt = Date()
            lastMediaAction = "Social ready packet blocked: missing queue or output"
            updateAgentState()
            return
        }

        guard FileManager.default.fileExists(atPath: queuePath) else {
            socialMasterQueueStatus = "blocked"
            socialMasterQueueOutputPath = outputPath
            socialMasterQueueErrorMessage = "Social ready packet blocked: queue does not exist at \(queuePath)"
            socialMasterQueueGeneratedAt = Date()
            lastMediaAction = "Social ready packet blocked: queue missing"
            updateAgentState()
            return
        }

        guard let scriptURL = socialReadyPacketBuilderURL() else {
            socialMasterQueueStatus = "blocked"
            socialMasterQueueOutputPath = outputPath
            socialMasterQueueErrorMessage = "Social ready packet blocked: script/build_social_ready_packet.py was not found."
            socialMasterQueueGeneratedAt = Date()
            lastMediaAction = "Social ready packet blocked: builder script missing"
            updateAgentState()
            return
        }

        let manifestURL = URL(fileURLWithPath: outputPath, isDirectory: true).appendingPathComponent("\(basename).json")
        socialMasterQueueStatus = "generating"
        socialMasterQueueOutputPath = outputPath
        socialMasterQueueErrorMessage = ""
        socialMasterQueueGeneratedAt = Date()
        lastMediaAction = "Generating social ready packet: \(basename)"
        updateAgentState()

        Task.detached(priority: .utility) {
            let result = Self.runSocialReadyPacketBuilder(
                scriptURL: scriptURL,
                queuePath: queuePath,
                outputPath: outputPath,
                basename: basename,
                topCount: topCount,
                shouldZip: shouldZip
            )

            await MainActor.run {
                switch result {
                case .success:
                    if FileManager.default.fileExists(atPath: manifestURL.path) {
                        importSocialMasterQueue(from: manifestURL)
                        lastMediaAction = "Generated and loaded social ready packet: \(manifestURL.path)"
                    } else {
                        socialMasterQueueStatus = "failed"
                        socialMasterQueueOutputPath = outputPath
                        socialMasterQueueErrorMessage = "Builder finished, but manifest was not found at \(manifestURL.path)"
                        socialMasterQueueGeneratedAt = Date()
                        lastMediaAction = "Social ready packet failed: manifest missing"
                        updateAgentState()
                    }
                case .failure(let error):
                    socialMasterQueueStatus = "failed"
                    socialMasterQueueOutputPath = outputPath
                    socialMasterQueueErrorMessage = error.localizedDescription
                    socialMasterQueueGeneratedAt = Date()
                    lastMediaAction = "Social ready packet failed: \(error.localizedDescription)"
                    updateAgentState()
                }
            }
        }
    }

    private func generateSocialReadyPacketForFullRelease(
        queueManifestURL: URL,
        outputFolder: URL,
        basename: String,
        topCount: Int
    ) -> Bool {
        guard FileManager.default.fileExists(atPath: queueManifestURL.path) else {
            socialMasterQueueStatus = "failed"
            socialMasterQueueOutputPath = outputFolder.path
            socialMasterQueueErrorMessage = "Social ready packet blocked: queue manifest missing at \(queueManifestURL.path)"
            socialMasterQueueGeneratedAt = Date()
            lastMediaAction = "Social ready packet blocked: queue manifest missing"
            updateAgentState()
            return false
        }
        guard let scriptURL = socialReadyPacketBuilderURL() else {
            socialMasterQueueStatus = "failed"
            socialMasterQueueOutputPath = outputFolder.path
            socialMasterQueueErrorMessage = "Social ready packet blocked: script/build_social_ready_packet.py was not found."
            socialMasterQueueGeneratedAt = Date()
            lastMediaAction = "Social ready packet blocked: builder script missing"
            updateAgentState()
            return false
        }

        let safeBase = sanitizedExportBasename(basename)
        let readyManifestURL = outputFolder.appendingPathComponent("\(safeBase).json")
        socialMasterQueueStatus = "generating"
        socialMasterQueueOutputPath = outputFolder.path
        socialMasterQueueErrorMessage = ""
        socialMasterQueueGeneratedAt = Date()
        updateAgentState()

        let result = Self.runSocialReadyPacketBuilder(
            scriptURL: scriptURL,
            queuePath: queueManifestURL.path,
            outputPath: outputFolder.path,
            basename: safeBase,
            topCount: max(1, topCount),
            shouldZip: true
        )
        switch result {
        case .success:
            guard FileManager.default.fileExists(atPath: readyManifestURL.path) else {
                socialMasterQueueStatus = "failed"
                socialMasterQueueOutputPath = outputFolder.path
                socialMasterQueueErrorMessage = "Social ready builder finished, but manifest was not found at \(readyManifestURL.path)"
                socialMasterQueueGeneratedAt = Date()
                lastMediaAction = "Social ready packet failed: manifest missing"
                updateAgentState()
                return false
            }
            importSocialMasterQueue(from: readyManifestURL)
            lastMediaAction = "Generated and loaded social ready packet: \(readyManifestURL.lastPathComponent)"
            updateAgentState()
            return true
        case .failure(let error):
            socialMasterQueueStatus = "failed"
            socialMasterQueueOutputPath = outputFolder.path
            socialMasterQueueErrorMessage = error.localizedDescription
            socialMasterQueueGeneratedAt = Date()
            lastMediaAction = "Social ready packet failed: \(error.localizedDescription)"
            updateAgentState()
            return false
        }
    }

    private func socialReadyPacketBuilderURL() -> URL? {
        let fileManager = FileManager.default
        let sourceRoot = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .path
        let roots = [
            ProcessInfo.processInfo.environment["QUIPSLY_STUDIO_ROOT"],
            fileManager.currentDirectoryPath,
            Bundle.main.resourceURL?.path,
            sourceRoot
        ]
        .compactMap { raw -> String? in
            let trimmed = (raw ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
            return trimmed.isEmpty ? nil : trimmed
        }

        for root in roots {
            let candidate = URL(fileURLWithPath: root)
                .appendingPathComponent("script")
                .appendingPathComponent("build_social_ready_packet.py")
            if fileManager.fileExists(atPath: candidate.path) {
                return candidate
            }
        }
        return nil
    }

    nonisolated private static func runSocialReadyPacketBuilder(
        scriptURL: URL,
        queuePath: String,
        outputPath: String,
        basename: String,
        topCount: Int,
        shouldZip: Bool
    ) -> Result<String, Error> {
        do {
            let process = Process()
            process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
            var arguments = [
                "python3",
                scriptURL.path,
                queuePath,
                "--output",
                outputPath,
                "--basename",
                basename,
                "--top-count",
                "\(topCount)"
            ]
            if shouldZip {
                arguments.append("--zip")
            }
            process.arguments = arguments
            let stdout = Pipe()
            let stderr = Pipe()
            process.standardOutput = stdout
            process.standardError = stderr
            try process.run()
            process.waitUntilExit()
            let output = String(data: stdout.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
            let errorOutput = String(data: stderr.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
            guard process.terminationStatus == 0 else {
                throw NSError(
                    domain: "QuipslySocialReadyPacket",
                    code: Int(process.terminationStatus),
                    userInfo: [NSLocalizedDescriptionKey: errorOutput.isEmpty ? "Builder exited with status \(process.terminationStatus)." : errorOutput]
                )
            }
            return .success(output)
        } catch {
            return .failure(error)
        }
    }

    private func generatePodcastReadyPacketFromAgent(values: [String: String]) {
        let manifestPath = (values["manifest_path"] ?? values["path"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let outputPath = (values["output"] ?? values["directory"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let basename = sanitizedExportBasename(values["basename"]?.isEmpty == false ? values["basename"]! : "podcast-ready")
        let shouldZip = ["1", "true", "yes", "zip", "--zip"].contains((values["zip"] ?? "").lowercased())

        guard !manifestPath.isEmpty, !outputPath.isEmpty else {
            podcastReadyPacketStatus = "blocked"
            podcastReadyPacketOutputPath = outputPath
            podcastReadyPacketErrorMessage = "Podcast ready packet blocked: provide manifest_path and output."
            podcastReadyPacketGeneratedAt = Date()
            lastMediaAction = "Podcast ready packet blocked: missing manifest or output"
            updateAgentState()
            return
        }

        guard FileManager.default.fileExists(atPath: manifestPath) else {
            podcastReadyPacketStatus = "blocked"
            podcastReadyPacketOutputPath = outputPath
            podcastReadyPacketErrorMessage = "Podcast ready packet blocked: manifest does not exist at \(manifestPath)"
            podcastReadyPacketGeneratedAt = Date()
            lastMediaAction = "Podcast ready packet blocked: manifest missing"
            updateAgentState()
            return
        }

        guard let scriptURL = podcastReadyPacketBuilderURL() else {
            podcastReadyPacketStatus = "blocked"
            podcastReadyPacketOutputPath = outputPath
            podcastReadyPacketErrorMessage = "Podcast ready packet blocked: script/build_podcast_ready_packet.py was not found."
            podcastReadyPacketGeneratedAt = Date()
            lastMediaAction = "Podcast ready packet blocked: builder script missing"
            updateAgentState()
            return
        }

        let readyManifestURL = URL(fileURLWithPath: outputPath, isDirectory: true).appendingPathComponent("\(basename).json")
        podcastReadyPacketStatus = "generating"
        podcastReadyPacketOutputPath = outputPath
        podcastReadyPacketErrorMessage = ""
        podcastReadyPacketGeneratedAt = Date()
        lastMediaAction = "Generating podcast ready packet: \(basename)"
        updateAgentState()

        Task.detached(priority: .utility) {
            let result = Self.runPodcastReadyPacketBuilder(
                scriptURL: scriptURL,
                manifestPath: manifestPath,
                outputPath: outputPath,
                basename: basename,
                shouldZip: shouldZip
            )

            await MainActor.run {
                switch result {
                case .success:
                    if FileManager.default.fileExists(atPath: readyManifestURL.path) {
                        podcastReadyPacketStatus = "generated"
                        podcastReadyPacketOutputPath = readyManifestURL.path
                        podcastReadyPacketErrorMessage = ""
                        podcastReadyPacketGeneratedAt = Date()
                        lastMediaAction = "Generated podcast ready packet: \(readyManifestURL.path)"
                        updateAgentState()
                    } else {
                        podcastReadyPacketStatus = "failed"
                        podcastReadyPacketOutputPath = outputPath
                        podcastReadyPacketErrorMessage = "Builder finished, but ready manifest was not found at \(readyManifestURL.path)"
                        podcastReadyPacketGeneratedAt = Date()
                        lastMediaAction = "Podcast ready packet failed: manifest missing"
                        updateAgentState()
                    }
                case .failure(let error):
                    podcastReadyPacketStatus = "failed"
                    podcastReadyPacketOutputPath = outputPath
                    podcastReadyPacketErrorMessage = error.localizedDescription
                    podcastReadyPacketGeneratedAt = Date()
                    lastMediaAction = "Podcast ready packet failed: \(error.localizedDescription)"
                    updateAgentState()
                }
            }
        }
    }

    private func generatePodcastReadyPacketForCurrentManifest() {
        let manifestPath = podcastPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !manifestPath.isEmpty else {
            podcastReadyPacketStatus = "blocked"
            podcastReadyPacketOutputPath = ""
            podcastReadyPacketErrorMessage = "Podcast ready packet blocked: generate a podcast manifest first."
            podcastReadyPacketGeneratedAt = Date()
            lastMediaAction = "Podcast ready packet blocked: no manifest"
            updateAgentState()
            return
        }

        let manifestURL = URL(fileURLWithPath: manifestPath)
        let parentFolder = manifestURL.deletingLastPathComponent().deletingLastPathComponent()
        let rawBase = manifestURL.deletingPathExtension().lastPathComponent
            .replacingOccurrences(of: "-podcast-manifest", with: "-podcast-ready")
            .replacingOccurrences(of: "-manifest", with: "-ready")
        let basename = sanitizedExportBasename(rawBase.isEmpty ? "podcast-ready" : rawBase)
        let outputURL = parentFolder.appendingPathComponent(basename, isDirectory: true)
        generatePodcastReadyPacketFromAgent(values: [
            "manifest_path": manifestPath,
            "output": outputURL.path,
            "basename": basename,
            "zip": "1"
        ])
    }

    private func generatePodcastReadyPacketForFullRelease(
        manifestURL: URL,
        outputFolder: URL,
        basename: String
    ) -> Bool {
        guard FileManager.default.fileExists(atPath: manifestURL.path) else {
            podcastReadyPacketStatus = "failed"
            podcastReadyPacketOutputPath = outputFolder.path
            podcastReadyPacketErrorMessage = "Podcast ready packet blocked: manifest missing at \(manifestURL.path)"
            podcastReadyPacketGeneratedAt = Date()
            lastMediaAction = "Podcast ready packet blocked: manifest missing"
            updateAgentState()
            return false
        }
        guard let scriptURL = podcastReadyPacketBuilderURL() else {
            podcastReadyPacketStatus = "failed"
            podcastReadyPacketOutputPath = outputFolder.path
            podcastReadyPacketErrorMessage = "Podcast ready packet blocked: script/build_podcast_ready_packet.py was not found."
            podcastReadyPacketGeneratedAt = Date()
            lastMediaAction = "Podcast ready packet blocked: builder script missing"
            updateAgentState()
            return false
        }

        let safeBase = sanitizedExportBasename(basename)
        let readyManifestURL = outputFolder.appendingPathComponent("\(safeBase).json")
        podcastReadyPacketStatus = "generating"
        podcastReadyPacketOutputPath = outputFolder.path
        podcastReadyPacketErrorMessage = ""
        podcastReadyPacketGeneratedAt = Date()
        updateAgentState()

        let result = Self.runPodcastReadyPacketBuilder(
            scriptURL: scriptURL,
            manifestPath: manifestURL.path,
            outputPath: outputFolder.path,
            basename: safeBase,
            shouldZip: true
        )
        switch result {
        case .success:
            guard FileManager.default.fileExists(atPath: readyManifestURL.path) else {
                podcastReadyPacketStatus = "failed"
                podcastReadyPacketOutputPath = outputFolder.path
                podcastReadyPacketErrorMessage = "Podcast ready builder finished, but ready manifest was not found at \(readyManifestURL.path)"
                podcastReadyPacketGeneratedAt = Date()
                lastMediaAction = "Podcast ready packet failed: manifest missing"
                updateAgentState()
                return false
            }
            podcastReadyPacketStatus = "generated"
            podcastReadyPacketOutputPath = readyManifestURL.path
            podcastReadyPacketErrorMessage = ""
            podcastReadyPacketGeneratedAt = Date()
            lastMediaAction = "Generated podcast ready packet: \(readyManifestURL.lastPathComponent)"
            updateAgentState()
            return true
        case .failure(let error):
            podcastReadyPacketStatus = "failed"
            podcastReadyPacketOutputPath = outputFolder.path
            podcastReadyPacketErrorMessage = error.localizedDescription
            podcastReadyPacketGeneratedAt = Date()
            lastMediaAction = "Podcast ready packet failed: \(error.localizedDescription)"
            updateAgentState()
            return false
        }
    }

    private func podcastReadyPacketBuilderURL() -> URL? {
        let fileManager = FileManager.default
        let sourceRoot = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .path
        let roots = [
            ProcessInfo.processInfo.environment["QUIPSLY_STUDIO_ROOT"],
            fileManager.currentDirectoryPath,
            Bundle.main.resourceURL?.path,
            sourceRoot
        ]
        .compactMap { raw -> String? in
            let trimmed = (raw ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
            return trimmed.isEmpty ? nil : trimmed
        }

        for root in roots {
            let candidate = URL(fileURLWithPath: root)
                .appendingPathComponent("script")
                .appendingPathComponent("build_podcast_ready_packet.py")
            if fileManager.fileExists(atPath: candidate.path) {
                return candidate
            }
        }
        return nil
    }

    nonisolated private static func runPodcastReadyPacketBuilder(
        scriptURL: URL,
        manifestPath: String,
        outputPath: String,
        basename: String,
        shouldZip: Bool
    ) -> Result<String, Error> {
        do {
            let process = Process()
            process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
            var arguments = [
                "python3",
                scriptURL.path,
                manifestPath,
                "--output",
                outputPath,
                "--basename",
                basename
            ]
            if shouldZip {
                arguments.append("--zip")
            }
            process.arguments = arguments
            let stdout = Pipe()
            let stderr = Pipe()
            process.standardOutput = stdout
            process.standardError = stderr
            try process.run()
            process.waitUntilExit()
            let output = String(data: stdout.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
            let errorOutput = String(data: stderr.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
            guard process.terminationStatus == 0 else {
                throw NSError(
                    domain: "QuipslyPodcastReadyPacket",
                    code: Int(process.terminationStatus),
                    userInfo: [NSLocalizedDescriptionKey: errorOutput.isEmpty ? "Builder exited with status \(process.terminationStatus)." : errorOutput]
                )
            }
            return .success(output)
        } catch {
            return .failure(error)
        }
    }

    private func selectSocialMasterQueueCandidate(rank: String?) {
        let trimmedRank = (rank ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedRank.isEmpty else {
            lastMediaAction = "Social master queue select blocked: missing rank"
            updateAgentState()
            return
        }
        guard socialMasterQueueCandidatePreview.contains(where: { ($0["rank"] ?? "") == trimmedRank }) else {
            lastMediaAction = "Social master queue select blocked: rank \(trimmedRank) not loaded"
            updateAgentState()
            return
        }

        selectedSocialMasterQueueRank = trimmedRank
        socialMasterReceiptCapturePlatform = socialMasterQueueSelectedPlatforms().first ?? socialMasterReceiptCapturePlatform
        socialMasterReceiptCaptureURL = ""
        socialMasterReceiptCaptureProviderId = ""
        lastMediaAction = "Selected social master candidate #\(trimmedRank)"
        updateAgentState()
    }

