    private func socialMasterQueueSelectedPlatformCopyPreview(maxCharacters: Int) -> String {
        let path = socialMasterQueueSelectedPath("platformCopyPath")
        guard !path.isEmpty else {
            return "No platform-copy file is attached yet."
        }

        do {
            let text = try String(contentsOfFile: path, encoding: .utf8)
                .trimmingCharacters(in: .whitespacesAndNewlines)
            guard !text.isEmpty else {
                return "Platform-copy file is empty."
            }
            if text.count <= maxCharacters {
                return text
            }
            return "\(String(text.prefix(maxCharacters)))..."
        } catch {
            return "Could not read platform-copy file: \(error.localizedDescription)"
        }
    }

    private func handleSocialMasterQueueArtifactCommand(action: String?, key: String?) {
        let normalizedAction = (action ?? "").trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let normalizedKey = (key ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let artifactKey = normalizedKey.isEmpty ? "clipPath" : normalizedKey
        let label = socialMasterQueueArtifactLabel(for: artifactKey)

        switch normalizedAction {
        case "open":
            openSocialMasterQueueCandidateArtifact(key: artifactKey, label: label)
        case "reveal":
            revealSocialMasterQueueCandidateArtifact(key: artifactKey, label: label)
        case "copy_handoff":
            copySocialMasterQueueCandidateSummary()
        case "copy_platform_copy":
            copySocialMasterQueueCandidatePlatformCopy()
        default:
            lastMediaAction = "Social candidate artifact action blocked: \(normalizedAction.isEmpty ? "missing action" : normalizedAction)"
            updateAgentState()
        }
    }

    private func socialMasterQueueArtifactLabel(for key: String) -> String {
        switch key {
        case "clipPath":
            return "clip"
        case "thumbnailPath":
            return "thumbnail"
        case "captionSrtPath":
            return "captions"
        case "platformCopyPath":
            return "platform copy"
        default:
            return key
        }
    }

    private func socialMasterQueueSelectedPlatforms() -> [String] {
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            return ["YouTube Shorts", "Instagram", "Facebook", "LinkedIn"]
        }
        let raw = (candidate["platforms"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let values = raw
            .split(separator: ",")
            .map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        return values.isEmpty ? ["YouTube Shorts", "Instagram", "Facebook", "LinkedIn"] : values
    }

    private func socialMasterQueueSelectedReceiptId(platform: String? = nil) -> String {
        guard let candidate = selectedSocialMasterQueueCandidate() else { return "" }
        let selectedPlatform = (platform ?? socialMasterReceiptCapturePlatform).trimmingCharacters(in: .whitespacesAndNewlines)
        switch selectedPlatform.lowercased() {
        case "youtube shorts", "youtube", "shorts":
            return candidate["youtubeShortsReceiptId"] ?? ""
        case "instagram", "instagram reels", "reels":
            return candidate["instagramReceiptId"] ?? ""
        case "facebook", "facebook reels":
            return candidate["facebookReceiptId"] ?? ""
        case "linkedin", "linked in":
            return candidate["linkedinReceiptId"] ?? ""
        default:
            return ""
        }
    }

    private func captureSocialMasterQueueReceiptForSelectedCandidate() {
        captureSocialMasterQueueReceiptFromAgent(values: [
            "rank": selectedSocialMasterQueueRank,
            "platform": socialMasterReceiptCapturePlatform,
            "status": socialMasterReceiptCaptureStatus,
            "public_url": socialMasterReceiptCaptureURL,
            "provider_receipt_id": socialMasterReceiptCaptureProviderId,
            "notes": "Manual receipt captured from the selected social master queue candidate."
        ])
    }

    private func captureSocialMasterQueueReceiptFromAgent(values: [String: String]) {
        if let rank = values["rank"], !rank.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            selectedSocialMasterQueueRank = rank.trimmingCharacters(in: .whitespacesAndNewlines)
        }
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            lastMediaAction = "Social master receipt capture blocked: no candidate selected"
            updateAgentState()
            return
        }
        let platform = (values["platform"] ?? socialMasterReceiptCapturePlatform)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let receiptId = socialMasterQueueSelectedReceiptId(platform: platform)
        guard !receiptId.isEmpty else {
            lastMediaAction = "Social master receipt capture blocked: selected candidate has no \(platform.isEmpty ? "platform" : platform) receipt id"
            updateAgentState()
            return
        }
        let publicURL = (values["public_url"] ?? values["url"] ?? values["publicURL"] ?? socialMasterReceiptCaptureURL)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !publicURL.isEmpty else {
            lastMediaAction = "Social master receipt capture blocked: paste a public or scheduled URL first"
            updateAgentState()
            return
        }
        let status = (values["status"] ?? socialMasterReceiptCaptureStatus)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let providerId = (values["provider_receipt_id"] ?? values["provider_id"] ?? socialMasterReceiptCaptureProviderId)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        var updateValues: [String: String] = [
            "id": receiptId,
            "status": status.isEmpty ? "published" : status,
            "upload_job_status": uploadJobStatusForManualReceipt(status.isEmpty ? "published" : status),
            "public_url": publicURL,
            "receipt_json": stableJSONString([
                "model": "quipsly-social-master-queue-receipt",
                "version": "2026-06-17.social-master-receipt.v1",
                "candidateRank": candidate["rank"] ?? "",
                "sourcePack": candidate["sourcePack"] ?? "",
                "sourceManifest": candidate["sourceManifest"] ?? "",
                "platform": platform,
                "title": candidate["title"] ?? "",
                "clipPath": candidate["clipPath"] ?? "",
                "platformCopyPath": candidate["platformCopyPath"] ?? "",
                "captionSrtPath": candidate["captionSrtPath"] ?? "",
                "publicURL": publicURL,
                "status": status.isEmpty ? "published" : status,
                "capturedAt": ISO8601DateFormatter().string(from: Date()),
                "captureMethod": "quipsly-studio-social-master-queue"
            ]),
            "notes": values["notes"] ?? "Manual receipt captured from the social master queue."
        ]
        if !providerId.isEmpty {
            updateValues["provider_receipt_id"] = providerId
        }
        updatePublishReceiptFromAgent(values: updateValues)
        socialMasterReceiptCaptureURL = ""
        socialMasterReceiptCaptureProviderId = ""
    }

