    private func mediaReadinessSummary() -> MediaReadinessSummary {
        guard let sequence = projectStore.activeSequence else {
            return MediaReadinessSummary(
                hasSequence: false,
                readyCount: 0,
                heldCount: 0,
                missingCount: 0,
                blockingCount: 0,
                videoProxyReadyCount: 0,
                videoBlockedCount: 0,
                audioReadyCount: 0,
                audioBlockedCount: 0,
                showDecisionCount: 0,
                skipDecisionCount: 0,
                rawVaultCount: 0,
                storageAccessNeededCount: 0,
                proxyBlockedCount: 0,
                detail: "Load an episode or import media to see source readiness."
            )
        }

        var ready = 0
        var held = 0
        var missing = 0
        var videoProxyReady = 0
        var videoBlocked = 0
        var audioReady = 0
        var audioBlocked = 0
        var showDecisions = 0
        var skipDecisions = 0
        var rawVaulted = 0
        var storageAccessNeeded = 0
        var proxyBlocked = 0

        for lane in sequence.lanes {
            let readiness = sourceReadiness(for: lane)
            if readiness.needsStorageAccess {
                storageAccessNeeded += 1
            }
            if readiness.isReady {
                ready += 1
            } else if readiness.label == "Missing source" {
                missing += 1
            } else {
                held += 1
            }

            if isSupportOnlyLane(lane) {
                if readiness.isReady {
                    audioReady += 1
                } else {
                    audioBlocked += 1
                }
            } else if readiness.label == "Proxy ready" {
                videoProxyReady += 1
            } else {
                videoBlocked += 1
            }

            if lane.metadata?.vaultRawPath?.isEmpty == false {
                rawVaulted += 1
            }

            if readiness.label.lowercased().contains("proxy blocked") {
                proxyBlocked += 1
            }

            showDecisions += lane.tags.filter { $0.type == .active }.count
            skipDecisions += lane.tags.filter { $0.type == .cut }.count
        }

        let blocking = held + missing
        let detail: String
        if sequence.lanes.isEmpty {
            detail = "No lanes yet. Import media or load a Premiere rescue packet."
        } else if rawVaulted > 0 {
            detail = "\(rawVaulted) lane(s) still point at raw vault media. Keep originals external and edit from proxies."
        } else if proxyBlocked > 0 {
            detail = "\(proxyBlocked) proxy job(s) are blocked. Grant external storage access or relink readable originals, then retry pending proxies."
        } else if storageAccessNeeded > 0 && blocking == 0 && videoBlocked == 0 {
            detail = "All \(videoProxyReady) video lane(s) and \(audioReady) audio/context lane(s) are proxy-backed for preview and proxy export. Grant storage access only for relink, waveform-from-originals, or raw-source operations."
        } else if blocking == 0 && videoBlocked == 0 {
            detail = "All \(videoProxyReady) video lane(s) and \(audioReady) audio/context lane(s) are proxy-backed for preview, and originals remain whole."
        } else if videoBlocked > 0 {
            detail = "\(videoBlocked) video lane(s) need generated proxies before editor playback. Do not fall back to raw originals."
        } else if missing > 0 {
            detail = "\(missing) lane(s) are missing source files. Relink originals, then generate proxies for preview."
        } else if audioBlocked > 0 {
            detail = "\(audioBlocked) audio/context lane(s) need local audio proxies before production editing, waveform work, or sync review."
        } else {
            detail = "\(blocking) lane(s) are held. Local preview proxies are required before production editing."
        }

        return MediaReadinessSummary(
            hasSequence: true,
            readyCount: ready,
            heldCount: held,
            missingCount: missing,
            blockingCount: blocking,
            videoProxyReadyCount: videoProxyReady,
            videoBlockedCount: videoBlocked,
            audioReadyCount: audioReady,
            audioBlockedCount: audioBlocked,
            showDecisionCount: showDecisions,
            skipDecisionCount: skipDecisions,
            rawVaultCount: rawVaulted,
            storageAccessNeededCount: storageAccessNeeded,
            proxyBlockedCount: proxyBlocked,
            detail: detail
        )
    }
    
    private func selectedDecision() -> (lane: VideoLane, tag: VideoTag)? {
        guard let laneId = selectedLaneId,
              let tagId = selectedTagId,
              let sequence = projectStore.activeSequence,
              let lane = sequence.lanes.first(where: { $0.id == laneId }),
              let tag = lane.tags.first(where: { $0.id == tagId }) else {
            return nil
        }
        
        return (lane, tag)
    }

    private func addSelectedDecisionToShortQueue(title requestedTitle: String?) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Short queue blocked: no active sequence"
            updateAgentState()
            return
        }

        guard let selected = selectedDecision() else {
            lastMediaAction = "Short queue blocked: select a SHOW decision first"
            updateAgentState()
            return
        }

        guard selected.tag.type == .active else {
            lastMediaAction = "Short queue blocked: selected decision is not a SHOW region"
            updateAgentState()
            return
        }

        let title = requestedTitle?.trimmingCharacters(in: .whitespacesAndNewlines)
        let clipTitle = (title?.isEmpty == false ? title! : defaultShortClipTitle(for: selected.lane, tag: selected.tag))
        let candidate = ShortClipCandidate(
            title: clipTitle,
            startTime: selected.tag.startTime,
            duration: selected.tag.duration,
            sourceLaneId: selected.lane.id,
            sourceTagId: selected.tag.id,
            notes: "Queued from selected SHOW decision over whole source lanes."
        )

        sequence.shortClipQueue.append(candidate)
        selectedShortClipId = candidate.id
        selectedLaneId = selected.lane.id
        selectedTagId = selected.tag.id
        playbackEngine.playbackFormat = .vertical9x16
        playbackEngine.scrub(to: sequenceStartTime(for: candidate, in: sequence))
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Queue Short Clip")
        lastMediaAction = "Queued short clip: \(clipTitle)"
        scheduleAutosave(reason: "queued short clip")
        updateAgentState()
    }

    private func addSequenceRangeToShortQueue(title requestedTitle: String?, start rawStart: Double?, end rawEnd: Double?) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Short range queue blocked: no active sequence"
            updateAgentState()
            return
        }

        let minimumDuration = 0.15
        let maxSequenceEnd = max(minimumDuration, sequence.duration)
        let requestedStart = rawStart ?? playbackEngine.playhead
        let requestedEnd = rawEnd ?? min(maxSequenceEnd, requestedStart + 30)
        let start = min(max(0, requestedStart), max(0, maxSequenceEnd - minimumDuration))
        let end = max(start + minimumDuration, min(maxSequenceEnd, requestedEnd))

        guard end > start else {
            lastMediaAction = "Short range queue blocked: invalid range"
            updateAgentState()
            return
        }

        let title = requestedTitle?.trimmingCharacters(in: .whitespacesAndNewlines)
        let clipTitle = title?.isEmpty == false
            ? title!
            : String(format: "Short from episode @ %.1fs", start)
        let candidate = ShortClipCandidate(
            title: clipTitle,
            startTime: start,
            duration: end - start,
            sourceLaneId: nil,
            sourceTagId: nil,
            notes: "Queued from explicit episode sequence range. Sequence time is the source of truth for this short packet."
        )

        sequence.shortClipQueue.append(candidate)
        selectedShortClipId = candidate.id
        selectedLaneId = nil
        selectedTagId = nil
        playbackEngine.playbackFormat = .vertical9x16
        playbackEngine.scrub(to: start)
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Queue Sequence Short Clip")
        lastMediaAction = String(format: "Queued sequence short %.2fs -> %.2fs: %@", start, end, clipTitle)
        scheduleAutosave(reason: "queued sequence short clip")
        updateAgentState()
    }

    private func removeShortClipCandidate(id rawId: String) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Short queue remove blocked: no active sequence"
            updateAgentState()
            return
        }

        guard let clipId = UUID(uuidString: rawId) else {
            lastMediaAction = "Short queue remove blocked: invalid id \(rawId)"
            updateAgentState()
            return
        }

        let before = sequence.shortClipQueue.count
        sequence.shortClipQueue.removeAll { $0.id == clipId }
        guard sequence.shortClipQueue.count != before else {
            lastMediaAction = "Short queue remove blocked: clip not found"
            updateAgentState()
            return
        }
        if selectedShortClipId == clipId {
            selectedShortClipId = nil
        }

        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Remove Short Clip")
        lastMediaAction = "Removed short clip candidate"
        scheduleAutosave(reason: "removed short clip")
        updateAgentState()
    }

    private func selectShortClipCandidate(_ clip: ShortClipCandidate) {
        selectedShortClipId = clip.id
        playbackEngine.playbackFormat = .vertical9x16

        if let laneId = clip.sourceLaneId {
            selectedLaneId = laneId
        }
        if let tagId = clip.sourceTagId {
            selectedTagId = tagId
        }

        if let sequence = projectStore.activeSequence {
            playbackEngine.scrub(to: sequenceStartTime(for: clip, in: sequence))
        }
        rebuildPlayer()
        lastMediaAction = "Opened short packet: \(clip.title)"
        requestTimelineFocus(reason: "Focused decision timeline for short packet")
        updateAgentState()
    }

    private func selectedShortClipValue() -> ShortClipCandidate? {
        guard let selectedShortClipId,
              let sequence = projectStore.activeSequence else {
            return nil
        }
        return sequence.shortClipQueue.first { $0.id == selectedShortClipId }
    }

    private func updateSelectedShortClip(_ mutate: (inout ShortClipCandidate) -> Void) {
        guard let selectedShortClipId,
              var sequence = projectStore.activeSequence,
              let index = sequence.shortClipQueue.firstIndex(where: { $0.id == selectedShortClipId }) else {
            lastMediaAction = "Short update blocked: no selected short packet"
            updateAgentState()
            return
        }

        mutate(&sequence.shortClipQueue[index])
        sequence.shortClipQueue[index].updatedAt = Date()
        if sequence.shortClipQueue[index].destinationPresets.isEmpty {
            let title = sequence.shortClipQueue[index].title
            sequence.shortClipQueue[index].destinationPresets = sequence.shortClipQueue[index].destinations.map {
                ShortDestinationPreset(platform: $0, title: title)
            }
        }

        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Update Short Packet")
        lastMediaAction = "Updated short packet: \(sequence.shortClipQueue[index].title)"
        scheduleAutosave(reason: "updated short packet")
        updateAgentState()
    }

    private func updateSelectedShortClipField(field rawField: String?, value: String?) {
        let field = (rawField ?? "").lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        let newValue = value ?? ""
        updateSelectedShortClip { clip in
            switch field {
            case "title":
                clip.title = newValue
            case "hook", "hooktext", "hook_text":
                clip.hookText = newValue
            case "caption", "captiondraft", "caption_draft":
                clip.captionDraft = newValue
            case "overlay", "primaryoverlay", "primary_overlay", "primaryoverlaytext", "primary_overlay_text":
                clip.primaryOverlayText = newValue
            case "notes":
                clip.notes = newValue
            case "publishnotes", "publish_notes":
                clip.publishNotes = newValue
            case "review", "reviewstatus", "review_status":
                clip.reviewStatus = newValue
            case "export", "exportstatus", "export_status":
                clip.exportStatus = newValue
            case "status":
                clip.status = newValue
            default:
                clip.notes = clip.notes.isEmpty
                    ? "Ignored unknown short field: \(field)"
                    : "\(clip.notes)\nIgnored unknown short field: \(field)"
            }
        }
    }

    private func previewSelectedShortClip(play: Bool) {
        guard let clip = selectedShortClipValue(),
              let sequence = projectStore.activeSequence else {
            lastMediaAction = "Short preview blocked: no selected short packet"
            updateAgentState()
            return
        }

        let start = sequenceStartTime(for: clip, in: sequence)
        let end = start + max(0.15, clip.duration)
        playbackEngine.playbackMode = .playEdit
        playbackEngine.playbackFormat = .vertical9x16
        playbackEngine.updateValidRanges(for: sequence)
        rebuildPlayer()
        playbackEngine.scrub(to: start)
        if play {
            shortPreviewClipId = clip.id
            shortPreviewStopAt = end
            playbackEngine.play()
        } else {
            shortPreviewClipId = nil
            shortPreviewStopAt = nil
            playbackEngine.pause()
        }
        lastMediaAction = play
            ? String(format: "Previewing short packet from %.2fs to %.2fs: %@", start, end, clip.title)
            : String(format: "Cued short packet at %.2fs: %@", start, clip.title)
        updateAgentState()
    }

    private func enforceSelectedShortPreviewStop(at playhead: Double) {
        guard let stopAt = shortPreviewStopAt,
              playbackEngine.isPlaying,
              playhead >= stopAt else {
            return
        }

        let stoppedClipId = shortPreviewClipId
        shortPreviewClipId = nil
        shortPreviewStopAt = nil
        playbackEngine.pause()
        playbackEngine.scrub(to: stopAt)
        if let stoppedClipId,
           let sequence = projectStore.activeSequence,
           let clip = sequence.shortClipQueue.first(where: { $0.id == stoppedClipId }) {
            lastMediaAction = String(format: "Short preview stopped at out point %.2fs: %@", stopAt, clip.title)
        } else {
            lastMediaAction = String(format: "Short preview stopped at out point %.2fs", stopAt)
        }
        updateAgentState()
    }

    private func setSelectedShortBoundaryFromPlayhead(_ boundary: String) {
        adjustSelectedShortBoundary(boundary, targetSequenceTime: playbackEngine.playhead, delta: nil)
    }

    private func nudgeSelectedShortBoundary(_ boundary: String, by delta: Double) {
        adjustSelectedShortBoundary(boundary, targetSequenceTime: nil, delta: delta)
    }

    private func adjustSelectedShortBoundary(_ boundary: String, targetSequenceTime: Double?, delta: Double?) {
        guard let selectedShortClipId,
              var sequence = projectStore.activeSequence,
              let index = sequence.shortClipQueue.firstIndex(where: { $0.id == selectedShortClipId }) else {
            lastMediaAction = "Short range update blocked: no selected short packet"
            updateAgentState()
            return
        }

        let minimumDuration = 0.15
        var clip = sequence.shortClipQueue[index]
        let sourceOffset = sourceOffset(for: clip, in: sequence)
        var start = sequenceStartTime(for: clip, in: sequence)
        var end = start + max(minimumDuration, clip.duration)
        let normalizedBoundary = boundary.lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        let maxSequenceEnd = max(minimumDuration, sequence.duration)

        switch normalizedBoundary {
        case "start", "in":
            let requested = targetSequenceTime ?? (start + (delta ?? 0))
            start = min(max(0, requested), max(0, end - minimumDuration))
        case "end", "out":
            let requested = targetSequenceTime ?? (end + (delta ?? 0))
            end = max(start + minimumDuration, min(maxSequenceEnd, requested))
        default:
            lastMediaAction = "Short range update blocked: unknown boundary \(boundary)"
            updateAgentState()
            return
        }

        if end > maxSequenceEnd {
            end = maxSequenceEnd
            start = min(start, max(0, end - minimumDuration))
        }

        clip.startTime = max(0, start - sourceOffset)
        clip.duration = max(minimumDuration, end - start)
        clip.exportStatus = clip.exportStatus == "exported" ? "not-exported" : clip.exportStatus
        clip.updatedAt = Date()
        sequence.shortClipQueue[index] = clip
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Adjust Short Range")
        scheduleAutosave(reason: "adjusted short range")
        playbackEngine.playbackFormat = .vertical9x16
        playbackEngine.scrub(to: start)
        lastMediaAction = String(format: "Adjusted short %@ to %.2fs -> %.2fs", normalizedBoundary, start, end)
        updateAgentState()
    }

    private func exportSelectedShortClipForAgent(directoryPath: String?, basename: String?) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Short export blocked: no active sequence"
            blockExportStatus(kind: "selected-short-9x16", reason: "No active sequence loaded.")
            updateAgentState()
            return
        }

        guard let selectedShortClipId,
              let index = sequence.shortClipQueue.firstIndex(where: { $0.id == selectedShortClipId }) else {
            lastMediaAction = "Short export blocked: no selected short packet"
            blockExportStatus(kind: "selected-short-9x16", reason: "Select a short packet before exporting.")
            updateAgentState()
            return
        }

        let readiness = mediaReadinessSummary()
        guard readiness.isProductionReady else {
            lastMediaAction = "Short export blocked: \(readiness.detail)"
            blockExportStatus(kind: "selected-short-9x16", reason: readiness.detail)
            updateAgentState()
            return
        }

        let clip = sequence.shortClipQueue[index]
        let sequenceStart = sequenceStartTime(for: clip, in: sequence)
        guard clip.duration.isFinite, clip.duration > 0 else {
            lastMediaAction = "Short export blocked: selected short has no duration"
            blockExportStatus(kind: "selected-short-9x16", reason: "Selected short packet has no positive duration.")
            updateAgentState()
            return
        }

        let outputDirectory: URL
        if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            outputDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
        } else {
            outputDirectory = defaultLocalExportDirectory()
                .appendingPathComponent("shorts", isDirectory: true)
        }

        let requestedBasename = basename?.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanBasename = sanitizedExportBasename(
            requestedBasename?.isEmpty == false
            ? requestedBasename!
            : "\(normalizedActiveSessionName())-\(clip.title)"
        )
        let outputURL = outputDirectory.appendingPathComponent("\(cleanBasename)-9x16-short.mp4")

        sequence.shortClipQueue[index].exportStatus = "exporting"
        sequence.shortClipQueue[index].publishNotes = appendLine(
            "Export started: \(outputURL.path)",
            to: sequence.shortClipQueue[index].publishNotes
        )
        sequence.shortClipQueue[index].updatedAt = Date()
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Export Short Clip")
        scheduleAutosave(reason: "started short export")

        beginExportStatus(kind: "selected-short-9x16", outputURLs: [outputURL], proofSeconds: clip.duration)
        playbackEngine.playbackFormat = .vertical9x16
        lastMediaAction = "Short export started: \(clip.title)"
        updateAgentState()

        Task {
            do {
                try await ExportEngine.shared.export(
                    sequence: sequence,
                    to: outputURL,
                    format: .vertical9x16,
                    allowExternalOriginalMedia: false,
                    allowedOriginalMediaRootPath: nil,
                    sequenceStartSeconds: sequenceStart,
                    sequenceDurationSeconds: clip.duration,
                    primaryOverlayText: clip.primaryOverlayText,
                    captionText: clip.captionDraft
                )

                await MainActor.run {
                    markShortClipExportResult(
                        id: selectedShortClipId,
                        status: "exported",
                        note: shortExportSuccessNote(outputURL: outputURL, clip: clip)
                    )
                    completeExportStatus(outputURLs: [outputURL])
                    lastMediaAction = "Short export completed: \(outputURL.path)"
                    updateAgentState()
                }
            } catch {
                await MainActor.run {
                    markShortClipExportResult(
                        id: selectedShortClipId,
                        status: "export-failed",
                        note: "Export failed: \(error.localizedDescription)"
                    )
                    failExportStatus(error: error)
                    lastMediaAction = "Short export failed: \(error.localizedDescription)"
                    errorMessage = lastMediaAction
                    showErrorAlert = true
                    updateAgentState()
                }
            }
        }
    }

    private func exportQueuedShortClipsForAgent(directoryPath: String?, basename: String?) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Batch short export blocked: no active sequence"
            blockExportStatus(kind: "queued-shorts-9x16", reason: "No active sequence loaded.")
            updateAgentState()
            return
        }

        let queuedClips = sequence.shortClipQueue
        guard !queuedClips.isEmpty else {
            lastMediaAction = "Batch short export blocked: no queued short packets"
            blockExportStatus(kind: "queued-shorts-9x16", reason: "Queue at least one short packet before batch export.")
            updateAgentState()
            return
        }

        let readiness = mediaReadinessSummary()
        guard readiness.isProductionReady else {
            lastMediaAction = "Batch short export blocked: \(readiness.detail)"
            blockExportStatus(kind: "queued-shorts-9x16", reason: readiness.detail)
            updateAgentState()
            return
        }

        let outputDirectory: URL
        if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            outputDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
        } else {
            outputDirectory = defaultLocalExportDirectory()
                .appendingPathComponent("shorts", isDirectory: true)
        }

        let requestedBasename = basename?.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanBasename = sanitizedExportBasename(
            requestedBasename?.isEmpty == false
            ? requestedBasename!
            : "\(normalizedActiveSessionName())-shorts"
        )

        struct QueuedShortExportJob {
            let clip: ShortClipCandidate
            let outputURL: URL
            let sequenceStart: Double
        }

        let jobs: [QueuedShortExportJob] = queuedClips.enumerated().compactMap { index, clip in
            guard clip.duration.isFinite, clip.duration > 0 else {
                return nil
            }
            let titleSlug = sanitizedExportBasename(clip.title.isEmpty ? "short" : clip.title)
            let filePrefix = String(format: "%@-%02d-%@", cleanBasename, index + 1, titleSlug)
            return QueuedShortExportJob(
                clip: clip,
                outputURL: outputDirectory.appendingPathComponent("\(filePrefix)-9x16-short.mp4"),
                sequenceStart: sequenceStartTime(for: clip, in: sequence)
            )
        }

        guard jobs.count == queuedClips.count else {
            let invalidCount = queuedClips.count - jobs.count
            lastMediaAction = "Batch short export blocked: \(invalidCount) short packet(s) have invalid duration"
            blockExportStatus(kind: "queued-shorts-9x16", reason: "Every queued short packet needs a positive duration before batch export.")
            updateAgentState()
            return
        }

        let outputURLs = jobs.map(\.outputURL)
        let outputById = Dictionary(uniqueKeysWithValues: jobs.map { ($0.clip.id, $0.outputURL.path) })
        for index in sequence.shortClipQueue.indices {
            let clipId = sequence.shortClipQueue[index].id
            sequence.shortClipQueue[index].exportStatus = "queued-for-export"
            sequence.shortClipQueue[index].publishNotes = appendLine(
                "Batch export queued: \(outputById[clipId] ?? outputDirectory.path)",
                to: sequence.shortClipQueue[index].publishNotes
            )
            sequence.shortClipQueue[index].updatedAt = Date()
        }
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Queue Batch Short Export")
        scheduleAutosave(reason: "queued batch short export")

        let proofSeconds = jobs.reduce(0) { $0 + max(0, $1.clip.duration) }
        beginExportStatus(kind: "queued-shorts-9x16", outputURLs: outputURLs, proofSeconds: proofSeconds)
        playbackEngine.playbackFormat = .vertical9x16
        lastMediaAction = "Batch short export started: \(jobs.count) queued packet(s)"
        updateAgentState()

        Task {
            var completedURLs: [URL] = []
            do {
                for job in jobs {
                    await MainActor.run {
                        markShortClipExportResult(
                            id: job.clip.id,
                            status: "exporting",
                            note: "Batch export started: \(job.outputURL.path)"
                        )
                    }

                    try await ExportEngine.shared.export(
                        sequence: sequence,
                        to: job.outputURL,
                        format: .vertical9x16,
                        allowExternalOriginalMedia: false,
                        allowedOriginalMediaRootPath: nil,
                        sequenceStartSeconds: job.sequenceStart,
                        sequenceDurationSeconds: job.clip.duration,
                        primaryOverlayText: job.clip.primaryOverlayText,
                        captionText: job.clip.captionDraft
                    )

                    completedURLs.append(job.outputURL)
                    await MainActor.run {
                        markShortClipExportResult(
                            id: job.clip.id,
                            status: "exported",
                            note: shortExportSuccessNote(outputURL: job.outputURL, clip: job.clip)
                        )
                    }
                }

                await MainActor.run {
                    completeExportStatus(outputURLs: completedURLs)
                    lastMediaAction = "Batch short export completed: \(completedURLs.count) file(s)"
                    updateAgentState()
                }
            } catch {
                await MainActor.run {
                    if let failedJob = jobs.first(where: { !completedURLs.contains($0.outputURL) }) {
                        markShortClipExportResult(
                            id: failedJob.clip.id,
                            status: "export-failed",
                            note: "Batch export failed: \(error.localizedDescription)"
                        )
                    }
                    failExportStatus(error: error)
                    lastMediaAction = "Batch short export failed after \(completedURLs.count) file(s): \(error.localizedDescription)"
                    errorMessage = lastMediaAction
                    showErrorAlert = true
                    updateAgentState()
                }
            }
        }
    }

    private func selectedShortSequenceRange(_ clip: ShortClipCandidate) -> (start: Double, end: Double, duration: Double)? {
        guard let sequence = projectStore.activeSequence else { return nil }
        let start = sequenceStartTime(for: clip, in: sequence)
        let duration = max(0, clip.duration)
        return (start, start + duration, duration)
    }

    private func sequenceStartTime(for clip: ShortClipCandidate, in sequence: MediaSequence) -> Double {
        max(0, clip.startTime + sourceOffset(for: clip, in: sequence))
    }

    private func sourceOffset(for clip: ShortClipCandidate, in sequence: MediaSequence) -> Double {
        guard let sourceLaneId = clip.sourceLaneId,
              let lane = sequence.lanes.first(where: { $0.id == sourceLaneId }),
              let sourceVideo = lane.sourceVideo else {
            return 0
        }
        return sourceVideo.offset
    }

    private func markShortClipExportResult(id: UUID, status: String, note: String) {
        guard var sequence = projectStore.activeSequence,
              let index = sequence.shortClipQueue.firstIndex(where: { $0.id == id }) else {
            return
        }

        sequence.shortClipQueue[index].exportStatus = status
        sequence.shortClipQueue[index].publishNotes = appendLine(note, to: sequence.shortClipQueue[index].publishNotes)
        sequence.shortClipQueue[index].updatedAt = Date()
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Update Short Export Status")
        scheduleAutosave(reason: "updated short export status")
    }

    private func appendLine(_ line: String, to existing: String) -> String {
        let trimmed = existing.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? line : "\(trimmed)\n\(line)"
    }

    private func lastExportedShortPath(for clip: ShortClipCandidate) -> String? {
        clip.publishNotes
            .components(separatedBy: .newlines)
            .reversed()
            .compactMap { line -> String? in
                let marker = "Exported 9:16 short: "
                guard let range = line.range(of: marker) else { return nil }
                let path = String(line[range.upperBound...]).trimmingCharacters(in: .whitespacesAndNewlines)
                return path.isEmpty ? nil : path
            }
            .first
    }

    private func revealShortExport(path: String) {
        #if os(macOS)
        NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath: path)])
        #endif
        lastMediaAction = "Revealed short export: \(path)"
        updateAgentState()
    }

    private func shortExportSuccessNote(outputURL: URL, clip: ShortClipCandidate) -> String {
        let overlay = clip.primaryOverlayText.trimmingCharacters(in: .whitespacesAndNewlines)
        let caption = clip.captionDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        var lines = ["Exported 9:16 short: \(outputURL.path)"]
        var burnIns: [String] = []
        if !overlay.isEmpty {
            burnIns.append("overlay")
        }
        if !caption.isEmpty {
            burnIns.append("caption")
        }
        if !burnIns.isEmpty {
            lines.append("Text burn-in: \(burnIns.joined(separator: ", "))")
        }
        return lines.joined(separator: "\n")
    }

    private func copyShortExportPath(_ path: String) {
        #if os(macOS)
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(path, forType: .string)
        #endif
        lastMediaAction = "Copied short export path"
        updateAgentState()
    }

    private func applyLeftWorkbenchMode(_ rawMode: String?) {
        let mode = (rawMode ?? "shorts").lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        switch mode {
        case "closed", "close", "hide":
            isInspectorVisible = false
            lastMediaAction = "Closed left workbench"
        case "inspector", "inspect", "framing":
            leftWorkbenchMode = .inspector
            isInspectorVisible = true
            lastMediaAction = "Opened Inspector workbench"
        case "shorts", "short", "short-clips", "clips":
            leftWorkbenchMode = .shorts
            isInspectorVisible = true
            lastMediaAction = "Opened Shorts workbench"
        case "transcript", "transcripts", "caption", "captions", "words":
            leftWorkbenchMode = .transcript
            isInspectorVisible = true
            lastMediaAction = "Opened Transcript workbench"
        default:
            leftWorkbenchMode = .shorts
            isInspectorVisible = true
            lastMediaAction = "Opened Shorts workbench"
        }
        updateAgentState()
    }

