        leftWorkbenchMode = .transcript
        isInspectorVisible = true
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Seed Transcript Spine")
        lastMediaAction = "Seeded transcript spine with \(segments.count) timed demo segment(s)"
        scheduleAutosave(reason: "seeded transcript spine")
        updateAgentState()
    }

