    }

    private func cutSourceLaneWindow(_ laneId: UUID) {
        applySourceWallDecision(laneId: laneId, type: .cut, sequenceDuration: 10)
    }

    private func applySourceWallDecision(laneId: UUID, type: TagType, sequenceDuration requestedDuration: Double) {
        guard let sequence = projectStore.activeSequence,
              sequence.lanes.contains(where: { $0.id == laneId }) else {
            lastMediaAction = "Source-wall decision failed: lane not found"
            updateAgentState()
            return
        }

        let sequenceStart = min(max(0, playbackEngine.playhead), max(0, sequence.duration))
        let decisionMap: [UUID: TagType]
        if type == .active {
            decisionMap = visualDecisionMap(
                in: sequence,
                showLaneIds: [laneId],
                cutOtherVisuals: true
            )
        } else {
            decisionMap = [laneId: .cut]
        }

        applyDecisionWindowMap(
            decisionMap,
            sequenceStart: sequenceStart,
            sequenceDuration: requestedDuration,
            actionName: type == .active ? "Show Source Window" : "Cut Source Window",
            autosaveReason: type == .active ? "source-wall show decision" : "source-wall cut decision",
            mediaActionLabel: type == .active ? "Added SHOW source-wall decision" : "Added CUT source-wall decision"
        )
    }

    private func applyDecisionWindowMap(
        _ decisionsByLaneId: [UUID: TagType],
        sequenceStart requestedSequenceStart: Double,
        sequenceDuration requestedDuration: Double,
        actionName: String,
        autosaveReason: String,
        mediaActionLabel: String
    ) {
        guard var sequence = projectStore.activeSequence else { return }
        let sequenceStart = min(max(0, requestedSequenceStart), max(0, sequence.duration))
        let sequenceEnd = min(max(sequenceStart, sequenceStart + max(0.1, requestedDuration)), max(0, sequence.duration))
        guard sequenceEnd - sequenceStart >= 0.05 else {
            lastMediaAction = "Source-wall decision failed: no room at the current playhead"
            updateAgentState()
            return
        }

        var preferredSelectedDecision: (laneId: UUID, tagId: UUID, type: TagType)? = nil
        var fallbackSelectedDecision: (laneId: UUID, tagId: UUID, type: TagType)? = nil

        func replaceDecisionWindow(laneIndex: Int, with decisionType: TagType) {
            guard sequence.lanes.indices.contains(laneIndex) else { return }
            let lane = sequence.lanes[laneIndex]
            let offset = lane.sourceVideo?.offset ?? 0
            let laneDuration = max(0, lane.sourceVideo?.duration ?? lane.duration)
            guard laneDuration > 0 else { return }

            var replacementTags: [VideoTag] = []
            for tag in lane.tags {
                guard tag.type == .active || tag.type == .cut else {
                    replacementTags.append(tag)
                    continue
                }

                let tagSequenceStart = tag.startTime + offset
                let tagSequenceEnd = tagSequenceStart + tag.duration

                if tagSequenceEnd <= sequenceStart || tagSequenceStart >= sequenceEnd {
                    replacementTags.append(tag)
                    continue
                }

                if tagSequenceStart < sequenceStart {
                    var left = tag
                    left.duration = max(0, sequenceStart - tagSequenceStart)
                    if left.duration >= 0.05 {
                        replacementTags.append(left)
                    }
                }

                if tagSequenceEnd > sequenceEnd {
                    var right = tag
                    right.startTime = max(0, sequenceEnd - offset)
                    right.duration = max(0, tagSequenceEnd - sequenceEnd)
                    if right.duration >= 0.05 {
                        replacementTags.append(right)
                    }
                }
            }

            let localStart = max(0, sequenceStart - offset)
            let localEnd = min(laneDuration, sequenceEnd - offset)
            let localDuration = localEnd - localStart
            guard localDuration >= 0.05 else {
                sequence.lanes[laneIndex].tags = replacementTags.sorted { $0.startTime < $1.startTime }
                return
            }

            let newTag = VideoTag(type: decisionType, startTime: localStart, duration: localDuration)
            replacementTags.append(newTag)
            sequence.lanes[laneIndex].tags = replacementTags.sorted { $0.startTime < $1.startTime }

            let selected = (sequence.lanes[laneIndex].id, newTag.id, decisionType)
            if decisionType == .active {
                if preferredSelectedDecision == nil {
                    preferredSelectedDecision = selected
                }
            } else if fallbackSelectedDecision == nil {
                fallbackSelectedDecision = selected
            }
        }

        for laneIndex in sequence.lanes.indices {
            let lane = sequence.lanes[laneIndex]
            guard let decisionType = decisionsByLaneId[lane.id] else { continue }
            replaceDecisionWindow(laneIndex: laneIndex, with: decisionType)
        }

        projectStore.updateSequence(sequence, undoManager: nil, actionName: actionName)
        if let selectedDecision = preferredSelectedDecision ?? fallbackSelectedDecision {
            selectedLaneId = selectedDecision.laneId
            selectedTagId = selectedDecision.tagId
        }
        playbackEngine.updateValidRanges(for: sequence)
        playbackEngine.seek(to: sequenceStart)
        rebuildPlayer()
        lastMediaAction = String(
            format: "%@ · %.1fs at %.2fs",
            mediaActionLabel,
            sequenceEnd - sequenceStart,
            sequenceStart
        )
        scheduleAutosave(reason: autosaveReason)
        updateAgentState()
    }

    private func seekToSelectedDecision(_ selected: (lane: VideoLane, tag: VideoTag)) {
        let sequenceTime = max(0, (selected.lane.sourceVideo?.offset ?? 0) + selected.tag.startTime)
        playbackEngine.seek(to: sequenceTime)
        lastMediaAction = String(format: "Jumped to selected decision at %.2fs", sequenceTime)
        updateAgentState()
    }

    private func setSelectedLaneRole(_ role: String) {
        guard let laneId = selectedLaneId else {
            return
        }

        assignLaneRole(laneId: laneId.uuidString, role: role)
    }

    private func assignLaneRole(laneId: String, role: String) {
        guard var sequence = projectStore.activeSequence,
              let laneIndex = sequence.lanes.firstIndex(where: { laneMatches($0, laneId: laneId) }) else {
            return
        }

        var metadata = sequence.lanes[laneIndex].metadata ?? VideoLaneMetadata(
            mediaKind: role.contains("audio") ? "audio" : "video",
            role: role,
            sourcePath: sequence.lanes[laneIndex].sourceVideo?.mediaURL.path,
            originalPath: sequence.lanes[laneIndex].sourceVideo?.mediaURL.path,
            declaredExists: sequence.lanes[laneIndex].metadata?.declaredExists,
            sourceLabel: sequence.lanes[laneIndex].sourceVideo?.mediaURL.lastPathComponent
        )

        metadata.role = role
        if role.contains("audio") {
            metadata.mediaKind = "audio"
        } else {
            metadata.mediaKind = "video"
        }

        sequence.lanes[laneIndex].metadata = metadata
        sequence.lanes[laneIndex].name = laneName(for: role, metadata: metadata, fallback: sequence.lanes[laneIndex].name)
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Assign Lane Role")
        playbackEngine.updateValidRanges(for: sequence)
        scheduleAutosave(reason: "assigned lane role")
        updateAgentState()
    }

    private func laneName(for role: String, metadata: VideoLaneMetadata, fallback: String) -> String {
        let label = metadata.sourceLabel?.isEmpty == false ? metadata.sourceLabel! : fallback
        let tracks = metadata.trackIds.isEmpty ? "" : "\(metadata.trackIds.joined(separator: ",")) "

        switch role {
        case "charlie_camera":
            return "Charlie Camera - \(label)"
        case "homer_camera":
            return "Homer Camera - \(label)"
        case "source_clip":
            return "Source Clip \(tracks)- \(label)".replacingOccurrences(of: "  ", with: " ")
        case "reference_clip":
            return "Reference Clip - \(label)"
        case "audio":
            return "Audio \(tracks)- \(label)".replacingOccurrences(of: "  ", with: " ")
        default:
            return label
        }
    }
    
    private func deleteSelectedTag() {
        guard let laneId = selectedLaneId,
              let tagId = selectedTagId,
              var sequence = projectStore.activeSequence,
              let laneIndex = sequence.lanes.firstIndex(where: { $0.id == laneId }) else {
