        sequence.lanes[laneIndex].tags.removeAll(where: { $0.id == tagId })
        selectedLaneId = nil
        selectedTagId = nil
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Delete Decision")
        playbackEngine.updateValidRanges(for: sequence)
        rebuildPlayer()
        lastMediaAction = "Deleted selected decision"
        scheduleAutosave(reason: "deleted decision")
        updateAgentState()
    }

    private func selectTag(laneId: String, tagId: String) {
        guard let sequence = projectStore.activeSequence,
              let lane = sequence.lanes.first(where: { laneMatches($0, laneId: laneId) }),
              let tag = lane.tags.first(where: { tagMatches($0, tagId: tagId) }) else {
