    }

    private func selectDecision(mode: String, laneId: String?, scope: String? = nil) {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Select decision failed: no active sequence"
            updateAgentState()
            return
        }

        let requestedMode = mode.lowercased().replacingOccurrences(of: "-", with: "_")
        let requestedScope = scope?.lowercased().replacingOccurrences(of: "-", with: "_") ?? ""
        let normalizedScope: String
        let normalizedMode: String

        if requestedMode.hasSuffix("_video") || requestedMode.hasSuffix("_visual") || requestedMode.hasSuffix("_source") {
            normalizedScope = "video"
            normalizedMode = requestedMode
                .replacingOccurrences(of: "_video", with: "")
                .replacingOccurrences(of: "_visual", with: "")
                .replacingOccurrences(of: "_source", with: "")
        } else if requestedMode.hasSuffix("_support") || requestedMode.hasSuffix("_audio") {
            normalizedScope = "support"
            normalizedMode = requestedMode
                .replacingOccurrences(of: "_support", with: "")
                .replacingOccurrences(of: "_audio", with: "")
        } else if ["video", "visual", "source"].contains(requestedScope) {
            normalizedScope = "video"
            normalizedMode = requestedMode
        } else if ["support", "audio", "context"].contains(requestedScope) {
            normalizedScope = "support"
            normalizedMode = requestedMode
        } else {
            normalizedScope = "all"
            normalizedMode = requestedMode
        }

        let lanes = sequence.lanes.filter { lane in
            if let laneId, !laneId.isEmpty, !laneMatches(lane, laneId: laneId) {
                return false
            }

            switch normalizedScope {
            case "video":
                return !isSupportOnlyLane(lane)
            case "support":
                return isSupportOnlyLane(lane)
            default:
                return true
            }
        }

        var candidates: [(lane: VideoLane, tag: VideoTag, sequenceTime: Double)] = []
        for lane in lanes {
            let offset = lane.sourceVideo?.offset ?? 0
            for tag in lane.tags where tag.type == .active || tag.type == .cut {
                candidates.append((lane, tag, offset + tag.startTime))
            }
        }

        guard !candidates.isEmpty else {
            let scopeLabel = normalizedScope == "all" ? "" : " \(normalizedScope)"
            lastMediaAction = "Select decision failed: no\(scopeLabel) SHOW/SKIP decisions found"
            updateAgentState()
            return
        }

        let playhead = playbackEngine.playhead
        let selected: (lane: VideoLane, tag: VideoTag, sequenceTime: Double)?

        if normalizedScope == "video",
           ["next", "previous", "prev", "first", "first_active"].contains(normalizedMode) {
            let boundaryMarkers = decisionBoundaryMarkers(scope: "video", laneId: laneId)
            let marker: DecisionMarker?
            switch normalizedMode {
            case "next":
                marker = boundaryMarkers
                    .first(where: { $0.sequenceTime > playhead + 0.05 })
                    ?? boundaryMarkers.first
            case "previous", "prev":
                marker = boundaryMarkers
                    .last(where: { $0.sequenceTime < playhead - 0.05 })
                    ?? boundaryMarkers.last
            default:
                marker = boundaryMarkers.first
            }

            if let marker,
               let lane = sequence.lanes.first(where: { $0.id == marker.laneId }),
               let tag = lane.tags.first(where: { $0.id == marker.tagId }) {
                selected = (lane, tag, marker.sequenceTime)
            } else {
                selected = nil
            }
        } else {
            switch normalizedMode {
            case "next":
                selected = candidates
                    .filter { $0.sequenceTime > playhead + 0.001 }
                    .min { $0.sequenceTime < $1.sequenceTime }
                    ?? candidates.min { $0.sequenceTime < $1.sequenceTime }
            case "previous", "prev":
                selected = candidates
                    .filter { $0.sequenceTime < playhead - 0.001 }
                    .max { $0.sequenceTime < $1.sequenceTime }
                    ?? candidates.max { $0.sequenceTime < $1.sequenceTime }
            case "first", "first_active":
                selected = candidates.min { $0.sequenceTime < $1.sequenceTime }
            case "at_playhead", "current":
            let atPlayhead = lanes.compactMap { lane -> (lane: VideoLane, tag: VideoTag, sequenceTime: Double)? in
                guard let tag = decisionAtPlayhead(for: lane) else { return nil }
                return (lane, tag, (lane.sourceVideo?.offset ?? 0) + tag.startTime)
            }
                selected = normalizedScope == "video"
                    ? (atPlayhead.first(where: { $0.tag.type == .active }) ?? atPlayhead.first
                        ?? candidates.min { abs($0.sequenceTime - playhead) < abs($1.sequenceTime - playhead) })
                    : (atPlayhead.first
                ?? candidates.min { abs($0.sequenceTime - playhead) < abs($1.sequenceTime - playhead) }
                    )
            default:
                selected = candidates.min { $0.sequenceTime < $1.sequenceTime }
            }
        }

        guard let selected else {
            lastMediaAction = "Select decision failed: no matching decision"
            updateAgentState()
            return
        }

        selectedLaneId = selected.lane.id
        selectedTagId = selected.tag.id
        playbackEngine.seek(to: max(0, selected.sequenceTime))
        lastMediaAction = String(
            format: "Selected %@ %@ decision via %@ at %.2fs on %@",
            selected.tag.type.rawValue.uppercased(),
            normalizedScope,
            normalizedMode,
            selected.sequenceTime,
            selected.lane.name
        )
        updateAgentState()
    }
    
    private func nudgeSelectedTag(by delta: Double) {
        guard let laneId = selectedLaneId,
              let tagId = selectedTagId,
              var sequence = projectStore.activeSequence,
              let laneIndex = sequence.lanes.firstIndex(where: { $0.id == laneId }),
              let tagIndex = sequence.lanes[laneIndex].tags.firstIndex(where: { $0.id == tagId }) else {
            return
        }
        
        let lane = sequence.lanes[laneIndex]
        let laneDuration = lane.sourceVideo?.duration ?? sequence.duration
        var tag = sequence.lanes[laneIndex].tags[tagIndex]
        tag.startTime = min(max(0, tag.startTime + delta), max(0, laneDuration - tag.duration))
        sequence.lanes[laneIndex].tags[tagIndex] = tag
        
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Nudge Decision")
        playbackEngine.updateValidRanges(for: sequence)
        playbackEngine.seek(to: (lane.sourceVideo?.offset ?? 0) + tag.startTime)
        rebuildPlayer()
        lastMediaAction = String(format: "Nudged selected decision to %.2fs", tag.startTime)
        scheduleAutosave(reason: "nudged decision")
        updateAgentState()
    }

    private func trimSelectedTag(startDelta: Double, durationDelta: Double) {
        guard let laneId = selectedLaneId,
              let tagId = selectedTagId,
              var sequence = projectStore.activeSequence,
              let laneIndex = sequence.lanes.firstIndex(where: { $0.id == laneId }),
              let tagIndex = sequence.lanes[laneIndex].tags.firstIndex(where: { $0.id == tagId }) else {
            lastMediaAction = "Trim decision failed: no selected decision"
            updateAgentState()
            return
        }

        let lane = sequence.lanes[laneIndex]
        let laneDuration = lane.sourceVideo?.duration ?? sequence.duration
        var tag = sequence.lanes[laneIndex].tags[tagIndex]
        let minimumDuration = 0.1
        let proposedStart = tag.startTime + startDelta
        let proposedDuration = tag.duration + durationDelta
        let boundedStart = min(max(0, proposedStart), max(0, laneDuration - minimumDuration))
        let boundedDuration = min(
            max(minimumDuration, proposedDuration),
            max(minimumDuration, laneDuration - boundedStart)
        )

        tag.startTime = boundedStart
        tag.duration = boundedDuration
        sequence.lanes[laneIndex].tags[tagIndex] = tag

        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Trim Decision")
        playbackEngine.updateValidRanges(for: sequence)
        playbackEngine.seek(to: (lane.sourceVideo?.offset ?? 0) + tag.startTime)
        rebuildPlayer()
        lastMediaAction = String(format: "Trimmed selected decision to %.2fs for %.2fs", tag.startTime, tag.duration)
        scheduleAutosave(reason: "trimmed decision")
        updateAgentState()
    }
    
    private func handleAgentCommandDispatch(fallbackToLegacy: Bool) {
        let queuedRequests = agentServer.drainCommandRequests()
        if !queuedRequests.isEmpty {
            lastDrainedAgentCommandSerial = agentServer.commandSerial
            for request in queuedRequests {
                handleAgentCommand(request)
            }
            agentServer.commandToExecute = ""
            updateAgentState()
            return
        }

        guard fallbackToLegacy else { return }
        handleLegacyAgentCommand()
    }

    private func handleAgentCommand(_ request: AgentCommandRequest) {
        switch request.name {
        case "load_demo":
            loadDemoEdit()
        case "import_file":
            if let path = request.values["path"] {
                loadVideoIntoProject(url: URL(fileURLWithPath: path), allowProtectedOriginalProbe: false)
            }
        case "load_premiere_packet":
            if let path = request.values["path"] {
                loadPremierePacket(url: URL(fileURLWithPath: path))
            }
        case "playback":
            applyAgentPlayback(
                mode: request.values["mode"],
                action: request.values["action"]
            )
        case "lane_role":
