        case "seek":
            if let rawTime = request.values["time"],
               let time = Double(rawTime) {
                playbackEngine.seek(to: max(0, time))
                lastMediaAction = String(format: "Seeked to %.2fs", max(0, time))
                updateAgentState()
            }
        case "scrub":
            if let rawTime = request.values["time"],
               let time = Double(rawTime) {
                playbackEngine.scrub(to: max(0, time))
                lastMediaAction = String(format: "Scrubbed to %.2fs", max(0, time))
                updateAgentState()
                Task { @MainActor in
                    try? await Task.sleep(nanoseconds: 300_000_000)
                    updateAgentState()
                }
            }
        case "program_scroll":
            if let rawDelta = request.values["delta"],
               let delta = Double(rawDelta) {
                scrubProgramMonitor(by: delta)
                Task { @MainActor in
