    private func exportFormat(from rawValue: String?) -> ExportFormat? {
        let normalized = (rawValue ?? "")
            .lowercased()
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: " ", with: "")
        switch normalized {
        case "16:9", "169", "wide", "horizontal", "landscape", "youtube":
            return .horizontal16x9
        case "9:16", "916", "vertical", "portrait", "reels", "shorts":
            return .vertical9x16
        default:
            return nil
        }
    }

    private func applyAgentSourceWindow(laneId: String, action: String?, duration: Double?) {
        guard let sequence = projectStore.activeSequence,
              let lane = sequence.lanes.first(where: { laneMatches($0, laneId: laneId) }) else {
            lastMediaAction = "Source-window decision failed: lane not found"
            updateAgentState()
            return
        }

        let normalizedAction = (action ?? "show").lowercased()
        let decisionType: TagType = ["cut", "skip", "hide", "inactive"].contains(normalizedAction) ? .cut : .active
        applySourceWallDecision(
            laneId: lane.id,
            type: decisionType,
            sequenceDuration: max(0.1, duration ?? 10)
        )
    }

    private func applyAgentSelectedDecisionSwitch(action: String?) {
        guard let action,
              let type = editDecisionType(from: action) else {
            lastMediaAction = "Selected decision switch failed: unknown action"
            updateAgentState()
            return
        }

        if !switchSelectedDecision(to: type) {
            lastMediaAction = "Selected decision switch failed: no selected SHOW/SKIP decision"
            updateAgentState()
        }
    }

    private func applyAgentPlayback(mode: String?, action: String?) {
        let requestedMode = playbackMode(from: mode)
        let requestedAction = (action ?? "toggle").lowercased()
        let modeIsChanging = playbackEngine.playbackMode != requestedMode

        if modeIsChanging {
            playbackEngine.playbackMode = requestedMode
            if let sequence = projectStore.activeSequence {
                playbackEngine.updateValidRanges(for: sequence)
            }

            let shouldResume = requestedAction != "pause" && requestedAction != "set"
            rebuildPlayer(resumeAfterRebuild: shouldResume)
            updateAgentState()
            return
        }

        switch requestedAction {
        case "play":
            playbackEngine.play()
        case "pause", "set":
            playbackEngine.pause()
        default:
            playbackEngine.togglePlayback()
        }
        updateAgentState()
    }

    private func playbackMode(from value: String?) -> PlaybackMode {
        switch (value ?? "edit").lowercased() {
        case "through", "playthrough", "play-through", "play_through", "all", "raw":
            return .playThrough
        default:
            return .playEdit
        }
    }
    
    private func applyAgentEdit(laneId: String, action: String, value1: Double?, value2: Double?) {
        guard var seq = projectStore.activeSequence,
              let laneIndex = seq.lanes.firstIndex(where: { laneMatches($0, laneId: laneId) }) else {
            return
        }
        
        switch action.lowercased() {
        case "offset":
            guard let offset = value1 else { return }
            guard var source = seq.lanes[laneIndex].sourceVideo else { return }
            source.offset = offset
            seq.lanes[laneIndex].sourceVideo = source
        case "clear_tags":
            seq.lanes[laneIndex].tags.removeAll()
        default:
            guard let tagType = agentTagType(from: action) else { return }
            let start = max(0, value1 ?? playbackEngine.playhead)
            let duration = max(0.1, value2 ?? 5)
            seq.lanes[laneIndex].tags.append(VideoTag(type: tagType, startTime: start, duration: duration))
        }
        
        projectStore.updateSequence(seq, undoManager: nil, actionName: "Agent Edit")
        rebuildPlayer()
        scheduleAutosave(reason: "agent edit")
    }
    
    private func applyAgentDecision(_ decision: String, start: Double?, duration: Double?) {
        guard var seq = projectStore.activeSequence else { return }
        
        let normalized = decision
            .lowercased()
            .replacingOccurrences(of: " ", with: "")
            .replacingOccurrences(of: "_", with: "")
            .replacingOccurrences(of: "-", with: "")
            .replacingOccurrences(of: "+", with: "")
        let sequenceStart = max(0, start ?? playbackEngine.playhead)
        let sequenceDuration = max(0.1, duration ?? 5)
        let sequenceEnd = sequenceStart + sequenceDuration
        var preferredSelectedDecision: (laneId: UUID, tagId: UUID, isSupportOnly: Bool)? = nil
        var fallbackSelectedDecision: (laneId: UUID, tagId: UUID, isSupportOnly: Bool)? = nil

        func appendDecision(to laneIndex: Int, type: TagType) {
            guard seq.lanes.indices.contains(laneIndex) else { return }
            let offset = seq.lanes[laneIndex].sourceVideo?.offset ?? 0
            let laneDuration = max(0, seq.lanes[laneIndex].duration)
            guard laneDuration > 0 else { return }

            let localStart = max(0, sequenceStart - offset)
            let localEnd = min(laneDuration, sequenceEnd - offset)
            let boundedDuration = localEnd - localStart
            guard boundedDuration >= 0.05 else { return }

            let newTag = VideoTag(type: type, startTime: localStart, duration: boundedDuration)
            seq.lanes[laneIndex].tags.append(newTag)
            let candidateIsSupportOnly = isSupportOnlyLane(seq.lanes[laneIndex])
            let selected = (seq.lanes[laneIndex].id, newTag.id, candidateIsSupportOnly)
            if type == .active {
                if preferredSelectedDecision == nil || preferredSelectedDecision?.isSupportOnly == true && !candidateIsSupportOnly {
                    preferredSelectedDecision = selected
                }
            } else if fallbackSelectedDecision == nil || fallbackSelectedDecision?.isSupportOnly == true && !candidateIsSupportOnly {
                fallbackSelectedDecision = selected
            }
        }
        
        for index in seq.lanes.indices {
            let shouldActivate: Bool
            let shouldCut: Bool
            
            switch normalized {
            case "charlie":
                shouldActivate = laneMatchesDecisionCategory(seq.lanes[index], "charlie")
                shouldCut = !shouldActivate
            case "homer":
                shouldActivate = laneMatchesDecisionCategory(seq.lanes[index], "homer")
                shouldCut = !shouldActivate
            case "both":
                shouldActivate = laneMatchesDecisionCategory(seq.lanes[index], "charlie") ||
                    laneMatchesDecisionCategory(seq.lanes[index], "homer")
                shouldCut = false
            case "skip", "skipover":
                shouldActivate = false
                shouldCut = true
            case "charlieclip":
                shouldActivate = laneMatchesDecisionCategory(seq.lanes[index], "charlie") ||
                    laneMatchesDecisionCategory(seq.lanes[index], "clip")
                shouldCut = !shouldActivate
            case "homerclip":
                shouldActivate = laneMatchesDecisionCategory(seq.lanes[index], "homer") ||
                    laneMatchesDecisionCategory(seq.lanes[index], "clip")
                shouldCut = !shouldActivate
            default:
                shouldActivate = false
                shouldCut = false
            }
            
            if shouldActivate {
                appendDecision(to: index, type: .active)
            } else if shouldCut {
                appendDecision(to: index, type: .cut)
            }
        }
        
        projectStore.updateSequence(seq, undoManager: nil, actionName: "Agent Decision")
        if let selectedDecision = preferredSelectedDecision ?? fallbackSelectedDecision {
            selectedLaneId = selectedDecision.laneId
            selectedTagId = selectedDecision.tagId
        }
        playbackEngine.updateValidRanges(for: seq)
        rebuildPlayer()
        lastMediaAction = String(format: "Added %@ decision at %.2fs for %.2fs", normalized, sequenceStart, sequenceDuration)
        scheduleAutosave(reason: "agent decision")
        updateAgentState()
    }
    
    private func laneMatches(_ lane: VideoLane, laneId: String) -> Bool {
        lane.id.uuidString.caseInsensitiveCompare(laneId) == .orderedSame ||
        lane.name.caseInsensitiveCompare(laneId) == .orderedSame ||
        lane.name.lowercased().contains(laneId.lowercased())
    }

    private func tagMatches(_ tag: VideoTag, tagId: String) -> Bool {
        tag.id.uuidString.caseInsensitiveCompare(tagId) == .orderedSame ||
        tag.id.uuidString.lowercased().hasPrefix(tagId.lowercased())
    }
    
    private func agentTagType(from action: String) -> TagType? {
        switch action.lowercased() {
        case "active", "activate", "keep":
            return .active
        case "cut", "inactive", "skip":
            return .cut
        case "highlight":
            return .highlight
        case "focus":
            return .focus
        case "meme":
            return .meme
        default:
            return nil
        }
    }
    
    enum EditDecisionType {
        case charlie, homer, both, skip, charlieClip, homerClip
    }

    private func editDecisionType(from value: String) -> EditDecisionType? {
        let normalized = value
            .lowercased()
            .replacingOccurrences(of: " ", with: "")
            .replacingOccurrences(of: "_", with: "")
            .replacingOccurrences(of: "-", with: "")
            .replacingOccurrences(of: "+", with: "")

        switch normalized {
        case "charlie", "c":
            return .charlie
        case "homer", "h":
            return .homer
        case "both", "two", "twoshot":
            return .both
        case "skip", "skipover", "cut", "gap":
            return .skip
        case "charlieclip", "cclip":
            return .charlieClip
        case "homerclip", "hclip":
            return .homerClip
        default:
            return nil
        }
    }
    
    private func applyDecision(_ type: EditDecisionType) {
        if switchSelectedDecision(to: type) {
            return
        }

        guard var sequence = projectStore.activeSequence else { return }
        
        let splitTime = playbackEngine.playhead
        
        for i in 0..<sequence.lanes.count {
            let offset = sequence.lanes[i].sourceVideo?.offset ?? 0
            var newTags: [VideoTag] = []
            
            for tag in sequence.lanes[i].tags {
                if tag.type == .active || tag.type == .cut {
                    let tagStartSeq = tag.startTime + offset
                    let tagEndSeq = tagStartSeq + tag.duration
                    
                    if tagEndSeq <= splitTime {
                        newTags.append(tag)
                    } else if tagStartSeq < splitTime {
                        var trimmedTag = tag
                        trimmedTag.duration = splitTime - tagStartSeq
                        newTags.append(trimmedTag)
                    }
                } else {
                    newTags.append(tag)
                }
            }
            sequence.lanes[i].tags = newTags
        }
        
        let remainingDuration = sequence.duration - splitTime
        guard remainingDuration > 0 else { return }
        var lastSelectedDecision: (laneId: UUID, tagId: UUID, isSupportOnly: Bool)? = nil

        func rememberSelectedDecision(laneIndex: Int, tagId: UUID) {
            guard laneIndex < sequence.lanes.count else { return }
            let isSupportOnly = isSupportOnlyLane(sequence.lanes[laneIndex])
            if lastSelectedDecision == nil || lastSelectedDecision?.isSupportOnly == true && !isSupportOnly {
                lastSelectedDecision = (sequence.lanes[laneIndex].id, tagId, isSupportOnly)
            }
        }
        
        func activate(laneIndex: Int) {
            guard laneIndex < sequence.lanes.count else { return }
            let offset = sequence.lanes[laneIndex].sourceVideo?.offset ?? 0
            let newTag = VideoTag(type: .active, startTime: splitTime - offset, duration: remainingDuration)
            sequence.lanes[laneIndex].tags.append(newTag)
            rememberSelectedDecision(laneIndex: laneIndex, tagId: newTag.id)
        }

        func skip(laneIndex: Int) {
            guard laneIndex < sequence.lanes.count else { return }
            let offset = sequence.lanes[laneIndex].sourceVideo?.offset ?? 0
            let newTag = VideoTag(type: .cut, startTime: splitTime - offset, duration: remainingDuration)
            sequence.lanes[laneIndex].tags.append(newTag)
            rememberSelectedDecision(laneIndex: laneIndex, tagId: newTag.id)
        }
        
        let charlieLanes = laneIndices(in: sequence, matching: "charlie", fallback: [0])
        let homerLanes = laneIndices(in: sequence, matching: "homer", fallback: [1])
        let clipLanes = laneIndices(in: sequence, matching: "clip", fallback: [2])

        func activate(_ laneIndices: [Int]) {
            for laneIndex in laneIndices {
                activate(laneIndex: laneIndex)
            }
        }

        switch type {
        case .charlie:
            activate(charlieLanes)
        case .homer:
            activate(homerLanes)
        case .both:
            activate(uniqueLaneIndices(charlieLanes + homerLanes))
        case .skip:
            for index in sequence.lanes.indices {
                skip(laneIndex: index)
            }
        case .charlieClip:
            activate(uniqueLaneIndices(charlieLanes + clipLanes))
        case .homerClip:
            activate(uniqueLaneIndices(homerLanes + clipLanes))
        }
        
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Edit Decision")
        if let lastSelectedDecision {
            selectedLaneId = lastSelectedDecision.laneId
            selectedTagId = lastSelectedDecision.tagId
        }
        playbackEngine.updateValidRanges(for: sequence)
        rebuildPlayer()
        scheduleAutosave(reason: "live switch decision")
    }

    @discardableResult
    private func switchSelectedDecision(to type: EditDecisionType) -> Bool {
        guard let selected = selectedDecision(),
              let sequence = projectStore.activeSequence else {
            return false
        }

        let sequenceStart = max(0, (selected.lane.sourceVideo?.offset ?? 0) + selected.tag.startTime)
        let sequenceDuration = max(0.1, selected.tag.duration)
        let showLaneIds = type == .skip ? [] : laneIdsForDecisionType(type, in: sequence)
        let decisionMap = visualDecisionMap(
            in: sequence,
            showLaneIds: showLaneIds,
            cutOtherVisuals: true
        )

        applyDecisionWindowMap(
            decisionMap,
            sequenceStart: sequenceStart,
            sequenceDuration: sequenceDuration,
            actionName: "Switch Selected Decision",
            autosaveReason: "switched selected decision",
            mediaActionLabel: labelForDecisionType(type)
        )
        return true
    }

    private func laneIdsForDecisionType(_ type: EditDecisionType, in sequence: MediaSequence) -> Set<UUID> {
        switch type {
        case .charlie:
            return Set(laneIndices(in: sequence, matching: "charlie", fallback: [0]).map { sequence.lanes[$0].id })
        case .homer:
            return Set(laneIndices(in: sequence, matching: "homer", fallback: [1]).map { sequence.lanes[$0].id })
        case .both:
            return Set(uniqueLaneIndices(
                laneIndices(in: sequence, matching: "charlie", fallback: [0]) +
                laneIndices(in: sequence, matching: "homer", fallback: [1])
            ).map { sequence.lanes[$0].id })
        case .skip:
            return []
        case .charlieClip:
            return Set(uniqueLaneIndices(
                laneIndices(in: sequence, matching: "charlie", fallback: [0]) +
                laneIndices(in: sequence, matching: "clip", fallback: [2])
            ).map { sequence.lanes[$0].id })
        case .homerClip:
            return Set(uniqueLaneIndices(
                laneIndices(in: sequence, matching: "homer", fallback: [1]) +
                laneIndices(in: sequence, matching: "clip", fallback: [2])
            ).map { sequence.lanes[$0].id })
        }
    }

    private func labelForDecisionType(_ type: EditDecisionType) -> String {
        switch type {
        case .charlie:
            return "Switched selected span to Charlie"
        case .homer:
            return "Switched selected span to Homer"
        case .both:
            return "Switched selected span to Both"
        case .skip:
            return "Switched selected span to Skip"
        case .charlieClip:
            return "Switched selected span to Charlie + Clip"
        case .homerClip:
            return "Switched selected span to Homer + Clip"
        }
    }

    private func visualDecisionMap(
        in sequence: MediaSequence,
        showLaneIds: Set<UUID>,
        cutOtherVisuals: Bool
    ) -> [UUID: TagType] {
        var map: [UUID: TagType] = [:]
        for lane in sequence.lanes where !isSupportOnlyLane(lane) {
            if showLaneIds.contains(lane.id) {
                map[lane.id] = .active
            } else if cutOtherVisuals {
                map[lane.id] = .cut
            }
        }
        return map
    }

    private func laneIndices(in sequence: MediaSequence, matching nameFragment: String, fallback: [Int]) -> [Int] {
        let lowercasedFragment = nameFragment.lowercased()
        let roleMatches = sequence.lanes.indices.filter { index in
            laneMatchesDecisionCategory(sequence.lanes[index], lowercasedFragment)
        }

        if !roleMatches.isEmpty {
            return Array(roleMatches)
        }

        let namedMatches = sequence.lanes.indices.filter { index in
            let lane = sequence.lanes[index]
            if lowercasedFragment == "clip", lane.metadata?.role == "unresolved_camera" {
                return false
            }
            return lane.name.lowercased().contains(lowercasedFragment)
        }

        if !namedMatches.isEmpty {
            return Array(namedMatches)
        }

        return fallback.filter { sequence.lanes.indices.contains($0) }
    }

    private func laneMatchesDecisionCategory(_ lane: VideoLane, _ category: String) -> Bool {
        let role = lane.metadata?.role.lowercased() ?? ""
        let name = lane.name.lowercased()

        switch category.lowercased() {
        case "charlie":
            return role.contains("charlie") || (lane.metadata == nil && name.contains("charlie"))
        case "homer":
            return role.contains("homer") || (lane.metadata == nil && name.contains("homer"))
        case "clip":
            return role == "reference_clip" || role == "source_clip" || (lane.metadata == nil && name.contains("clip"))
        default:
            return role.contains(category.lowercased()) || name.contains(category.lowercased())
        }
    }

    private func uniqueLaneIndices(_ indices: [Int]) -> [Int] {
        Array(Set(indices)).sorted()
    }

    #if os(macOS)
    private func installKeyboardMonitorIfNeeded() {
        guard keyMonitor == nil else { return }
        keyMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { event in
            handleKeyboardEvent(event) ? nil : event
        }
    }

    private func removeKeyboardMonitor() {
        if let keyMonitor {
            NSEvent.removeMonitor(keyMonitor)
            self.keyMonitor = nil
        }
    }

    private func installProgramScrollMonitorIfNeeded() {
        guard programScrollMonitor == nil else { return }
        programScrollMonitor = NSEvent.addLocalMonitorForEvents(matching: .scrollWheel) { event in
            guard isPointerOverProgramMonitor else {
                return event
            }

            if NSApp.keyWindow?.firstResponder is NSTextView {
                return event
            }

            let flags = event.modifierFlags.intersection([.command, .control, .option])
            guard flags.isEmpty else {
                return event
            }

            let delta = programScrollScrubSeconds(from: event)
            guard abs(delta) > 0.001 else {
                return event
            }

            scrubProgramMonitor(by: delta)
            return nil
        }
    }

    private func removeProgramScrollMonitor() {
        if let programScrollMonitor {
            NSEvent.removeMonitor(programScrollMonitor)
            self.programScrollMonitor = nil
        }
        isPointerOverProgramMonitor = false
    }

    private func programScrollScrubSeconds(from event: NSEvent) -> Double {
        let dominantDelta = abs(event.scrollingDeltaX) > abs(event.scrollingDeltaY)
            ? event.scrollingDeltaX
            : -event.scrollingDeltaY
        let sensitivity = event.hasPreciseScrollingDeltas ? 0.055 : 0.35
        return max(-12, min(12, dominantDelta * sensitivity))
    }

    private func handleKeyboardEvent(_ event: NSEvent) -> Bool {
        if NSApp.keyWindow?.firstResponder is NSTextView {
            return false
        }

        let flags = event.modifierFlags.intersection([.command, .control, .option])
        guard flags.isEmpty else { return false }
        
        if event.keyCode == 51 || event.keyCode == 117 {
            deleteSelectedTag()
            return true
        }
        
        if event.keyCode == 53 {
            clearSelection()
            return true
        }

        switch event.charactersIgnoringModifiers?.lowercased() {
        case "j":
            playbackEngine.seek(to: max(0, playbackEngine.playhead - 5))
            updateAgentState()
            return true
        case "k":
            playbackEngine.pause()
            updateAgentState()
            return true
        case " ":
            handlePlaybackModeRequest(.playEdit)
            updateAgentState()
            return true
        case "t":
            handlePlaybackModeRequest(.playThrough)
            updateAgentState()
            return true
        case "l":
            playbackEngine.seek(to: playbackEngine.playhead + 5)
            updateAgentState()
            return true
        case "-", "_":
            applyTimelineZoom(mode: "out", scale: nil)
            return true
        case "=", "+":
            applyTimelineZoom(mode: "in", scale: nil)
            return true
        case "0":
            applyTimelineZoom(mode: "fit", scale: nil)
            return true
        case "\\":
            applyTimelineZoom(mode: "frame", scale: nil)
            return true
        case ",", "<":
            nudgeSelectedTag(by: -0.1)
            return true
        case ".", ">":
            nudgeSelectedTag(by: 0.1)
            return true
        case "q":
            trimSelectedTag(startDelta: -0.1, durationDelta: 0.1)
            return true
        case "w":
            trimSelectedTag(startDelta: 0.1, durationDelta: -0.1)
            return true
        case "o":
            trimSelectedTag(startDelta: 0, durationDelta: -0.1)
            return true
        case "p":
            trimSelectedTag(startDelta: 0, durationDelta: 0.1)
            return true
        case "[":
            jumpToAdjacentDecision(direction: -1, scope: "video")
            return true
        case "]":
            jumpToAdjacentDecision(direction: 1, scope: "video")
            return true
        case "m":
            selectFirstMediaIssue()
            return true
        case "1":
            applyDecision(.charlie)
            return true
        case "2":
            applyDecision(.homer)
            return true
        case "3":
            applyDecision(.both)
            return true
        case "4":
            applyDecision(.skip)
            return true
        case "5":
            applyDecision(.charlieClip)
            return true
        case "6":
            applyDecision(.homerClip)
            return true
        default:
            return false
        }
    }
    #endif

