    private func agentCapabilityParityPayload(
        sequenceLoaded: Bool,
        readinessSummary: MediaReadinessSummary?
    ) -> [[String: Any]] {
        let videoReady = readinessSummary?.isVideoRoughCutReady ?? false
        let productionReady = readinessSummary?.isProductionReady ?? false
        let mediaBlocked = (readinessSummary?.videoBlockedCount ?? 0) > 0
            || (readinessSummary?.audioBlockedCount ?? 0) > 0
            || (readinessSummary?.proxyBlockedCount ?? 0) > 0

        func capability(
            _ id: String,
            _ humanWorkflow: String,
            observe: [String],
            act: [String],
            prove: [String],
            ready: Bool,
            status: String,
            trainingValue: String
        ) -> [String: Any] {
            [
                "id": id,
                "humanWorkflow": humanWorkflow,
                "agentCanObserve": observe,
                "agentCanActWith": act,
                "agentCanProveWith": prove,
                "readyForAgents": ready,
                "parityStatus": status,
                "trainingValue": trainingValue
            ]
        }

        return [
            capability(
                "monitor-wall-scrub",
                "Scrub the timeline and see program output plus synced source monitors",
                observe: ["playhead", "sourcePlayerTimeSeconds", "expectedSourcePlayerTimeSeconds", "sourcePlayerDeltaSeconds", "sourceMonitorVideoCount"],
                act: ["GET /scrub?time=<seconds>", "GET /seek?time=<seconds>", "GET /program_scroll?delta=<seconds>", "GET /focus_monitors"],
                prove: ["GET /state", "GET /editor_snapshot"],
                ready: sequenceLoaded && videoReady,
                status: sequenceLoaded ? (videoReady ? "ready" : "needs_proxy_or_media_recovery") : "needs_sequence",
                trainingValue: "Teaches models that sequence time drives all source monitors without chopping source lanes."
            ),
            capability(
                "play-edit-through",
                "Play the edited output or play through the whole synced timeline",
                observe: ["playbackMode", "validRangeCount", "currentProgramTitle", "currentProgramDetail"],
                act: ["GET /playback?mode=edit&action=play", "GET /playback?mode=through&action=play", "GET /playback?mode=edit&action=set"],
                prove: ["GET /editor_snapshot", "GET /state"],
                ready: sequenceLoaded && videoReady,
                status: sequenceLoaded ? (videoReady ? "ready" : "needs_visual_sources") : "needs_sequence",
                trainingValue: "Preserves the core Quipsly distinction between raw synced review and gap-skipping edit playback."
            ),
            capability(
                "visual-decision-editing",
                "Review grouped visual edit boundaries, then nudge/trim/delete the selected SHOW/SKIP lane metadata",
                observe: ["selectedTagId", "selectedTagType", "selectedTagStart", "selectedTagDuration", "selectedTagLaneName", "visualDecisionBoundaryModel", "visualDecisionCount", "selectedVisualDecisionIndex", "selectedVisualDecisionSequenceTime", "selectedSourceReviewStopCount", "showDecisionCount", "skipDecisionCount"],
                act: ["GET /select_decision?mode=previous_video", "GET /select_decision?mode=previous_video&lane_id=<selected-source>", "GET /select_decision?mode=at_playhead&scope=video", "GET /select_decision?mode=next_video&lane_id=<selected-source>", "GET /select_decision?mode=next_video", "GET /nudge_selected?delta=-1", "GET /nudge_selected?delta=-0.1", "GET /nudge_selected?delta=0.1", "GET /nudge_selected?delta=1", "GET /trim_selected?start_delta=-0.1&duration_delta=0.1", "GET /trim_selected?start_delta=0.1&duration_delta=-0.1", "GET /trim_selected?start_delta=0&duration_delta=-0.1", "GET /trim_selected?start_delta=0&duration_delta=0.1", "GET /delete_selected_tag"],
                prove: ["GET /state", "GET /editor_snapshot"],
                ready: sequenceLoaded,
                status: sequenceLoaded ? "ready" : "needs_sequence",
                trainingValue: "Teaches the distinction between grouped review stops for fast navigation and lane-level metadata tags for precise non-destructive edits."
            ),
            capability(
                "source-window-live-switching",
                "Choose which source appears for a duration at the playhead",
                observe: ["selectedLaneName", "selectedTagId", "selectedTagType", "playhead", "lanes.role", "lanes.activeCount", "lanes.cutCount"],
                act: ["GET /select_lane?lane_id=<uuid-or-name>", "GET /source_window?lane_id=<uuid-or-name>&action=show&duration=<seconds>", "GET /source_window?lane_id=<uuid-or-name>&action=cut&duration=<seconds>", "GET /switch_selected_decision?action=charlie|homer|both|skip|charlieClip|homerClip"],
                prove: ["GET /state", "GET /editor_snapshot"],
                ready: sequenceLoaded && videoReady,
                status: sequenceLoaded ? (videoReady ? "ready" : "needs_video_sources") : "needs_sequence",
                trainingValue: "Captures camera-switch intent as metadata over full synced lanes, including retargeting an existing selected edit span without chopping media."
            ),
            capability(
                "timeline-precision-navigation",
                "Zoom and focus the decision timeline for fine-grained edits",
                observe: ["timelinePixelsPerSecond", "timelineFitToWindow", "timelineFocusBehavior"],
                act: ["GET /focus_timeline", "GET /timeline_zoom?mode=precision", "GET /timeline_zoom?mode=set&scale=<pixels-per-second>"],
                prove: ["GET /state"],
                ready: sequenceLoaded,
                status: sequenceLoaded ? "ready" : "needs_sequence",
                trainingValue: "Lets models request inspectable context before changing dense edit boundaries."
            ),
            capability(
                "output-format-reframing",
                "Switch program output between landscape and vertical preview",
                observe: ["playbackFormat", "currentProgramTitle", "currentProgramDetail"],
                act: ["GET /format?value=16:9", "GET /format?value=9:16"],
                prove: ["GET /state", "GET /editor_snapshot"],
                ready: sequenceLoaded,
                status: sequenceLoaded ? "ready" : "needs_sequence",
                trainingValue: "Keeps output decisions explicit and inspectable before later keyframe/reframe automation."
            ),
            capability(
                "media-readiness-recovery",
                "Understand whether imported sources are proxy-safe, blocked, or need operator intent",
                observe: ["mediaRecoveryReport", "videoProxyReadyCount", "videoBlockedCount", "audioBlockedCount", "storageAccessNeededCount"],
                act: ["GET /match_folder?path=<absolute-folder-path>", "GET /retry_proxies", "GET /relink_lane?lane_id=<uuid-or-name>&path=<absolute-file-path>", "GET /vault_lane?lane_id=<uuid-or-name>"],
                prove: ["GET /state", "GET /editor_snapshot"],
                ready: sequenceLoaded && !mediaBlocked && productionReady,
                status: sequenceLoaded ? (mediaBlocked ? "operator_intent_required" : "ready") : "needs_sequence",
                trainingValue: "Prevents agents from touching protected originals or launching proxy storms without explicit recovery context."
            )
        ]
    }

    private func agentCurrentContextPayload(
        sequenceLoaded: Bool,
        selectedLaneName: String,
        selectedTagType: String,
        programSummary: (String, String)
    ) -> [String: Any] {
        [
            "sequenceLoaded": sequenceLoaded,
            "currentProgramTitle": programSummary.0,
            "currentProgramDetail": programSummary.1,
            "selectedLaneName": selectedLaneName,
            "selectedTagType": selectedTagType,
            "agentRule": "Never infer by screen position when /state has semantic truth. Source lanes stay whole; SHOW/SKIP are metadata overlays."
        ]
    }

    private func agentOperatingProtocolPayload() -> [[String: Any]] {
        [
            [
                "step": 1,
                "name": "observe",
                "endpoint": "GET /state",
                "proof": "Read current program state, selected lane/tag, readiness, safe actions, and editorProofSnapshot."
            ],
            [
                "step": 2,
                "name": "choose_semantic_action",
                "endpoint": "Read agentCurrentSafeActions",
                "proof": "Use agentCapabilityParity and named editor concepts instead of screen coordinates: select lane, source window, trim selected, zoom timeline, set format."
            ],
            [
                "step": 3,
                "name": "execute",
                "endpoint": "GET one semantic command",
                "proof": "Prefer one small action, then re-observe before taking the next action."
            ],
            [
                "step": 4,
                "name": "reobserve",
                "endpoint": "GET /editor_snapshot and GET /state",
                "proof": "Confirm source monitors, Play Edit, proxy-first status, selected state, and decision counts."
            ]
        ]
    }

    private func agentTrainingDataContractPayload() -> [String: Any] {
        [
            "goal": "Capture editor work as state/action/proof examples that can teach models how this editor works.",
            "humanParityRule": "Every serious human editing affordance should eventually have a matching state field and semantic command.",
            "preferredRecordShape": [
                "capability": "agentCapabilityParity item id",
                "beforeState": "GET /state",
                "action": "endpoint plus parameters",
                "response": "endpoint response",
                "afterState": "GET /state",
                "proof": "GET /editor_snapshot"
            ],
            "accessibilityRule": "If a human can do an important edit through visible controls, an agent should have equivalent observable state, a semantic command, and a proof path.",
            "nonDestructiveRule": "SHOW/SKIP/source-window/trim operations alter metadata decisions over whole lanes. They do not cut originals or proxies.",
            "forbiddenShortcut": "Do not train agents to click by screen coordinates when semantic editor truth exists."
        ]
    }

