                    semanticCommands: ["GET /match_folder?path=<absolute-folder-path>", "GET /retry_proxies", "GET /relink_lane?lane_id=<uuid-or-name>&path=<absolute-file-path>", "GET /export_proxy_package?directory=<absolute-output-folder>&basename=<name>&proof_seconds=<seconds>"],
                    proof: ["GET /state", "GET /editor_snapshot"],
                    physicalProof: ["Computer Use: inspect readiness panel only after /state says what is blocked"],
                    ready: sequenceLoaded && productionReady,
                    notes: "This surface prevents false confidence and prevents agents from asking for raw-file access prematurely."
                )
            ]
        ]
    }

